  );
};

export default Toolbar;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  CircuitNode, 
  Wire, 
  Camera, 
  InteractionMode, 
  InteractionState, 
  GateType,
  Position
} from './types';
import { COMPONENT_CONFIGS, COLORS } from './constants';
import { renderCircuit, screenToWorld, worldToScreen } from './services/renderer';
import { propagateCircuit } from './services/circuitEngine';
import Toolbar from './components/Toolbar';
import { v4 as uuidv4 } from 'uuid'; // Normally use library, using simplified random here

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // State
  const [nodes, setNodes] = useState<CircuitNode[]>([]);
  const [wires, setWires] = useState<Wire[]>([]);
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, zoom: 1 });

  // Interaction State
  const [interaction, setInteraction] = useState<InteractionState>({
    mode: InteractionMode.IDLE,
    hoveredNodeId: null,
    hoveredPin: null,
    dragStart: { x: 0, y: 0 },
    dragOffset: { x: 0, y: 0 },
    activeWireStart: null,
    placingType: null,
  });

  // Refs for items needed inside event listeners/loops without triggering re-renders
  const nodesRef = useRef(nodes);
  const wiresRef = useRef(wires);
  const interactionRef = useRef(interaction);
  const cameraRef = useRef(camera);
  const mousePosRef = useRef<Position>({ x: 0, y: 0 });

  // Sync refs
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { wiresRef.current = wires; }, [wires]);
  useEffect(() => { interactionRef.current = interaction; }, [interaction]);
  useEffect(() => { cameraRef.current = camera; }, [camera]);

  // Main Logic Loop (Clock & Propagation)
  useEffect(() => {
    const interval = setInterval(() => {
      let needsUpdate = false;
      const currentNodes = [...nodesRef.current];

      // Handle Clock Components
      currentNodes.forEach(node => {
        if (node.type === GateType.CLOCK) {
          node.state = !node.state;
          needsUpdate = true;
        }
      });

      if (needsUpdate) {
        const result = propagateCircuit(currentNodes, wiresRef.current);
        setNodes(result.nodes);
        setWires(result.wires);
      }
    }, 500); // 500ms Clock tick

    return () => clearInterval(interval);
  }, []);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;

    const render = () => {
      // Handle resize
      if (containerRef.current) {
        canvas.width = containerRef.current.clientWidth;
        canvas.height = containerRef.current.clientHeight;
      }

      // Draw active wire line if dragging
      const currentInteraction = interactionRef.current;

      renderCircuit(
        canvas, 
        ctx, 
        nodesRef.current, 
        wiresRef.current, 
        cameraRef.current, 
        currentInteraction
      );

      // Draw dragging wire line
      if (currentInteraction.mode === InteractionMode.WIRING && currentInteraction.activeWireStart) {
        const { nodeId } = currentInteraction.activeWireStart;
        const node = nodesRef.current.find(n => n.id === nodeId);
        if (node) {
          const startX = node.position.x + node.width;
          const startY = node.position.y + node.height / 2;
          const s = worldToScreen(startX, startY, cameraRef.current);

          ctx.beginPath();
          ctx.moveTo(s.x, s.y);
          ctx.lineTo(mousePosRef.current.x, mousePosRef.current.y);
          ctx.strokeStyle = COLORS.wireActive;
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, []);

  // --- Interaction Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const worldPos = screenToWorld(x, y, camera);

    // Right click for panning
    if (e.button === 2) {
      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.PANNING,
        dragStart: { x, y }
      }));
      return;
    }

    // Placing Mode
    if (interaction.mode === InteractionMode.PLACING && interaction.placingType) {
      const config = COMPONENT_CONFIGS[interaction.placingType];
      const newNode: CircuitNode = {
        id: generateId(),
        type: interaction.placingType,
        position: { x: worldPos.x - config.width/2, y: worldPos.y - config.height/2 },
        width: config.width,
        height: config.height,
        inputs: new Array(config.inputCount).fill(false),
        state: false,
        label: config.label
      };

      setNodes(prev => [...prev, newNode]);
      // Don't reset mode to allow multiple placements, or reset if desired.
      // Let's keep placing.
      return;
    }

    // Wiring Mode Check (Pin Click)
    if (interaction.hoveredPin) {
      if (interaction.hoveredPin.type === 'output') {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.WIRING,
          activeWireStart: { nodeId: prev.hoveredPin!.nodeId, pinIndex: prev.hoveredPin!.index }
        }));
      }
      return;
    }

    // Switch Toggle Check
    if (interaction.hoveredNodeId) {
      const node = nodes.find(n => n.id === interaction.hoveredNodeId);
      if (node && node.type === GateType.INPUT_SWITCH) {
        const newNodes = nodes.map(n => 
          n.id === node.id ? { ...n, state: !n.state } : n
        );
        const res = propagateCircuit(newNodes, wires);
        setNodes(res.nodes);
        setWires(res.wires);
        return;
      }
    }

    // Drag Node Check
    if (interaction.hoveredNodeId) {
      const node = nodes.find(n => n.id === interaction.hoveredNodeId);
      if (node) {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.DRAGGING_NODE,
          dragOffset: { 
            x: worldPos.x - node.position.x, 
            y: worldPos.y - node.position.y 
          }
        }));
      }
      return;
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    // Panning
    if (interaction.mode === InteractionMode.PANNING) {
      const dx = x - interaction.dragStart.x;
      const dy = y - interaction.dragStart.y;
      setCamera(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
      setInteraction(prev => ({ ...prev, dragStart: { x, y } }));
      return;
    }

    // Dragging Node
    if (interaction.mode === InteractionMode.DRAGGING_NODE && interaction.hoveredNodeId) {
      const worldPos = screenToWorld(x, y, camera);
      setNodes(prev => prev.map(n => 
        n.id === interaction.hoveredNodeId 
          ? { ...n, position: { x: worldPos.x - interaction.dragOffset.x, y: worldPos.y - interaction.dragOffset.y } } 
          : n
      ));
      return;
    }

    // Hover Detection
    if (interaction.mode === InteractionMode.IDLE || interaction.mode === InteractionMode.WIRING || interaction.mode === InteractionMode.PLACING) {
      const worldPos = screenToWorld(x, y, camera);
      let foundNodeId: string | null = null;
      let foundPin: InteractionState['hoveredPin'] = null;

      // Reverse iterate for top-most check
      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];

        // Check Pins first (Hitbox radius 10)
        const config = COMPONENT_CONFIGS[node.type];

        // Inputs
        const pinSpacingIn = node.height / (config.inputCount + 1);
        for (let p = 0; p < config.inputCount; p++) {
          const px = node.position.x;
          const py = node.position.y + (pinSpacingIn * (p + 1));
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'input', index: p };
            break;
          }
        }
        if (foundPin) break;

        // Output
        if (config.outputCount > 0) {
          const px = node.position.x + node.width;
          const py = node.position.y + node.height / 2;
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'output', index: 0 };
            break;
          }
        }
        if (foundPin) break;

        // Check Body
        if (worldPos.x >= node.position.x && worldPos.x <= node.position.x + node.width &&
            worldPos.y >= node.position.y && worldPos.y <= node.position.y + node.height) {
          foundNodeId = node.id;
          break;
        }
      }

      setInteraction(prev => ({
        ...prev,
        hoveredNodeId: foundNodeId,
        hoveredPin: foundPin
      }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    // Complete Wiring
    if (interaction.mode === InteractionMode.WIRING && interaction.hoveredPin && interaction.activeWireStart) {
      if (interaction.hoveredPin.type === 'input') {
        const newWire: Wire = {
          id: generateId(),
          sourceNodeId: interaction.activeWireStart.nodeId,
          sourcePinIndex: interaction.activeWireStart.pinIndex,
          targetNodeId: interaction.hoveredPin.nodeId,
          targetPinIndex: interaction.hoveredPin.index,
          state: false
        };

        // Avoid duplicates
        const exists = wires.some(w => 
          w.targetNodeId === newWire.targetNodeId && w.targetPinIndex === newWire.targetPinIndex
        );

        if (!exists) {
          const newWires = [...wires, newWire];
          // Immediate propagation check
          const res = propagateCircuit(nodes, newWires);
          setNodes(res.nodes);
          setWires(res.wires);
        }
      }
    }

    setInteraction(prev => ({
      ...prev,
      mode: prev.mode === InteractionMode.PLACING ? InteractionMode.PLACING : InteractionMode.IDLE,
      activeWireStart: null,
      dragStart: { x: 0, y: 0 }
    }));
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomIntensity = 0.1;
    const direction = e.deltaY > 0 ? -1 : 1;
    const newZoom = Math.min(Math.max(camera.zoom + (direction * zoomIntensity), 0.2), 3);

    // Zoom towards mouse pointer logic would go here, simplified to center for now or basic zoom
    // Keeping it simple:
    setCamera(prev => ({ ...prev, zoom: newZoom }));
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      if (interactionRef.current.hoveredNodeId) {
        const id = interactionRef.current.hoveredNodeId;
        setNodes(prev => prev.filter(n => n.id !== id));
        setWires(prev => prev.filter(w => w.sourceNodeId !== id && w.targetNodeId !== id));
      }
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const selectTool = (mode: InteractionMode, gateType?: GateType) => {
    setInteraction(prev => ({
      ...prev,
      mode: mode,
      placingType: gateType || null
    }));
  };

  return (
    <div className="relative w-screen h-screen bg-[#1e1e1e] overflow-hidden">
      <Toolbar 
        onSelectTool={selectTool} 
        currentMode={interaction.mode} 
        selectedGateType={interaction.placingType}
      />

      <div 
        ref={containerRef} 
        className="w-full h-full cursor-crosshair"
      >
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onContextMenu={(e) => e.preventDefault()}
          onWheel={handleWheel}
          className="block"
        />
      </div>

      {/* Info overlay */}
      <div className="absolute top-4 right-4 pointer-events-none text-zinc-500 text-xs font-mono">
        Nodes: {nodes.length} | Wires: {wires.length} | Zoom: {Math.round(camera.zoom * 100)}%
      </div>
    </div>
  );
};

export default App;

import { CircuitNode, GateType, Wire, Camera } from '../types';
import { COLORS, COMPONENT_CONFIGS, GRID_SIZE } from '../constants';

export const worldToScreen = (x: number, y: number, camera: Camera) => {
  return {
    x: (x * camera.zoom) + camera.x,
    y: (y * camera.zoom) + camera.y
  };
};

export const screenToWorld = (x: number, y: number, camera: Camera) => {
  return {
    x: (x - camera.x) / camera.zoom,
    y: (y - camera.y) / camera.zoom
  };
};

// Helper to draw input/output pins
const drawPin = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  isInput: boolean, 
  active: boolean,
  isHovered: boolean
) => {
  const r = 5;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = active 
    ? (isInput ? COLORS.pinInput : COLORS.pinOutput) 
    : COLORS.componentBody;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = isHovered ? '#ffffff' : (isInput ? COLORS.pinInput : COLORS.pinOutput);
  ctx.stroke();
};

const drawIEEEGate = (ctx: CanvasRenderingContext2D, node: CircuitNode, selected: boolean) => {
  const { x, y } = node.position;
  const config = COMPONENT_CONFIGS[node.type];
  const w = node.width;
  const h = node.height;

  ctx.save();
  ctx.translate(x, y);

  // Body Path
  ctx.beginPath();
  ctx.lineWidth = 2;
  ctx.strokeStyle = selected ? COLORS.componentBorderSelected : COLORS.componentBorder;
  ctx.fillStyle = COLORS.componentBody;

  switch (node.type) {
    case GateType.AND:
    case GateType.NAND:
      ctx.moveTo(0, 0);
      ctx.lineTo(w / 2, 0);
      ctx.arc(w / 2, h / 2, h / 2, -Math.PI / 2, Math.PI / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.OR:
    case GateType.NOR:
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      ctx.lineTo(w / 2, h); // Bottom flat-ish
      // OR curve is complex, approximating:
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(0, 0);
      break;
    case GateType.XOR:
      // Similar to OR but with the extra back curve line
      ctx.moveTo(10, 0);
      ctx.quadraticCurveTo(w / 4 + 10, h / 2, 10, h);
      ctx.lineTo(w / 2, h);
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(10, 0);

      // The second line for XOR
      ctx.stroke(); // Stroke body first
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      break;
    case GateType.NOT:
      ctx.moveTo(0, 0);
      ctx.lineTo(w - 10, h / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.INPUT_SWITCH:
      ctx.rect(0, 0, w, h);
      break;
    case GateType.OUTPUT_LAMP:
      ctx.arc(w/2, h/2, w/2 - 2, 0, Math.PI * 2);
      break;
    default:
      ctx.rect(0, 0, w, h);
  }

  ctx.fill();
  ctx.stroke();

  // Negation Circle (NAND, NOR, NOT)
  if ([GateType.NAND, GateType.NOR, GateType.NOT].includes(node.type)) {
    ctx.beginPath();
    ctx.arc(w - 5, h / 2, 4, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.componentBody;
    ctx.fill();
    ctx.stroke();
  }

  // Visuals for Switch/Lamp
  if (node.type === GateType.INPUT_SWITCH) {
    ctx.beginPath();
    ctx.rect(10, 10, w - 20, h - 20);
    ctx.fillStyle = node.state ? COLORS.lampOn : '#111';
    ctx.fill();
    ctx.fillStyle = COLORS.textColor;
    ctx.font = '10px Inter';
    ctx.fillText(node.state ? 'ON' : 'OFF', w/2 - 8, h/2 + 3);
  }

  if (node.type === GateType.OUTPUT_LAMP) {
    ctx.beginPath();
    ctx.arc(w/2, h/2, w/2 - 8, 0, Math.PI * 2);
    ctx.fillStyle = node.state ? COLORS.lampOn : COLORS.lampOff;
    ctx.fill();

    if (node.state) {
        ctx.shadowColor = COLORS.lampOn;
        ctx.shadowBlur = 20;
        ctx.stroke();
        ctx.shadowBlur = 0;
    }
  }

  // Label
  if (node.type !== GateType.INPUT_SWITCH && node.type !== GateType.OUTPUT_LAMP) {
      ctx.fillStyle = COLORS.textColor;
      ctx.font = 'bold 12px Inter';
      ctx.textAlign = 'center';
      ctx.fillText(config.label, w / 2, h / 2 + 4);
  }

  ctx.restore();
};

export const renderCircuit = (
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  nodes: CircuitNode[],
  wires: Wire[],
  camera: Camera,
  interactionState: any
) => {
  const { width, height } = canvas;

  // Clear
  ctx.fillStyle = COLORS.background;
  ctx.fillRect(0, 0, width, height);

  // Grid
  ctx.save();
  ctx.beginPath();
  ctx.strokeStyle = COLORS.gridLines;
  ctx.lineWidth = 1;

  const startX = Math.floor((0 - camera.x) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const startY = Math.floor((0 - camera.y) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const endX = Math.floor((width - camera.x) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;
  const endY = Math.floor((height - camera.y) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;

  for (let x = startX; x <= endX; x += GRID_SIZE) {
    const screenX = (x * camera.zoom) + camera.x;
    ctx.moveTo(screenX, 0);
    ctx.lineTo(screenX, height);
  }
  for (let y = startY; y <= endY; y += GRID_SIZE) {
    const screenY = (y * camera.zoom) + camera.y;
    ctx.moveTo(0, screenY);
    ctx.lineTo(width, screenY);
  }
  ctx.stroke();
  ctx.restore();

  // Draw Wires
  wires.forEach(wire => {
    const sourceNode = nodes.find(n => n.id === wire.sourceNodeId);
    const targetNode = nodes.find(n => n.id === wire.targetNodeId);
    if (!sourceNode || !targetNode) return;

    const startX = sourceNode.position.x + sourceNode.width;
    const startY = sourceNode.position.y + (sourceNode.height / 2); // Assuming single output center

    // Calculate input pin Y position based on input count
    const inputCount = COMPONENT_CONFIGS[targetNode.type].inputCount;
    const pinSpacing = targetNode.height / (inputCount + 1);
    const endX = targetNode.position.x;
    const endY = targetNode.position.y + (pinSpacing * (wire.targetPinIndex + 1));

    const s = worldToScreen(startX, startY, camera);
    const e = worldToScreen(endX, endY, camera);

    ctx.beginPath();
    ctx.moveTo(s.x, s.y);
    const cpDist = Math.abs(e.x - s.x) * 0.5;
    ctx.bezierCurveTo(s.x + cpDist, s.y, e.x - cpDist, e.y, e.x, e.y);

    ctx.strokeStyle = wire.state ? COLORS.wireActive : COLORS.wireInactive;
    ctx.lineWidth = 3 * camera.zoom;
    if (wire.state) {
      ctx.shadowColor = COLORS.wireActive;
      ctx.shadowBlur = 10;
    }
    ctx.stroke();
    ctx.shadowBlur = 0;
  });

  // Active wire creation line
  if (interactionState.mode === 'WIRING' && interactionState.activeWireStart) {
    const { nodeId, pinIndex } = interactionState.activeWireStart;
    const node = nodes.find(n => n.id === nodeId);
    if (node) {
        const startX = node.position.x + node.width;
        const startY = node.position.y + node.height / 2;
        const s = worldToScreen(startX, startY, camera);

        // Mouse pos (we need to pass mouse pos or store it in interaction state, assumed dragStart/current in real impl)
        // For now, let's skip drawing the drag line perfectly here without mousePos in render args
        // In App.tsx we track mousePos ref
    }
  }

  // Draw Nodes
  nodes.forEach(node => {
    const screenPos = worldToScreen(node.position.x, node.position.y, camera);
    const isSelected = false; // Add selection logic later

    // Transform ctx to node position
    ctx.save();
    // Translate happens inside drawIEEEGate but we need to pass screen coords or scale ctx
    // Better to scale ctx and draw in world coords? 
    // Mixing: Let's transform scale/translate for the whole layer
    ctx.setTransform(camera.zoom, 0, 0, camera.zoom, camera.x, camera.y);

    drawIEEEGate(ctx, node, isSelected);

    // Draw Pins
    const config = COMPONENT_CONFIGS[node.type];

    // Inputs
    const pinSpacingIn = node.height / (config.inputCount + 1);
    for (let i = 0; i < config.inputCount; i++) {
        const pinY = node.position.y + (pinSpacingIn * (i + 1));
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'input' 
            && interactionState.hoveredPin?.index === i;

        drawPin(ctx, node.position.x, pinY, true, node.inputs[i], isHovered);
    }

    // Outputs
    if (config.outputCount > 0) {
        const pinY = node.position.y + (node.height / 2);
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'output';
        drawPin(ctx, node.position.x + node.width, pinY, false, node.state, isHovered);
    }

    ctx.restore();
  });
};

import React from 'react';
import { GateType, InteractionMode } from '../types';
import { COMPONENT_CONFIGS } from '../constants';
import { MousePointer2, Plus } from 'lucide-react';

interface ToolbarProps {
  onSelectTool: (mode: InteractionMode, gateType?: GateType) => void;
  currentMode: InteractionMode;
  selectedGateType: GateType | null;
}

const Toolbar: React.FC<ToolbarProps> = ({ onSelectTool, currentMode, selectedGateType }) => {
  const gates = Object.values(COMPONENT_CONFIGS);

  return (
    <div className="absolute left-4 top-4 bottom-4 w-64 bg-zinc-900/90 backdrop-blur-md border border-zinc-700 rounded-xl shadow-2xl flex flex-col overflow-hidden z-10">
      <div className="p-4 border-b border-zinc-700 bg-zinc-800/50">
