export default Toolbar;

import React, { useEffect, useRef } from 'react';
import { Copy, Trash2 } from 'lucide-react';

interface ContextMenuProps {
  x: number;
  y: number;
  onDuplicate: () => void;
  onDelete: () => void;
  onClose: () => void;
}

export const ContextMenu: React.FC<ContextMenuProps> = ({ x, y, onDuplicate, onDelete, onClose }) => {
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onClose();
      }
    };
    // Use mousedown to detect outside clicks earlier than click
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  return (
    <div 
      ref={menuRef}
      className="fixed bg-zinc-800 border border-zinc-700 rounded-lg shadow-xl z-50 py-1 min-w-[160px] flex flex-col"
      style={{ top: y, left: x }}
    >
      <button 
        onClick={(e) => { e.stopPropagation(); onDuplicate(); }}
        className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-zinc-700 hover:text-white flex items-center gap-2 transition-colors cursor-pointer"
      >
        <Copy size={14} />
        Duplicate
      </button>
      <button 
        onClick={(e) => { e.stopPropagation(); onDelete(); }}
        className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-zinc-700 hover:text-red-300 flex items-center gap-2 transition-colors cursor-pointer"
      >
        <Trash2 size={14} />
        Delete
      </button>
    </div>
  );
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  CircuitNode, 
  Wire, 
  Camera, 
  InteractionMode, 
  InteractionState, 
  GateType,
  Position
} from './types';
import { COMPONENT_CONFIGS, COLORS } from './constants';
import { renderCircuit, screenToWorld, worldToScreen } from './services/renderer';
import { propagateCircuit } from './services/circuitEngine';
import Toolbar from './components/Toolbar';
import { ContextMenu } from './components/ContextMenu';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // State
  const [nodes, setNodes] = useState<CircuitNode[]>([]);
  const [wires, setWires] = useState<Wire[]>([]);
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, zoom: 1 });
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; nodeId: string } | null>(null);

  // Interaction State
  const [interaction, setInteraction] = useState<InteractionState>({
    mode: InteractionMode.IDLE,
    hoveredNodeId: null,
    hoveredPin: null,
    dragStart: { x: 0, y: 0 },
    dragOffset: { x: 0, y: 0 },
    activeWireStart: null,
    placingType: null,
  });

  // Refs for items needed inside event listeners/loops without triggering re-renders
  const nodesRef = useRef(nodes);
  const wiresRef = useRef(wires);
  const interactionRef = useRef(interaction);
  const cameraRef = useRef(camera);
  const mousePosRef = useRef<Position>({ x: 0, y: 0 });

  // Sync refs
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { wiresRef.current = wires; }, [wires]);
  useEffect(() => { interactionRef.current = interaction; }, [interaction]);
  useEffect(() => { cameraRef.current = camera; }, [camera]);

  // Main Logic Loop (Clock & Propagation)
  useEffect(() => {
    const interval = setInterval(() => {
      let needsUpdate = false;
      const currentNodes = [...nodesRef.current];

      // Handle Clock Components
      currentNodes.forEach(node => {
        if (node.type === GateType.CLOCK) {
          node.state = !node.state;
          needsUpdate = true;
        }
      });

      if (needsUpdate) {
        const result = propagateCircuit(currentNodes, wiresRef.current);
        setNodes(result.nodes);
        setWires(result.wires);
      }
    }, 500); // 500ms Clock tick

    return () => clearInterval(interval);
  }, []);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;

    const render = () => {
      // Handle resize
      if (containerRef.current) {
        canvas.width = containerRef.current.clientWidth;
        canvas.height = containerRef.current.clientHeight;
      }

      const currentInteraction = interactionRef.current;

      renderCircuit(
        canvas, 
        ctx, 
        nodesRef.current, 
        wiresRef.current, 
        cameraRef.current, 
        currentInteraction
      );

      // Draw active wire line if dragging
      if (currentInteraction.mode === InteractionMode.WIRING && currentInteraction.activeWireStart) {
        const { nodeId } = currentInteraction.activeWireStart;
        const node = nodesRef.current.find(n => n.id === nodeId);
        if (node) {
          const startX = node.position.x + node.width;
          const startY = node.position.y + node.height / 2;
          const s = worldToScreen(startX, startY, cameraRef.current);

          ctx.beginPath();
          ctx.moveTo(s.x, s.y);
          ctx.lineTo(mousePosRef.current.x, mousePosRef.current.y);
          ctx.strokeStyle = COLORS.wireActive;
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, []);

  // --- Actions ---
  const deleteNode = (id: string) => {
    setNodes(prev => prev.filter(n => n.id !== id));
    setWires(prev => prev.filter(w => w.sourceNodeId !== id && w.targetNodeId !== id));
    setContextMenu(null);
  };

  const duplicateNode = (id: string) => {
    const original = nodes.find(n => n.id === id);
    if (!original) return;

    const newNode: CircuitNode = {
        ...original,
        id: generateId(),
        position: { x: original.position.x + 20, y: original.position.y + 20 },
        // Keep state for convenience, usually logic gates reset but switches might be nice to keep
        inputs: [...original.inputs]
    };
    setNodes(prev => [...prev, newNode]);
    setContextMenu(null);
  };

  // --- Interaction Handlers ---

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
    if (interaction.hoveredNodeId) {
      setContextMenu({
        x: e.clientX,
        y: e.clientY,
        nodeId: interaction.hoveredNodeId
      });
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Close context menu if clicking anywhere
    if (contextMenu) setContextMenu(null);

    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const worldPos = screenToWorld(x, y, camera);

    // Right click
    if (e.button === 2) {
      // If hovering a node, do not pan, let ContextMenu handle it on menu event
      if (interaction.hoveredNodeId) {
        return;
      }
      // Else pan on empty space
      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.PANNING,
        dragStart: { x, y }
      }));
      return;
    }

    // Placing Mode
    if (interaction.mode === InteractionMode.PLACING && interaction.placingType) {
      const config = COMPONENT_CONFIGS[interaction.placingType];
      const newNode: CircuitNode = {
        id: generateId(),
        type: interaction.placingType,
        position: { x: worldPos.x - config.width/2, y: worldPos.y - config.height/2 },
        width: config.width,
        height: config.height,
        inputs: new Array(config.inputCount).fill(false),
        state: false,
        label: config.label
      };

      setNodes(prev => [...prev, newNode]);
      return;
    }

    // Wiring Mode Check (Pin Click)
    if (interaction.hoveredPin) {
      if (interaction.hoveredPin.type === 'output') {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.WIRING,
          activeWireStart: { nodeId: prev.hoveredPin!.nodeId, pinIndex: prev.hoveredPin!.index }
        }));
      }
      return;
    }

    // Switch Toggle Check
    if (interaction.hoveredNodeId) {
      const node = nodes.find(n => n.id === interaction.hoveredNodeId);
      if (node && node.type === GateType.INPUT_SWITCH) {
        const newNodes = nodes.map(n => 
          n.id === node.id ? { ...n, state: !n.state } : n
        );
        const res = propagateCircuit(newNodes, wires);
        setNodes(res.nodes);
        setWires(res.wires);
        return;
      }
    }

    // Drag Node Check
    if (interaction.hoveredNodeId) {
      const node = nodes.find(n => n.id === interaction.hoveredNodeId);
      if (node) {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.DRAGGING_NODE,
          dragOffset: { 
            x: worldPos.x - node.position.x, 
            y: worldPos.y - node.position.y 
          }
        }));
      }
      return;
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    // Panning
    if (interaction.mode === InteractionMode.PANNING) {
      const dx = x - interaction.dragStart.x;
      const dy = y - interaction.dragStart.y;
      setCamera(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
      setInteraction(prev => ({ ...prev, dragStart: { x, y } }));
      return;
    }

    // Dragging Node
    if (interaction.mode === InteractionMode.DRAGGING_NODE && interaction.hoveredNodeId) {
      const worldPos = screenToWorld(x, y, camera);
      setNodes(prev => prev.map(n => 
        n.id === interaction.hoveredNodeId 
          ? { ...n, position: { x: worldPos.x - interaction.dragOffset.x, y: worldPos.y - interaction.dragOffset.y } } 
          : n
      ));
      return;
    }

    // Hover Detection
    if (interaction.mode === InteractionMode.IDLE || interaction.mode === InteractionMode.WIRING || interaction.mode === InteractionMode.PLACING) {
      const worldPos = screenToWorld(x, y, camera);
      let foundNodeId: string | null = null;
      let foundPin: InteractionState['hoveredPin'] = null;

      // Reverse iterate for top-most check
      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];

        // Check Pins first (Hitbox radius 10)
        const config = COMPONENT_CONFIGS[node.type];

        // Inputs
        const pinSpacingIn = node.height / (config.inputCount + 1);
        for (let p = 0; p < config.inputCount; p++) {
          const px = node.position.x;
          const py = node.position.y + (pinSpacingIn * (p + 1));
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'input', index: p };
            break;
          }
        }
        if (foundPin) break;

        // Output
        if (config.outputCount > 0) {
          const px = node.position.x + node.width;
          const py = node.position.y + node.height / 2;
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'output', index: 0 };
            break;
          }
        }
        if (foundPin) break;

        // Check Body
        if (worldPos.x >= node.position.x && worldPos.x <= node.position.x + node.width &&
            worldPos.y >= node.position.y && worldPos.y <= node.position.y + node.height) {
          foundNodeId = node.id;
          break;
        }
      }

      setInteraction(prev => ({
        ...prev,
        hoveredNodeId: foundNodeId,
        hoveredPin: foundPin
      }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    // Complete Wiring
    if (interaction.mode === InteractionMode.WIRING && interaction.hoveredPin && interaction.activeWireStart) {
      if (interaction.hoveredPin.type === 'input') {
        const newWire: Wire = {
          id: generateId(),
          sourceNodeId: interaction.activeWireStart.nodeId,
          sourcePinIndex: interaction.activeWireStart.pinIndex,
          targetNodeId: interaction.hoveredPin.nodeId,
          targetPinIndex: interaction.hoveredPin.index,
          state: false
        };

        // Avoid duplicates
        const exists = wires.some(w => 
          w.targetNodeId === newWire.targetNodeId && w.targetPinIndex === newWire.targetPinIndex
        );

        if (!exists) {
          const newWires = [...wires, newWire];
          // Immediate propagation check
          const res = propagateCircuit(nodes, newWires);
          setNodes(res.nodes);
          setWires(res.wires);
        }
      }
    }

    setInteraction(prev => ({
      ...prev,
      mode: prev.mode === InteractionMode.PLACING ? InteractionMode.PLACING : InteractionMode.IDLE,
      activeWireStart: null,
      dragStart: { x: 0, y: 0 }
    }));
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomIntensity = 0.1;
    const direction = e.deltaY > 0 ? -1 : 1;
    const newZoom = Math.min(Math.max(camera.zoom + (direction * zoomIntensity), 0.2), 3);
    setCamera(prev => ({ ...prev, zoom: newZoom }));
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      if (interactionRef.current.hoveredNodeId) {
        const id = interactionRef.current.hoveredNodeId;
        setNodes(prev => prev.filter(n => n.id !== id));
        setWires(prev => prev.filter(w => w.sourceNodeId !== id && w.targetNodeId !== id));
      }
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const selectTool = (mode: InteractionMode, gateType?: GateType) => {
    setInteraction(prev => ({
      ...prev,
      mode: mode,
      placingType: gateType || null
    }));
  };

  return (
    <div className="relative w-screen h-screen bg-[#1e1e1e] overflow-hidden">
      <Toolbar 
        onSelectTool={selectTool} 
        currentMode={interaction.mode} 
        selectedGateType={interaction.placingType}
      />

      <div 
        ref={containerRef} 
        className="w-full h-full cursor-crosshair"
      >
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onContextMenu={handleContextMenu}
          onWheel={handleWheel}
          className="block"
        />
      </div>

      {contextMenu && (
        <ContextMenu 
          x={contextMenu.x} 
          y={contextMenu.y} 
          onDelete={() => deleteNode(contextMenu.nodeId)}
          onDuplicate={() => duplicateNode(contextMenu.nodeId)}
          onClose={() => setContextMenu(null)}
        />
      )}

      {/* Info overlay */}
      <div className="absolute top-4 right-4 pointer-events-none text-zinc-500 text-xs font-mono">
        Nodes: {nodes.length} | Wires: {wires.length} | Zoom: {Math.round(camera.zoom * 100)}%
      </div>
    </div>
  );
};

export default App;

export enum GateType {
  AND = 'AND',
  OR = 'OR',
  NOT = 'NOT',
  NAND = 'NAND',
  NOR = 'NOR',
  XOR = 'XOR',
  INPUT_SWITCH = 'INPUT_SWITCH',
  OUTPUT_LAMP = 'OUTPUT_LAMP',
  CLOCK = 'CLOCK'
}

export interface Position {
  x: number;
  y: number;
}

export interface PinDef {
  id: string;
  type: 'input' | 'output';
  label?: string;
}

export interface CircuitNode {
  id: string;
  type: GateType;
  position: Position;
  state: boolean; // Main output state (High/Low)
  inputs: boolean[]; // Current state of inputs
  width: number;
  height: number;
  label: string;
}

export type WireCurveType = 'bezier' | 'straight' | 'step';

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourcePinIndex: number; // usually 0 for single output gates
  targetNodeId: string;
  targetPinIndex: number;
  state: boolean;
  curveType?: WireCurveType;
  color?: string;
}

export interface Camera {
  x: number;
  y: number;
  zoom: number;
}

export enum InteractionMode {
  IDLE = 'IDLE',
  PANNING = 'PANNING',
  DRAGGING_NODE = 'DRAGGING_NODE',
  WIRING = 'WIRING',
  PLACING = 'PLACING'
}

export interface InteractionState {
  mode: InteractionMode;
  hoveredNodeId: string | null;
  hoveredPin: { nodeId: string; type: 'input' | 'output'; index: number } | null;
  dragStart: Position; // Screen coordinates
  dragOffset: Position; // Offset from node center
  activeWireStart: { nodeId: string; pinIndex: number } | null;
  placingType: GateType | null;
}

import { CircuitNode, GateType, Wire, Camera } from '../types';
import { COLORS, COMPONENT_CONFIGS, GRID_SIZE } from '../constants';

export const worldToScreen = (x: number, y: number, camera: Camera) => {
  return {
    x: (x * camera.zoom) + camera.x,
    y: (y * camera.zoom) + camera.y
  };
};

export const screenToWorld = (x: number, y: number, camera: Camera) => {
  return {
    x: (x - camera.x) / camera.zoom,
    y: (y - camera.y) / camera.zoom
  };
};

// Helper to draw input/output pins
const drawPin = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  isInput: boolean, 
  active: boolean,
  isHovered: boolean
) => {
  const r = 5;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = active 
    ? (isInput ? COLORS.pinInput : COLORS.pinOutput) 
    : COLORS.componentBody;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = isHovered ? '#ffffff' : (isInput ? COLORS.pinInput : COLORS.pinOutput);
  ctx.stroke();
};

const drawIEEEGate = (ctx: CanvasRenderingContext2D, node: CircuitNode, selected: boolean) => {
  const { x, y } = node.position;
  const config = COMPONENT_CONFIGS[node.type];
  const w = node.width;
  const h = node.height;

  ctx.save();
  ctx.translate(x, y);

  // Body Path
  ctx.beginPath();
  ctx.lineWidth = 2;
  ctx.strokeStyle = selected ? COLORS.componentBorderSelected : COLORS.componentBorder;
  ctx.fillStyle = COLORS.componentBody;

  switch (node.type) {
    case GateType.AND:
    case GateType.NAND:
      ctx.moveTo(0, 0);
      ctx.lineTo(w / 2, 0);
      ctx.arc(w / 2, h / 2, h / 2, -Math.PI / 2, Math.PI / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.OR:
    case GateType.NOR:
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      ctx.lineTo(w / 2, h); // Bottom flat-ish
      // OR curve is complex, approximating:
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(0, 0);
      break;
    case GateType.XOR:
      // Similar to OR but with the extra back curve line
      ctx.moveTo(10, 0);
      ctx.quadraticCurveTo(w / 4 + 10, h / 2, 10, h);
      ctx.lineTo(w / 2, h);
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(10, 0);

      // The second line for XOR
      ctx.stroke(); // Stroke body first
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      break;
    case GateType.NOT:
      ctx.moveTo(0, 0);
      ctx.lineTo(w - 10, h / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.INPUT_SWITCH:
      ctx.rect(0, 0, w, h);
      break;
    case GateType.OUTPUT_LAMP:
      ctx.arc(w/2, h/2, w/2 - 2, 0, Math.PI * 2);
      break;
    default:
      ctx.rect(0, 0, w, h);
  }

  ctx.fill();
  ctx.stroke();

  // Negation Circle (NAND, NOR, NOT)
  if ([GateType.NAND, GateType.NOR, GateType.NOT].includes(node.type)) {
    ctx.beginPath();
    ctx.arc(w - 5, h / 2, 4, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.componentBody;
    ctx.fill();
    ctx.stroke();
  }

  // Visuals for Switch/Lamp
  if (node.type === GateType.INPUT_SWITCH) {
    ctx.beginPath();
    ctx.rect(10, 10, w - 20, h - 20);
    ctx.fillStyle = node.state ? COLORS.lampOn : '#111';
    ctx.fill();
    ctx.fillStyle = COLORS.textColor;
    ctx.font = '10px Inter';
    ctx.fillText(node.state ? 'ON' : 'OFF', w/2 - 8, h/2 + 3);
  }

  if (node.type === GateType.OUTPUT_LAMP) {
    ctx.beginPath();
    ctx.arc(w/2, h/2, w/2 - 8, 0, Math.PI * 2);
    ctx.fillStyle = node.state ? COLORS.lampOn : COLORS.lampOff;
    ctx.fill();

    if (node.state) {
        ctx.shadowColor = COLORS.lampOn;
        ctx.shadowBlur = 20;
        ctx.stroke();
        ctx.shadowBlur = 0;
    }
  }

  // Label
  if (node.type !== GateType.INPUT_SWITCH && node.type !== GateType.OUTPUT_LAMP) {
      ctx.fillStyle = COLORS.textColor;
      ctx.font = 'bold 12px Inter';
      ctx.textAlign = 'center';
      ctx.fillText(config.label, w / 2, h / 2 + 4);
  }

  ctx.restore();
};

export const renderCircuit = (
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  nodes: CircuitNode[],
  wires: Wire[],
  camera: Camera,
  interactionState: any
) => {
  const { width, height } = canvas;

  // Clear
  ctx.fillStyle = COLORS.background;
  ctx.fillRect(0, 0, width, height);

  // Grid
  ctx.save();
  ctx.beginPath();
  ctx.strokeStyle = COLORS.gridLines;
  ctx.lineWidth = 1;

  const startX = Math.floor((0 - camera.x) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const startY = Math.floor((0 - camera.y) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const endX = Math.floor((width - camera.x) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;
  const endY = Math.floor((height - camera.y) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;

  for (let x = startX; x <= endX; x += GRID_SIZE) {
    const screenX = (x * camera.zoom) + camera.x;
    ctx.moveTo(screenX, 0);
    ctx.lineTo(screenX, height);
  }
  for (let y = startY; y <= endY; y += GRID_SIZE) {
    const screenY = (y * camera.zoom) + camera.y;
    ctx.moveTo(0, screenY);
    ctx.lineTo(width, screenY);
  }
  ctx.stroke();
  ctx.restore();

  // Draw Wires
  wires.forEach(wire => {
    const sourceNode = nodes.find(n => n.id === wire.sourceNodeId);
    const targetNode = nodes.find(n => n.id === wire.targetNodeId);
    if (!sourceNode || !targetNode) return;

    const startX = sourceNode.position.x + sourceNode.width;
    const startY = sourceNode.position.y + (sourceNode.height / 2); // Assuming single output center

    // Calculate input pin Y position based on input count
    const inputCount = COMPONENT_CONFIGS[targetNode.type].inputCount;
    const pinSpacing = targetNode.height / (inputCount + 1);
    const endX = targetNode.position.x;
    const endY = targetNode.position.y + (pinSpacing * (wire.targetPinIndex + 1));

    const s = worldToScreen(startX, startY, camera);
    const e = worldToScreen(endX, endY, camera);

    ctx.beginPath();
    ctx.moveTo(s.x, s.y);

    // Wire Curve Logic
    const curveType = wire.curveType || 'bezier';

    if (curveType === 'straight') {
      ctx.lineTo(e.x, e.y);
    } else if (curveType === 'step') {
      const midX = (s.x + e.x) / 2;
      ctx.lineTo(midX, s.y);
      ctx.lineTo(midX, e.y);
      ctx.lineTo(e.x, e.y);
    } else {
      // Default 'bezier'
      const cpDist = Math.abs(e.x - s.x) * 0.5;
      ctx.bezierCurveTo(s.x + cpDist, s.y, e.x - cpDist, e.y, e.x, e.y);
    }

    // Wire Color Logic
    if (wire.color) {
      ctx.strokeStyle = wire.color;
      if (wire.state) {
        ctx.shadowColor = wire.color;
        ctx.shadowBlur = 10;
      }
    } else {
      ctx.strokeStyle = wire.state ? COLORS.wireActive : COLORS.wireInactive;
      if (wire.state) {
        ctx.shadowColor = COLORS.wireActive;
        ctx.shadowBlur = 10;
      }
    }

    ctx.lineWidth = 3 * camera.zoom;
    ctx.stroke();
    ctx.shadowBlur = 0;
  });

  // Active wire creation line (dragging wire)
  if (interactionState.mode === 'WIRING' && interactionState.activeWireStart) {
    const { nodeId, pinIndex } = interactionState.activeWireStart;
    const node = nodes.find(n => n.id === nodeId);
    if (node) {
        const startX = node.position.x + node.width;
        const startY = node.position.y + node.height / 2;
        const s = worldToScreen(startX, startY, camera);

        // Note: Actual end coords are handled in App via mouse pos, 
        // but since we don't have mouse pos here explicitly without modifying signature, 
        // this part relies on the external caller to handle the drag line OR
        // we assume App handles drawing the drag line separately (which it does in App.tsx).
    }
  }

  // Draw Nodes
  nodes.forEach(node => {
    // Transform ctx to node position
    ctx.save();
    ctx.setTransform(camera.zoom, 0, 0, camera.zoom, camera.x, camera.y);

    const isSelected = false; // Placeholder for selection logic
    drawIEEEGate(ctx, node, isSelected);

    // Draw Pins
    const config = COMPONENT_CONFIGS[node.type];

    // Inputs
    const pinSpacingIn = node.height / (config.inputCount + 1);
    for (let i = 0; i < config.inputCount; i++) {
        const pinY = node.position.y + (pinSpacingIn * (i + 1));
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'input' 
            && interactionState.hoveredPin?.index === i;

        drawPin(ctx, node.position.x, pinY, true, node.inputs[i], isHovered);
    }

    // Outputs
    if (config.outputCount > 0) {
        const pinY = node.position.y + (node.height / 2);
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'output';
        drawPin(ctx, node.position.x + node.width, pinY, false, node.state, isHovered);
    }

    ctx.restore();
  });
};

export enum GateType {
  AND = 'AND',
  OR = 'OR',
  NOT = 'NOT',
  NAND = 'NAND',
  NOR = 'NOR',
  XOR = 'XOR',
  INPUT_SWITCH = 'INPUT_SWITCH',
  OUTPUT_LAMP = 'OUTPUT_LAMP',
  CLOCK = 'CLOCK'
}

export interface Position {
  x: number;
  y: number;
}

export interface PinDef {
  id: string;
  type: 'input' | 'output';
  label?: string;
}

export interface CircuitNode {
  id: string;
  type: GateType;
  position: Position;
  state: boolean; // Main output state (High/Low)
  inputs: boolean[]; // Current state of inputs
  width: number;
  height: number;
  label: string;
}

export type WireCurveType = 'bezier' | 'straight' | 'step';

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourcePinIndex: number; // usually 0 for single output gates
  targetNodeId: string;
  targetPinIndex: number;
  state: boolean;
  curveType?: WireCurveType;
  color?: string;
}

export interface Camera {
  x: number;
  y: number;
  zoom: number;
}

export enum InteractionMode {
  IDLE = 'IDLE',
  PANNING = 'PANNING',
  DRAGGING_NODE = 'DRAGGING_NODE',
  WIRING = 'WIRING',
  PLACING = 'PLACING',
  SELECTING = 'SELECTING'
}

export interface InteractionState {
  mode: InteractionMode;
  hoveredNodeId: string | null;
  hoveredPin: { nodeId: string; type: 'input' | 'output'; index: number } | null;
  dragStart: Position; // Screen coordinates
  dragOffset: Position; // Offset from node center (Legacy/Single) or unused in multi-drag
  activeWireStart: { nodeId: string; pinIndex: number } | null;
  placingType: GateType | null;
}

import { CircuitNode, GateType, Wire, Camera, InteractionMode } from '../types';
import { COLORS, COMPONENT_CONFIGS, GRID_SIZE } from '../constants';

export const worldToScreen = (x: number, y: number, camera: Camera) => {
  return {
    x: (x * camera.zoom) + camera.x,
    y: (y * camera.zoom) + camera.y
  };
};

export const screenToWorld = (x: number, y: number, camera: Camera) => {
  return {
    x: (x - camera.x) / camera.zoom,
    y: (y - camera.y) / camera.zoom
  };
};

// Helper to draw input/output pins
const drawPin = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  isInput: boolean, 
  active: boolean,
  isHovered: boolean
) => {
  const r = 5;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = active 
    ? (isInput ? COLORS.pinInput : COLORS.pinOutput) 
    : COLORS.componentBody;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = isHovered ? '#ffffff' : (isInput ? COLORS.pinInput : COLORS.pinOutput);
  ctx.stroke();
};

const drawIEEEGate = (ctx: CanvasRenderingContext2D, node: CircuitNode, selected: boolean) => {
  const { x, y } = node.position;
  const config = COMPONENT_CONFIGS[node.type];
  const w = node.width;
  const h = node.height;

  ctx.save();
  ctx.translate(x, y);

  // Body Path
  ctx.beginPath();
  ctx.lineWidth = selected ? 3 : 2;
  ctx.strokeStyle = selected ? COLORS.componentBorderSelected : COLORS.componentBorder;
  ctx.fillStyle = COLORS.componentBody;

  if (selected) {
    ctx.shadowColor = 'rgba(255, 255, 255, 0.5)';
    ctx.shadowBlur = 10;
  }

  switch (node.type) {
    case GateType.AND:
    case GateType.NAND:
      ctx.moveTo(0, 0);
      ctx.lineTo(w / 2, 0);
      ctx.arc(w / 2, h / 2, h / 2, -Math.PI / 2, Math.PI / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.OR:
    case GateType.NOR:
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      ctx.lineTo(w / 2, h); // Bottom flat-ish
      // OR curve is complex, approximating:
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(0, 0);
      break;
    case GateType.XOR:
      // Similar to OR but with the extra back curve line
      ctx.moveTo(10, 0);
      ctx.quadraticCurveTo(w / 4 + 10, h / 2, 10, h);
      ctx.lineTo(w / 2, h);
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(10, 0);

      // The second line for XOR
      ctx.stroke(); // Stroke body first
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      break;
    case GateType.NOT:
      ctx.moveTo(0, 0);
      ctx.lineTo(w - 10, h / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.INPUT_SWITCH:
      ctx.rect(0, 0, w, h);
      break;
    case GateType.OUTPUT_LAMP:
      ctx.arc(w/2, h/2, w/2 - 2, 0, Math.PI * 2);
      break;
    default:
      ctx.rect(0, 0, w, h);
  }

  ctx.fill();
  ctx.stroke();
  ctx.shadowBlur = 0; // Reset shadow

  // Negation Circle (NAND, NOR, NOT)
  if ([GateType.NAND, GateType.NOR, GateType.NOT].includes(node.type)) {
    ctx.beginPath();
    ctx.arc(w - 5, h / 2, 4, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.componentBody;
    ctx.fill();
    ctx.stroke();
  }

  // Visuals for Switch/Lamp
  if (node.type === GateType.INPUT_SWITCH) {
    ctx.beginPath();
    ctx.rect(10, 10, w - 20, h - 20);
    ctx.fillStyle = node.state ? COLORS.lampOn : '#111';
    ctx.fill();
    ctx.fillStyle = COLORS.textColor;
    ctx.font = '10px Inter';
    ctx.fillText(node.state ? 'ON' : 'OFF', w/2 - 8, h/2 + 3);
  }

  if (node.type === GateType.OUTPUT_LAMP) {
    ctx.beginPath();
    ctx.arc(w/2, h/2, w/2 - 8, 0, Math.PI * 2);
    ctx.fillStyle = node.state ? COLORS.lampOn : COLORS.lampOff;
    ctx.fill();

    if (node.state) {
        ctx.shadowColor = COLORS.lampOn;
        ctx.shadowBlur = 20;
        ctx.stroke();
        ctx.shadowBlur = 0;
    }
  }

  // Label
  if (node.type !== GateType.INPUT_SWITCH && node.type !== GateType.OUTPUT_LAMP) {
      ctx.fillStyle = COLORS.textColor;
      ctx.font = 'bold 12px Inter';
      ctx.textAlign = 'center';
      ctx.fillText(config.label, w / 2, h / 2 + 4);
  }

  ctx.restore();
};

export const renderCircuit = (
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  nodes: CircuitNode[],
  wires: Wire[],
  camera: Camera,
  interactionState: any,
  selectedNodeIds: string[],
  currentMousePos: { x: number, y: number }
) => {
  const { width, height } = canvas;

  // Clear
  ctx.fillStyle = COLORS.background;
  ctx.fillRect(0, 0, width, height);

  // Grid
  ctx.save();
  ctx.beginPath();
  ctx.strokeStyle = COLORS.gridLines;
  ctx.lineWidth = 1;

  const startX = Math.floor((0 - camera.x) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const startY = Math.floor((0 - camera.y) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const endX = Math.floor((width - camera.x) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;
  const endY = Math.floor((height - camera.y) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;

  for (let x = startX; x <= endX; x += GRID_SIZE) {
    const screenX = (x * camera.zoom) + camera.x;
    ctx.moveTo(screenX, 0);
    ctx.lineTo(screenX, height);
  }
  for (let y = startY; y <= endY; y += GRID_SIZE) {
    const screenY = (y * camera.zoom) + camera.y;
    ctx.moveTo(0, screenY);
    ctx.lineTo(width, screenY);
  }
  ctx.stroke();
  ctx.restore();

  // Draw Wires
  wires.forEach(wire => {
    const sourceNode = nodes.find(n => n.id === wire.sourceNodeId);
    const targetNode = nodes.find(n => n.id === wire.targetNodeId);
    if (!sourceNode || !targetNode) return;

    const startX = sourceNode.position.x + sourceNode.width;
    const startY = sourceNode.position.y + (sourceNode.height / 2); 

    const inputCount = COMPONENT_CONFIGS[targetNode.type].inputCount;
    const pinSpacing = targetNode.height / (inputCount + 1);
    const endX = targetNode.position.x;
    const endY = targetNode.position.y + (pinSpacing * (wire.targetPinIndex + 1));

    const s = worldToScreen(startX, startY, camera);
    const e = worldToScreen(endX, endY, camera);

    ctx.beginPath();
    ctx.moveTo(s.x, s.y);

    const curveType = wire.curveType || 'bezier';

    if (curveType === 'straight') {
      ctx.lineTo(e.x, e.y);
    } else if (curveType === 'step') {
      const midX = (s.x + e.x) / 2;
      ctx.lineTo(midX, s.y);
      ctx.lineTo(midX, e.y);
      ctx.lineTo(e.x, e.y);
    } else {
      const cpDist = Math.abs(e.x - s.x) * 0.5;
      ctx.bezierCurveTo(s.x + cpDist, s.y, e.x - cpDist, e.y, e.x, e.y);
    }

    if (wire.color) {
      ctx.strokeStyle = wire.color;
      if (wire.state) {
        ctx.shadowColor = wire.color;
        ctx.shadowBlur = 10;
      }
    } else {
      ctx.strokeStyle = wire.state ? COLORS.wireActive : COLORS.wireInactive;
      if (wire.state) {
        ctx.shadowColor = COLORS.wireActive;
        ctx.shadowBlur = 10;
      }
    }

    ctx.lineWidth = 3 * camera.zoom;
    ctx.stroke();
    ctx.shadowBlur = 0;
  });

  // Active wire creation line
  if (interactionState.mode === InteractionMode.WIRING && interactionState.activeWireStart) {
    const { nodeId, pinIndex } = interactionState.activeWireStart;
    const node = nodes.find(n => n.id === nodeId);
    if (node) {
        // ... (Drawing handled in App.tsx mainly, but placeholder here if needed)
    }
  }

  // Draw Nodes
  nodes.forEach(node => {
    ctx.save();
    ctx.setTransform(camera.zoom, 0, 0, camera.zoom, camera.x, camera.y);

    const isSelected = selectedNodeIds.includes(node.id);
    drawIEEEGate(ctx, node, isSelected);

    // Draw Pins
    const config = COMPONENT_CONFIGS[node.type];

    // Inputs
    const pinSpacingIn = node.height / (config.inputCount + 1);
    for (let i = 0; i < config.inputCount; i++) {
        const pinY = node.position.y + (pinSpacingIn * (i + 1));
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'input' 
            && interactionState.hoveredPin?.index === i;

        drawPin(ctx, node.position.x, pinY, true, node.inputs[i], isHovered);
    }

    // Outputs
    if (config.outputCount > 0) {
        const pinY = node.position.y + (node.height / 2);
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'output';
        drawPin(ctx, node.position.x + node.width, pinY, false, node.state, isHovered);
    }

    ctx.restore();
  });

  // Draw Selection Box
  if (interactionState.mode === InteractionMode.SELECTING) {
    const startX = interactionState.dragStart.x;
    const startY = interactionState.dragStart.y;
    const currentX = currentMousePos.x;
    const currentY = currentMousePos.y;

    const width = currentX - startX;
    const height = currentY - startY;

    ctx.save();
    ctx.strokeStyle = '#00ccff';
    ctx.lineWidth = 1;
    ctx.fillStyle = 'rgba(0, 204, 255, 0.1)';
    ctx.fillRect(startX, startY, width, height);
    ctx.strokeRect(startX, startY, width, height);
    ctx.restore();
  }
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  CircuitNode, 
  Wire, 
  Camera, 
  InteractionMode, 
  InteractionState, 
  GateType,
  Position
} from './types';
import { COMPONENT_CONFIGS, COLORS } from './constants';
import { renderCircuit, screenToWorld, worldToScreen } from './services/renderer';
import { propagateCircuit } from './services/circuitEngine';
import Toolbar from './components/Toolbar';
import { ContextMenu } from './components/ContextMenu';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // State
  const [nodes, setNodes] = useState<CircuitNode[]>([]);
  const [wires, setWires] = useState<Wire[]>([]);
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, zoom: 1 });
  const [selectedNodeIds, setSelectedNodeIds] = useState<string[]>([]);
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; nodeId: string } | null>(null);

  // Interaction State
  const [interaction, setInteraction] = useState<InteractionState>({
    mode: InteractionMode.IDLE,
    hoveredNodeId: null,
    hoveredPin: null,
    dragStart: { x: 0, y: 0 },
    dragOffset: { x: 0, y: 0 },
    activeWireStart: null,
    placingType: null,
  });

  // Refs
  const nodesRef = useRef(nodes);
  const wiresRef = useRef(wires);
  const interactionRef = useRef(interaction);
  const cameraRef = useRef(camera);
  const mousePosRef = useRef<Position>({ x: 0, y: 0 });
  const selectedNodeIdsRef = useRef(selectedNodeIds);

  // Store initial positions of selected nodes when dragging starts
  const initialNodePositionsRef = useRef<Map<string, Position>>(new Map());

  // Sync refs
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { wiresRef.current = wires; }, [wires]);
  useEffect(() => { interactionRef.current = interaction; }, [interaction]);
  useEffect(() => { cameraRef.current = camera; }, [camera]);
  useEffect(() => { selectedNodeIdsRef.current = selectedNodeIds; }, [selectedNodeIds]);

  // Main Logic Loop (Clock & Propagation)
  useEffect(() => {
    const interval = setInterval(() => {
      let needsUpdate = false;
      const currentNodes = [...nodesRef.current];

      // Handle Clock Components
      currentNodes.forEach(node => {
        if (node.type === GateType.CLOCK) {
          node.state = !node.state;
          needsUpdate = true;
        }
      });

      if (needsUpdate) {
        const result = propagateCircuit(currentNodes, wiresRef.current);
        setNodes(result.nodes);
        setWires(result.wires);
      }
    }, 500); // 500ms Clock tick

    return () => clearInterval(interval);
  }, []);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;

    const render = () => {
      // Handle resize
      if (containerRef.current) {
        canvas.width = containerRef.current.clientWidth;
        canvas.height = containerRef.current.clientHeight;
      }

      const currentInteraction = interactionRef.current;

      renderCircuit(
        canvas, 
        ctx, 
        nodesRef.current, 
        wiresRef.current, 
        cameraRef.current, 
        currentInteraction,
        selectedNodeIdsRef.current,
        mousePosRef.current
      );

      // Draw active wire line if dragging
      if (currentInteraction.mode === InteractionMode.WIRING && currentInteraction.activeWireStart) {
        const { nodeId } = currentInteraction.activeWireStart;
        const node = nodesRef.current.find(n => n.id === nodeId);
        if (node) {
          const startX = node.position.x + node.width;
          const startY = node.position.y + node.height / 2;
          const s = worldToScreen(startX, startY, cameraRef.current);

          ctx.beginPath();
          ctx.moveTo(s.x, s.y);
          ctx.lineTo(mousePosRef.current.x, mousePosRef.current.y);
          ctx.strokeStyle = COLORS.wireActive;
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, []);

  // --- Actions ---
  const deleteSelected = () => {
    const idsToDelete = new Set(selectedNodeIdsRef.current);
    if (contextMenu?.nodeId && !idsToDelete.has(contextMenu.nodeId)) {
        idsToDelete.add(contextMenu.nodeId);
    }

    if (idsToDelete.size === 0) return;

    setNodes(prev => prev.filter(n => !idsToDelete.has(n.id)));
    setWires(prev => prev.filter(w => !idsToDelete.has(w.sourceNodeId) && !idsToDelete.has(w.targetNodeId)));
    setSelectedNodeIds([]);
    setContextMenu(null);
  };

  const duplicateSelected = () => {
    // If context menu was triggered on an unselected node, duplicate just that.
    // Otherwise duplicate the selection.
    let idsToDuplicate = selectedNodeIds;
    if (contextMenu?.nodeId && !idsToDuplicate.includes(contextMenu.nodeId)) {
      idsToDuplicate = [contextMenu.nodeId];
    }

    if (idsToDuplicate.length === 0) return;

    const newNodes: CircuitNode[] = [];
    const idMap = new Map<string, string>(); // oldId -> newId

    // 1. Clone Nodes
    idsToDuplicate.forEach(id => {
      const original = nodes.find(n => n.id === id);
      if (original) {
        const newId = generateId();
        idMap.set(id, newId);
        newNodes.push({
          ...original,
          id: newId,
          position: { x: original.position.x + 20, y: original.position.y + 20 },
          inputs: [...original.inputs], // Copy state
          state: original.state
        });
      }
    });

    // 2. Clone internal wires (wires connecting two duplicated nodes)
    const newWires: Wire[] = [];
    wires.forEach(w => {
      if (idMap.has(w.sourceNodeId) && idMap.has(w.targetNodeId)) {
        newWires.push({
          ...w,
          id: generateId(),
          sourceNodeId: idMap.get(w.sourceNodeId)!,
          targetNodeId: idMap.get(w.targetNodeId)!
        });
      }
    });

    setNodes(prev => [...prev, ...newNodes]);
    setWires(prev => [...prev, ...newWires]);

    // Select the new copies
    setSelectedNodeIds(newNodes.map(n => n.id));
    setContextMenu(null);
  };

  // --- Interaction Handlers ---

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();

    let targetNodeId = interaction.hoveredNodeId;

    // Logic: 
    // If we right-clicked a node that is already selected, keep selection as is.
    // If we right-clicked a node that is NOT selected, select ONLY that node.
    // If we right-clicked empty space, clear selection (handled in Mousedown usually, but good to handle here too).

    if (targetNodeId) {
      if (!selectedNodeIds.includes(targetNodeId)) {
        setSelectedNodeIds([targetNodeId]);
      }
      setContextMenu({
        x: e.clientX,
        y: e.clientY,
        nodeId: targetNodeId
      });
    } else {
        // Right click empty space? Maybe show global menu later. 
        // For now, allow standard pan or just clear
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (contextMenu) setContextMenu(null);

    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const worldPos = screenToWorld(x, y, camera);

    // Right click handled by ContextMenu or Pan
    if (e.button === 2) {
      if (!interaction.hoveredNodeId) {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.PANNING,
          dragStart: { x, y }
        }));
      }
      return;
    }

    // Placing Mode
    if (interaction.mode === InteractionMode.PLACING && interaction.placingType) {
      const config = COMPONENT_CONFIGS[interaction.placingType];
      const newNode: CircuitNode = {
        id: generateId(),
        type: interaction.placingType,
        position: { x: worldPos.x - config.width/2, y: worldPos.y - config.height/2 },
        width: config.width,
        height: config.height,
        inputs: new Array(config.inputCount).fill(false),
        state: false,
        label: config.label
      };

      setNodes(prev => [...prev, newNode]);
      // Select the new node
      setSelectedNodeIds([newNode.id]);
      return;
    }

    // Wiring Mode
    if (interaction.hoveredPin) {
      if (interaction.hoveredPin.type === 'output') {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.WIRING,
          activeWireStart: { nodeId: prev.hoveredPin!.nodeId, pinIndex: prev.hoveredPin!.index }
        }));
        setSelectedNodeIds([]); // Clear selection when starting to wire
      }
      return;
    }

    // Node Interaction (Selection / Dragging)
    if (interaction.hoveredNodeId) {
      const nodeId = interaction.hoveredNodeId;
      const isSelected = selectedNodeIds.includes(nodeId);
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;

      let newSelection = [...selectedNodeIds];

      if (isMultiSelectKey) {
        if (isSelected) {
          newSelection = newSelection.filter(id => id !== nodeId);
        } else {
          newSelection.push(nodeId);
        }
      } else {
        if (!isSelected) {
          newSelection = [nodeId];
        }
        // If already selected and no modifier, keep selection (might be starting a drag of the group)
      }

      setSelectedNodeIds(newSelection);

      // Prepare for Dragging
      const initialPosMap = new Map<string, Position>();
      nodes.forEach(n => {
        if (newSelection.includes(n.id)) {
          initialPosMap.set(n.id, { ...n.position });
        }
      });
      initialNodePositionsRef.current = initialPosMap;

      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.DRAGGING_NODE,
        dragStart: { x, y } // Screen coords for delta calc
      }));
      return;
    }

    // Empty Space -> Selection Box
    if (!interaction.hoveredNodeId) {
      if (!e.shiftKey && !e.ctrlKey) {
          setSelectedNodeIds([]);
      }
      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.SELECTING,
        dragStart: { x, y }
      }));
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    // Panning
    if (interaction.mode === InteractionMode.PANNING) {
      const dx = x - interaction.dragStart.x;
      const dy = y - interaction.dragStart.y;
      setCamera(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
      setInteraction(prev => ({ ...prev, dragStart: { x, y } }));
      return;
    }

    // Dragging Nodes (Multi)
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dx = (x - interaction.dragStart.x) / camera.zoom;
      const dy = (y - interaction.dragStart.y) / camera.zoom;

      setNodes(prev => prev.map(n => {
        if (initialNodePositionsRef.current.has(n.id)) {
            const initial = initialNodePositionsRef.current.get(n.id)!;
            return {
                ...n,
                position: { x: initial.x + dx, y: initial.y + dy }
            };
        }
        return n;
      }));
      return;
    }

    // Selection Box
    if (interaction.mode === InteractionMode.SELECTING) {
      // Calculate world rect
      const startWorld = screenToWorld(interaction.dragStart.x, interaction.dragStart.y, camera);
      const currentWorld = screenToWorld(x, y, camera);

      const minX = Math.min(startWorld.x, currentWorld.x);
      const maxX = Math.max(startWorld.x, currentWorld.x);
      const minY = Math.min(startWorld.y, currentWorld.y);
      const maxY = Math.max(startWorld.y, currentWorld.y);

      // Find nodes inside
      const enclosedIds = nodes
        .filter(n => 
          n.position.x >= minX && (n.position.x + n.width) <= maxX &&
          n.position.y >= minY && (n.position.y + n.height) <= maxY
        )
        .map(n => n.id);

      setSelectedNodeIds(enclosedIds);
      return;
    }

    // Hover Detection (IDLE or Wiring)
    if ([InteractionMode.IDLE, InteractionMode.WIRING, InteractionMode.PLACING].includes(interaction.mode)) {
      const worldPos = screenToWorld(x, y, camera);
      let foundNodeId: string | null = null;
      let foundPin: InteractionState['hoveredPin'] = null;

      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];
        const config = COMPONENT_CONFIGS[node.type];

        // Pins
        const pinSpacingIn = node.height / (config.inputCount + 1);
        for (let p = 0; p < config.inputCount; p++) {
          const px = node.position.x;
          const py = node.position.y + (pinSpacingIn * (p + 1));
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'input', index: p };
            break;
          }
        }
        if (foundPin) break;

        if (config.outputCount > 0) {
          const px = node.position.x + node.width;
          const py = node.position.y + node.height / 2;
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'output', index: 0 };
            break;
          }
        }
        if (foundPin) break;

        // Body
        if (worldPos.x >= node.position.x && worldPos.x <= node.position.x + node.width &&
            worldPos.y >= node.position.y && worldPos.y <= node.position.y + node.height) {
          foundNodeId = node.id;
          break;
        }
      }

      setInteraction(prev => ({
        ...prev,
        hoveredNodeId: foundNodeId,
        hoveredPin: foundPin
      }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    // Complete Wiring
    if (interaction.mode === InteractionMode.WIRING && interaction.hoveredPin && interaction.activeWireStart) {
      if (interaction.hoveredPin.type === 'input') {
        const newWire: Wire = {
          id: generateId(),
          sourceNodeId: interaction.activeWireStart.nodeId,
          sourcePinIndex: interaction.activeWireStart.pinIndex,
          targetNodeId: interaction.hoveredPin.nodeId,
          targetPinIndex: interaction.hoveredPin.index,
          state: false
        };

        const exists = wires.some(w => 
          w.targetNodeId === newWire.targetNodeId && w.targetPinIndex === newWire.targetPinIndex
        );

        if (!exists) {
          const newWires = [...wires, newWire];
          const res = propagateCircuit(nodes, newWires);
          setNodes(res.nodes);
          setWires(res.wires);
        }
      }
    }

    // Toggle Switch click handling
    // Check if we just clicked (not dragged) a switch
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      // Small delta check to see if it was a click
      const dist = Math.hypot(e.clientX - interaction.dragStart.x, e.clientY - interaction.dragStart.y);
      if (dist < 3 && interaction.hoveredNodeId) {
        const node = nodes.find(n => n.id === interaction.hoveredNodeId);
        if (node && node.type === GateType.INPUT_SWITCH) {
           const newNodes = nodes.map(n => 
             n.id === node.id ? { ...n, state: !n.state } : n
           );
           const res = propagateCircuit(newNodes, wires);
           setNodes(res.nodes);
           setWires(res.wires);
        }
      }
    }

    setInteraction(prev => ({
      ...prev,
      mode: prev.mode === InteractionMode.PLACING ? InteractionMode.PLACING : InteractionMode.IDLE,
      activeWireStart: null,
      dragStart: { x: 0, y: 0 }
    }));
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomIntensity = 0.1;
    const direction = e.deltaY > 0 ? -1 : 1;
    const newZoom = Math.min(Math.max(camera.zoom + (direction * zoomIntensity), 0.2), 3);
    setCamera(prev => ({ ...prev, zoom: newZoom }));
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      const idsToDelete = new Set(selectedNodeIdsRef.current);
      if (idsToDelete.size > 0) {
        setNodes(prev => prev.filter(n => !idsToDelete.has(n.id)));
        setWires(prev => prev.filter(w => !idsToDelete.has(w.sourceNodeId) && !idsToDelete.has(w.targetNodeId)));
        setSelectedNodeIds([]);
      }
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const selectTool = (mode: InteractionMode, gateType?: GateType) => {
    setInteraction(prev => ({
      ...prev,
      mode: mode,
      placingType: gateType || null
    }));
    if (mode !== InteractionMode.IDLE) {
      setSelectedNodeIds([]);
    }
  };

  return (
    <div className="relative w-screen h-screen bg-[#1e1e1e] overflow-hidden">
      <Toolbar 
        onSelectTool={selectTool} 
        currentMode={interaction.mode} 
        selectedGateType={interaction.placingType}
      />

      <div 
        ref={containerRef} 
        className="w-full h-full cursor-crosshair"
      >
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onContextMenu={handleContextMenu}
          onWheel={handleWheel}
          className="block"
        />
      </div>

      {contextMenu && (
        <ContextMenu 
          x={contextMenu.x} 
          y={contextMenu.y} 
          onDelete={deleteSelected}
          onDuplicate={duplicateSelected}
          onClose={() => setContextMenu(null)}
        />
      )}

      {/* Info overlay */}
      <div className="absolute top-4 right-4 pointer-events-none text-zinc-500 text-xs font-mono">
        Nodes: {nodes.length} | Wires: {wires.length} | Zoom: {Math.round(camera.zoom * 100)}% | Selected: {selectedNodeIds.length}
      </div>
    </div>
  );
};

export default App;

export enum GateType {
  AND = 'AND',
  OR = 'OR',
  NOT = 'NOT',
  NAND = 'NAND',
  NOR = 'NOR',
  XOR = 'XOR',
  INPUT_SWITCH = 'INPUT_SWITCH',
  OUTPUT_LAMP = 'OUTPUT_LAMP',
  CLOCK = 'CLOCK'
}

export interface Position {
  x: number;
  y: number;
}

export interface PinDef {
  id: string;
  type: 'input' | 'output';
  label?: string;
}

export interface CircuitNode {
  id: string;
  type: GateType;
  position: Position;
  state: boolean; // Main output state (High/Low)
  inputs: boolean[]; // Current state of inputs
  width: number;
  height: number;
  label: string;
}

export type WireCurveType = 'bezier' | 'straight' | 'step';

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourcePinIndex: number; // usually 0 for single output gates
  targetNodeId: string;
  targetPinIndex: number;
  state: boolean;
  curveType?: WireCurveType;
  color?: string;
}

export interface Camera {
  x: number;
  y: number;
  zoom: number;
}

export enum InteractionMode {
  IDLE = 'IDLE',
  PANNING = 'PANNING',
  DRAGGING_NODE = 'DRAGGING_NODE',
  WIRING = 'WIRING',
  PLACING = 'PLACING',
  SELECTING = 'SELECTING'
}

export interface InteractionState {
  mode: InteractionMode;
  hoveredNodeId: string | null;
  hoveredWireId: string | null;
  hoveredPin: { nodeId: string; type: 'input' | 'output'; index: number } | null;
  dragStart: Position; // Screen coordinates
  dragOffset: Position; // Offset from node center (Legacy/Single) or unused in multi-drag
  activeWireStart: { nodeId: string; pinIndex: number } | null;
  placingType: GateType | null;
}

import { CircuitNode, GateType, Wire, Camera, InteractionMode } from '../types';
import { COLORS, COMPONENT_CONFIGS, GRID_SIZE } from '../constants';

export const worldToScreen = (x: number, y: number, camera: Camera) => {
  return {
    x: (x * camera.zoom) + camera.x,
    y: (y * camera.zoom) + camera.y
  };
};

export const screenToWorld = (x: number, y: number, camera: Camera) => {
  return {
    x: (x - camera.x) / camera.zoom,
    y: (y - camera.y) / camera.zoom
  };
};

// --- Geometry Helpers for Hit Testing ---

const distToSegment = (px: number, py: number, x1: number, y1: number, x2: number, y2: number) => {
  const l2 = (x1 - x2) ** 2 + (y1 - y2) ** 2;
  if (l2 === 0) return Math.hypot(px - x1, py - y1);
  let t = ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1)));
};

// Samples a bezier curve to find approximate distance
const distToBezier = (
  px: number, py: number, 
  x0: number, y0: number, 
  cp1x: number, cp1y: number, 
  cp2x: number, cp2y: number, 
  x1: number, y1: number
) => {
  const SAMPLES = 10;
  let minD = Infinity;
  let prevX = x0;
  let prevY = y0;

  for (let i = 1; i <= SAMPLES; i++) {
    const t = i / SAMPLES;
    const invT = 1 - t;

    // Cubic Bezier Formula
    const currX = (invT ** 3) * x0 + 
                  3 * (invT ** 2) * t * cp1x + 
                  3 * invT * (t ** 2) * cp2x + 
                  (t ** 3) * x1;
    const currY = (invT ** 3) * y0 + 
                  3 * (invT ** 2) * t * cp1y + 
                  3 * invT * (t ** 2) * cp2y + 
                  (t ** 3) * y1;

    const d = distToSegment(px, py, prevX, prevY, currX, currY);
    if (d < minD) minD = d;

    prevX = currX;
    prevY = currY;
  }
  return minD;
};

export const checkWireHit = (
  worldX: number, 
  worldY: number, 
  wires: Wire[], 
  nodes: CircuitNode[]
): string | null => {
  const HIT_THRESHOLD = 8; // World units

  for (const wire of wires) {
    const sourceNode = nodes.find(n => n.id === wire.sourceNodeId);
    const targetNode = nodes.find(n => n.id === wire.targetNodeId);
    if (!sourceNode || !targetNode) continue;

    // Calculate start/end points exactly as they are drawn
    const startX = sourceNode.position.x + sourceNode.width;
    const startY = sourceNode.position.y + (sourceNode.height / 2);

    const inputCount = COMPONENT_CONFIGS[targetNode.type].inputCount;
    const pinSpacing = targetNode.height / (inputCount + 1);
    const endX = targetNode.position.x;
    const endY = targetNode.position.y + (pinSpacing * (wire.targetPinIndex + 1));

    const curveType = wire.curveType || 'bezier';
    let dist = Infinity;

    if (curveType === 'straight') {
      dist = distToSegment(worldX, worldY, startX, startY, endX, endY);
    } else if (curveType === 'step') {
      const midX = (startX + endX) / 2;
      const d1 = distToSegment(worldX, worldY, startX, startY, midX, startY);
      const d2 = distToSegment(worldX, worldY, midX, startY, midX, endY);
      const d3 = distToSegment(worldX, worldY, midX, endY, endX, endY);
      dist = Math.min(d1, d2, d3);
    } else {
      // Bezier
      const cpDist = Math.abs(endX - startX) * 0.5;
      dist = distToBezier(
        worldX, worldY, 
        startX, startY, 
        startX + cpDist, startY, 
        endX - cpDist, endY, 
        endX, endY
      );
    }

    if (dist < HIT_THRESHOLD) {
      return wire.id;
    }
  }

  return null;
};

// --- Drawing Functions ---

const drawPin = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  isInput: boolean, 
  active: boolean,
  isHovered: boolean
) => {
  const r = 5;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = active 
    ? (isInput ? COLORS.pinInput : COLORS.pinOutput) 
    : COLORS.componentBody;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = isHovered ? '#ffffff' : (isInput ? COLORS.pinInput : COLORS.pinOutput);
  ctx.stroke();
};

const drawIEEEGate = (ctx: CanvasRenderingContext2D, node: CircuitNode, selected: boolean) => {
  const { x, y } = node.position;
  const config = COMPONENT_CONFIGS[node.type];
  const w = node.width;
  const h = node.height;

  ctx.save();
  ctx.translate(x, y);

  // Body Path
  ctx.beginPath();
  ctx.lineWidth = selected ? 3 : 2;
  ctx.strokeStyle = selected ? COLORS.componentBorderSelected : COLORS.componentBorder;
  ctx.fillStyle = COLORS.componentBody;

  if (selected) {
    ctx.shadowColor = 'rgba(255, 255, 255, 0.5)';
    ctx.shadowBlur = 10;
  }

  switch (node.type) {
    case GateType.AND:
    case GateType.NAND:
      ctx.moveTo(0, 0);
      ctx.lineTo(w / 2, 0);
      ctx.arc(w / 2, h / 2, h / 2, -Math.PI / 2, Math.PI / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.OR:
    case GateType.NOR:
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      ctx.lineTo(w / 2, h); // Bottom flat-ish
      // OR curve is complex, approximating:
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(0, 0);
      break;
    case GateType.XOR:
      // Similar to OR but with the extra back curve line
      ctx.moveTo(10, 0);
      ctx.quadraticCurveTo(w / 4 + 10, h / 2, 10, h);
      ctx.lineTo(w / 2, h);
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(10, 0);

      // The second line for XOR
      ctx.stroke(); // Stroke body first
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      break;
    case GateType.NOT:
      ctx.moveTo(0, 0);
      ctx.lineTo(w - 10, h / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.INPUT_SWITCH:
      ctx.rect(0, 0, w, h);
      break;
    case GateType.OUTPUT_LAMP:
      ctx.arc(w/2, h/2, w/2 - 2, 0, Math.PI * 2);
      break;
    default:
      ctx.rect(0, 0, w, h);
  }

  ctx.fill();
  ctx.stroke();
  ctx.shadowBlur = 0; // Reset shadow

  // Negation Circle (NAND, NOR, NOT)
  if ([GateType.NAND, GateType.NOR, GateType.NOT].includes(node.type)) {
    ctx.beginPath();
    ctx.arc(w - 5, h / 2, 4, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.componentBody;
    ctx.fill();
    ctx.stroke();
  }

  // Visuals for Switch/Lamp
  if (node.type === GateType.INPUT_SWITCH) {
    ctx.beginPath();
    ctx.rect(10, 10, w - 20, h - 20);
    ctx.fillStyle = node.state ? COLORS.lampOn : '#111';
    ctx.fill();
    ctx.fillStyle = COLORS.textColor;
    ctx.font = '10px Inter';
    ctx.fillText(node.state ? 'ON' : 'OFF', w/2 - 8, h/2 + 3);
  }

  if (node.type === GateType.OUTPUT_LAMP) {
    ctx.beginPath();
    ctx.arc(w/2, h/2, w/2 - 8, 0, Math.PI * 2);
    ctx.fillStyle = node.state ? COLORS.lampOn : COLORS.lampOff;
    ctx.fill();

    if (node.state) {
        ctx.shadowColor = COLORS.lampOn;
        ctx.shadowBlur = 20;
        ctx.stroke();
        ctx.shadowBlur = 0;
    }
  }

  // Label
  if (node.type !== GateType.INPUT_SWITCH && node.type !== GateType.OUTPUT_LAMP) {
      ctx.fillStyle = COLORS.textColor;
      ctx.font = 'bold 12px Inter';
      ctx.textAlign = 'center';
      ctx.fillText(config.label, w / 2, h / 2 + 4);
  }

  ctx.restore();
};

export const renderCircuit = (
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  nodes: CircuitNode[],
  wires: Wire[],
  camera: Camera,
  interactionState: any,
  selectedNodeIds: string[],
  selectedWireIds: string[],
  currentMousePos: { x: number, y: number }
) => {
  const { width, height } = canvas;

  // Clear
  ctx.fillStyle = COLORS.background;
  ctx.fillRect(0, 0, width, height);

  // Grid
  ctx.save();
  ctx.beginPath();
  ctx.strokeStyle = COLORS.gridLines;
  ctx.lineWidth = 1;

  const startX = Math.floor((0 - camera.x) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const startY = Math.floor((0 - camera.y) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const endX = Math.floor((width - camera.x) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;
  const endY = Math.floor((height - camera.y) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;

  for (let x = startX; x <= endX; x += GRID_SIZE) {
    const screenX = (x * camera.zoom) + camera.x;
    ctx.moveTo(screenX, 0);
    ctx.lineTo(screenX, height);
  }
  for (let y = startY; y <= endY; y += GRID_SIZE) {
    const screenY = (y * camera.zoom) + camera.y;
    ctx.moveTo(0, screenY);
    ctx.lineTo(width, screenY);
  }
  ctx.stroke();
  ctx.restore();

  // Draw Wires
  wires.forEach(wire => {
    const sourceNode = nodes.find(n => n.id === wire.sourceNodeId);
    const targetNode = nodes.find(n => n.id === wire.targetNodeId);
    if (!sourceNode || !targetNode) return;

    const startX = sourceNode.position.x + sourceNode.width;
    const startY = sourceNode.position.y + (sourceNode.height / 2); 

    const inputCount = COMPONENT_CONFIGS[targetNode.type].inputCount;
    const pinSpacing = targetNode.height / (inputCount + 1);
    const endX = targetNode.position.x;
    const endY = targetNode.position.y + (pinSpacing * (wire.targetPinIndex + 1));

    const s = worldToScreen(startX, startY, camera);
    const e = worldToScreen(endX, endY, camera);

    ctx.beginPath();
    ctx.moveTo(s.x, s.y);

    const curveType = wire.curveType || 'bezier';

    if (curveType === 'straight') {
      ctx.lineTo(e.x, e.y);
    } else if (curveType === 'step') {
      const midX = (s.x + e.x) / 2;
      ctx.lineTo(midX, s.y);
      ctx.lineTo(midX, e.y);
      ctx.lineTo(e.x, e.y);
    } else {
      const cpDist = Math.abs(e.x - s.x) * 0.5;
      ctx.bezierCurveTo(s.x + cpDist, s.y, e.x - cpDist, e.y, e.x, e.y);
    }

    const isSelected = selectedWireIds.includes(wire.id);
    const isHovered = interactionState.hoveredWireId === wire.id;

    if (isSelected || isHovered) {
      // Draw highlight under the wire
      ctx.save();
      ctx.lineWidth = 6 * camera.zoom;
      ctx.strokeStyle = isSelected ? COLORS.componentBorderSelected : 'rgba(255, 255, 255, 0.3)';
      if (isSelected) {
        ctx.shadowColor = 'white';
        ctx.shadowBlur = 10;
      }
      ctx.stroke();
      ctx.restore();
    }

    if (wire.color) {
      ctx.strokeStyle = wire.color;
      if (wire.state) {
        ctx.shadowColor = wire.color;
        ctx.shadowBlur = 10;
      }
    } else {
      ctx.strokeStyle = wire.state ? COLORS.wireActive : COLORS.wireInactive;
      if (wire.state) {
        ctx.shadowColor = COLORS.wireActive;
        ctx.shadowBlur = 10;
      }
    }

    ctx.lineWidth = 3 * camera.zoom;
    ctx.stroke();
    ctx.shadowBlur = 0;
  });

  // Active wire creation line
  if (interactionState.mode === InteractionMode.WIRING && interactionState.activeWireStart) {
    const { nodeId, pinIndex } = interactionState.activeWireStart;
    const node = nodes.find(n => n.id === nodeId);
    if (node) {
        // ... (Drawing handled in App.tsx mainly, but placeholder here if needed)
    }
  }

  // Draw Nodes
  nodes.forEach(node => {
    ctx.save();
    ctx.setTransform(camera.zoom, 0, 0, camera.zoom, camera.x, camera.y);

    const isSelected = selectedNodeIds.includes(node.id);
    drawIEEEGate(ctx, node, isSelected);

    // Draw Pins
    const config = COMPONENT_CONFIGS[node.type];

    // Inputs
    const pinSpacingIn = node.height / (config.inputCount + 1);
    for (let i = 0; i < config.inputCount; i++) {
        const pinY = node.position.y + (pinSpacingIn * (i + 1));
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'input' 
            && interactionState.hoveredPin?.index === i;

        drawPin(ctx, node.position.x, pinY, true, node.inputs[i], isHovered);
    }

    // Outputs
    if (config.outputCount > 0) {
        const pinY = node.position.y + (node.height / 2);
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'output';
        drawPin(ctx, node.position.x + node.width, pinY, false, node.state, isHovered);
    }

    ctx.restore();
  });

  // Draw Selection Box
  if (interactionState.mode === InteractionMode.SELECTING) {
    const startX = interactionState.dragStart.x;
    const startY = interactionState.dragStart.y;
    const currentX = currentMousePos.x;
    const currentY = currentMousePos.y;

    const width = currentX - startX;
    const height = currentY - startY;

    ctx.save();
    ctx.strokeStyle = '#00ccff';
    ctx.lineWidth = 1;
    ctx.fillStyle = 'rgba(0, 204, 255, 0.1)';
    ctx.fillRect(startX, startY, width, height);
    ctx.strokeRect(startX, startY, width, height);
    ctx.restore();
  }
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  CircuitNode, 
  Wire, 
  Camera, 
  InteractionMode, 
  InteractionState, 
  GateType,
  Position
} from './types';
import { COMPONENT_CONFIGS, COLORS } from './constants';
import { renderCircuit, screenToWorld, worldToScreen, checkWireHit } from './services/renderer';
import { propagateCircuit } from './services/circuitEngine';
import Toolbar from './components/Toolbar';
import { ContextMenu } from './components/ContextMenu';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // State
  const [nodes, setNodes] = useState<CircuitNode[]>([]);
  const [wires, setWires] = useState<Wire[]>([]);
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, zoom: 1 });
  const [selectedNodeIds, setSelectedNodeIds] = useState<string[]>([]);
  const [selectedWireIds, setSelectedWireIds] = useState<string[]>([]);
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; nodeId: string } | null>(null);

  // Interaction State
  const [interaction, setInteraction] = useState<InteractionState>({
    mode: InteractionMode.IDLE,
    hoveredNodeId: null,
    hoveredWireId: null,
    hoveredPin: null,
    dragStart: { x: 0, y: 0 },
    dragOffset: { x: 0, y: 0 },
    activeWireStart: null,
    placingType: null,
  });

  // Refs
  const nodesRef = useRef(nodes);
  const wiresRef = useRef(wires);
  const interactionRef = useRef(interaction);
  const cameraRef = useRef(camera);
  const mousePosRef = useRef<Position>({ x: 0, y: 0 });
  const selectedNodeIdsRef = useRef(selectedNodeIds);
  const selectedWireIdsRef = useRef(selectedWireIds);

  // Store initial positions of selected nodes when dragging starts
  const initialNodePositionsRef = useRef<Map<string, Position>>(new Map());

  // Sync refs
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { wiresRef.current = wires; }, [wires]);
  useEffect(() => { interactionRef.current = interaction; }, [interaction]);
  useEffect(() => { cameraRef.current = camera; }, [camera]);
  useEffect(() => { selectedNodeIdsRef.current = selectedNodeIds; }, [selectedNodeIds]);
  useEffect(() => { selectedWireIdsRef.current = selectedWireIds; }, [selectedWireIds]);

  // Main Logic Loop (Clock & Propagation)
  useEffect(() => {
    const interval = setInterval(() => {
      let needsUpdate = false;
      const currentNodes = [...nodesRef.current];

      // Handle Clock Components
      currentNodes.forEach(node => {
        if (node.type === GateType.CLOCK) {
          node.state = !node.state;
          needsUpdate = true;
        }
      });

      if (needsUpdate) {
        const result = propagateCircuit(currentNodes, wiresRef.current);
        setNodes(result.nodes);
        setWires(result.wires);
      }
    }, 500); // 500ms Clock tick

    return () => clearInterval(interval);
  }, []);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;

    const render = () => {
      // Handle resize
      if (containerRef.current) {
        canvas.width = containerRef.current.clientWidth;
        canvas.height = containerRef.current.clientHeight;
      }

      const currentInteraction = interactionRef.current;

      renderCircuit(
        canvas, 
        ctx, 
        nodesRef.current, 
        wiresRef.current, 
        cameraRef.current, 
        currentInteraction,
        selectedNodeIdsRef.current,
        selectedWireIdsRef.current,
        mousePosRef.current
      );

      // Draw active wire line if dragging
      if (currentInteraction.mode === InteractionMode.WIRING && currentInteraction.activeWireStart) {
        const { nodeId } = currentInteraction.activeWireStart;
        const node = nodesRef.current.find(n => n.id === nodeId);
        if (node) {
          const startX = node.position.x + node.width;
          const startY = node.position.y + node.height / 2;
          const s = worldToScreen(startX, startY, cameraRef.current);

          ctx.beginPath();
          ctx.moveTo(s.x, s.y);
          ctx.lineTo(mousePosRef.current.x, mousePosRef.current.y);
          ctx.strokeStyle = COLORS.wireActive;
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, []);

  // --- Actions ---
  const deleteSelected = () => {
    // Collect ids
    const nodeIdsToDelete = new Set(selectedNodeIdsRef.current);
    const wireIdsToDelete = new Set(selectedWireIdsRef.current);

    // Add context menu target if applicable
    if (contextMenu?.nodeId && !nodeIdsToDelete.has(contextMenu.nodeId)) {
        nodeIdsToDelete.add(contextMenu.nodeId);
    }

    if (nodeIdsToDelete.size === 0 && wireIdsToDelete.size === 0) return;

    // Filter nodes
    setNodes(prev => prev.filter(n => !nodeIdsToDelete.has(n.id)));

    // Filter wires (remove if explicitly selected OR if attached to a deleted node)
    setWires(prev => prev.filter(w => 
      !wireIdsToDelete.has(w.id) && 
      !nodeIdsToDelete.has(w.sourceNodeId) && 
      !nodeIdsToDelete.has(w.targetNodeId)
    ));

    setSelectedNodeIds([]);
    setSelectedWireIds([]);
    setContextMenu(null);
  };

  const duplicateSelected = () => {
    // If context menu was triggered on an unselected node, duplicate just that.
    // Otherwise duplicate the selection.
    let idsToDuplicate = selectedNodeIds;
    if (contextMenu?.nodeId && !idsToDuplicate.includes(contextMenu.nodeId)) {
      idsToDuplicate = [contextMenu.nodeId];
    }

    if (idsToDuplicate.length === 0) return;

    const newNodes: CircuitNode[] = [];
    const idMap = new Map<string, string>(); // oldId -> newId

    // 1. Clone Nodes
    idsToDuplicate.forEach(id => {
      const original = nodes.find(n => n.id === id);
      if (original) {
        const newId = generateId();
        idMap.set(id, newId);
        newNodes.push({
          ...original,
          id: newId,
          position: { x: original.position.x + 20, y: original.position.y + 20 },
          inputs: [...original.inputs], // Copy state
          state: original.state
        });
      }
    });

    // 2. Clone internal wires (wires connecting two duplicated nodes)
    const newWires: Wire[] = [];
    wires.forEach(w => {
      if (idMap.has(w.sourceNodeId) && idMap.has(w.targetNodeId)) {
        newWires.push({
          ...w,
          id: generateId(),
          sourceNodeId: idMap.get(w.sourceNodeId)!,
          targetNodeId: idMap.get(w.targetNodeId)!
        });
      }
    });

    setNodes(prev => [...prev, ...newNodes]);
    setWires(prev => [...prev, ...newWires]);

    // Select the new copies
    setSelectedNodeIds(newNodes.map(n => n.id));
    setSelectedWireIds([]); // Do not auto-select duplicated wires for now
    setContextMenu(null);
  };

  // --- Interaction Handlers ---

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();

    let targetNodeId = interaction.hoveredNodeId;

    if (targetNodeId) {
      if (!selectedNodeIds.includes(targetNodeId)) {
        setSelectedNodeIds([targetNodeId]);
        setSelectedWireIds([]);
      }
      setContextMenu({
        x: e.clientX,
        y: e.clientY,
        nodeId: targetNodeId
      });
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (contextMenu) setContextMenu(null);

    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const worldPos = screenToWorld(x, y, camera);

    // Right click handled by ContextMenu or Pan
    if (e.button === 2) {
      if (!interaction.hoveredNodeId) {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.PANNING,
          dragStart: { x, y }
        }));
      }
      return;
    }

    // Placing Mode
    if (interaction.mode === InteractionMode.PLACING && interaction.placingType) {
      const config = COMPONENT_CONFIGS[interaction.placingType];
      const newNode: CircuitNode = {
        id: generateId(),
        type: interaction.placingType,
        position: { x: worldPos.x - config.width/2, y: worldPos.y - config.height/2 },
        width: config.width,
        height: config.height,
        inputs: new Array(config.inputCount).fill(false),
        state: false,
        label: config.label
      };

      setNodes(prev => [...prev, newNode]);
      setSelectedNodeIds([newNode.id]);
      setSelectedWireIds([]);
      return;
    }

    // Wiring Mode
    if (interaction.hoveredPin) {
      if (interaction.hoveredPin.type === 'output') {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.WIRING,
          activeWireStart: { nodeId: prev.hoveredPin!.nodeId, pinIndex: prev.hoveredPin!.index }
        }));
        setSelectedNodeIds([]); 
        setSelectedWireIds([]);
      }
      return;
    }

    // Node Interaction (Selection / Dragging)
    if (interaction.hoveredNodeId) {
      const nodeId = interaction.hoveredNodeId;
      const isSelected = selectedNodeIds.includes(nodeId);
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;

      let newSelection = [...selectedNodeIds];

      if (isMultiSelectKey) {
        if (isSelected) {
          newSelection = newSelection.filter(id => id !== nodeId);
        } else {
          newSelection.push(nodeId);
        }
      } else {
        if (!isSelected) {
          newSelection = [nodeId];
          setSelectedWireIds([]); // Clear wires if selecting a node without Shift
        }
      }

      setSelectedNodeIds(newSelection);

      // Prepare for Dragging
      const initialPosMap = new Map<string, Position>();
      nodes.forEach(n => {
        if (newSelection.includes(n.id)) {
          initialPosMap.set(n.id, { ...n.position });
        }
      });
      initialNodePositionsRef.current = initialPosMap;

      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.DRAGGING_NODE,
        dragStart: { x, y }
      }));
      return;
    }

    // Wire Selection Check (if no node or pin is hovered)
    // Check if we hit a wire using the logic in renderer
    const hitWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
    if (hitWireId) {
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;
      let newWireSelection = [...selectedWireIds];

      if (isMultiSelectKey) {
        if (newWireSelection.includes(hitWireId)) {
          newWireSelection = newWireSelection.filter(id => id !== hitWireId);
        } else {
          newWireSelection.push(hitWireId);
        }
      } else {
        newWireSelection = [hitWireId];
        setSelectedNodeIds([]); // Clear nodes if selecting wire without Shift
      }

      setSelectedWireIds(newWireSelection);
      return;
    }

    // Empty Space -> Selection Box
    if (!e.shiftKey && !e.ctrlKey) {
        setSelectedNodeIds([]);
        setSelectedWireIds([]);
    }
    setInteraction(prev => ({
      ...prev,
      mode: InteractionMode.SELECTING,
      dragStart: { x, y }
    }));
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    // Panning
    if (interaction.mode === InteractionMode.PANNING) {
      const dx = x - interaction.dragStart.x;
      const dy = y - interaction.dragStart.y;
      setCamera(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
      setInteraction(prev => ({ ...prev, dragStart: { x, y } }));
      return;
    }

    // Dragging Nodes
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dx = (x - interaction.dragStart.x) / camera.zoom;
      const dy = (y - interaction.dragStart.y) / camera.zoom;

      setNodes(prev => prev.map(n => {
        if (initialNodePositionsRef.current.has(n.id)) {
            const initial = initialNodePositionsRef.current.get(n.id)!;
            return {
                ...n,
                position: { x: initial.x + dx, y: initial.y + dy }
            };
        }
        return n;
      }));
      return;
    }

    // Selection Box
    if (interaction.mode === InteractionMode.SELECTING) {
      const startWorld = screenToWorld(interaction.dragStart.x, interaction.dragStart.y, camera);
      const currentWorld = screenToWorld(x, y, camera);

      const minX = Math.min(startWorld.x, currentWorld.x);
      const maxX = Math.max(startWorld.x, currentWorld.x);
      const minY = Math.min(startWorld.y, currentWorld.y);
      const maxY = Math.max(startWorld.y, currentWorld.y);

      const enclosedIds = nodes
        .filter(n => 
          n.position.x >= minX && (n.position.x + n.width) <= maxX &&
          n.position.y >= minY && (n.position.y + n.height) <= maxY
        )
        .map(n => n.id);

      setSelectedNodeIds(enclosedIds);
      // Optional: Select enclosed wires too? For now, stick to nodes.
      return;
    }

    // Hover Detection
    if ([InteractionMode.IDLE, InteractionMode.WIRING, InteractionMode.PLACING].includes(interaction.mode)) {
      const worldPos = screenToWorld(x, y, camera);
      let foundNodeId: string | null = null;
      let foundPin: InteractionState['hoveredPin'] = null;

      // Check Nodes & Pins
      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];
        const config = COMPONENT_CONFIGS[node.type];

        // Pins
        const pinSpacingIn = node.height / (config.inputCount + 1);
        for (let p = 0; p < config.inputCount; p++) {
          const px = node.position.x;
          const py = node.position.y + (pinSpacingIn * (p + 1));
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'input', index: p };
            break;
          }
        }
        if (foundPin) break;

        if (config.outputCount > 0) {
          const px = node.position.x + node.width;
          const py = node.position.y + node.height / 2;
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'output', index: 0 };
            break;
          }
        }
        if (foundPin) break;

        // Body
        if (worldPos.x >= node.position.x && worldPos.x <= node.position.x + node.width &&
            worldPos.y >= node.position.y && worldPos.y <= node.position.y + node.height) {
          foundNodeId = node.id;
          break;
        }
      }

      // Check Wires (Only if no node/pin hovered to avoid noise)
      let foundWireId: string | null = null;
      if (!foundNodeId && !foundPin) {
        foundWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
      }

      setInteraction(prev => ({
        ...prev,
        hoveredNodeId: foundNodeId,
        hoveredPin: foundPin,
        hoveredWireId: foundWireId
      }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    // Complete Wiring
    if (interaction.mode === InteractionMode.WIRING && interaction.hoveredPin && interaction.activeWireStart) {
      if (interaction.hoveredPin.type === 'input') {
        const newWire: Wire = {
          id: generateId(),
          sourceNodeId: interaction.activeWireStart.nodeId,
          sourcePinIndex: interaction.activeWireStart.pinIndex,
          targetNodeId: interaction.hoveredPin.nodeId,
          targetPinIndex: interaction.hoveredPin.index,
          state: false
        };

        const exists = wires.some(w => 
          w.targetNodeId === newWire.targetNodeId && w.targetPinIndex === newWire.targetPinIndex
        );

        if (!exists) {
          const newWires = [...wires, newWire];
          const res = propagateCircuit(nodes, newWires);
          setNodes(res.nodes);
          setWires(res.wires);
        }
      }
    }

    // Toggle Switch click handling
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dist = Math.hypot(e.clientX - interaction.dragStart.x, e.clientY - interaction.dragStart.y);
      if (dist < 3 && interaction.hoveredNodeId) {
        const node = nodes.find(n => n.id === interaction.hoveredNodeId);
        if (node && node.type === GateType.INPUT_SWITCH) {
           const newNodes = nodes.map(n => 
             n.id === node.id ? { ...n, state: !n.state } : n
           );
           const res = propagateCircuit(newNodes, wires);
           setNodes(res.nodes);
           setWires(res.wires);
        }
      }
    }

    setInteraction(prev => ({
      ...prev,
      mode: prev.mode === InteractionMode.PLACING ? InteractionMode.PLACING : InteractionMode.IDLE,
      activeWireStart: null,
      dragStart: { x: 0, y: 0 }
    }));
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomIntensity = 0.1;
    const direction = e.deltaY > 0 ? -1 : 1;
    const newZoom = Math.min(Math.max(camera.zoom + (direction * zoomIntensity), 0.2), 3);
    setCamera(prev => ({ ...prev, zoom: newZoom }));
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      deleteSelected();
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const selectTool = (mode: InteractionMode, gateType?: GateType) => {
    setInteraction(prev => ({
      ...prev,
      mode: mode,
      placingType: gateType || null
    }));
    if (mode !== InteractionMode.IDLE) {
      setSelectedNodeIds([]);
      setSelectedWireIds([]);
    }
  };

  return (
    <div className="relative w-screen h-screen bg-[#1e1e1e] overflow-hidden">
      <Toolbar 
        onSelectTool={selectTool} 
        currentMode={interaction.mode} 
        selectedGateType={interaction.placingType}
      />

      <div 
        ref={containerRef} 
        className="w-full h-full cursor-crosshair"
      >
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onContextMenu={handleContextMenu}
          onWheel={handleWheel}
          className="block"
        />
      </div>

      {contextMenu && (
        <ContextMenu 
          x={contextMenu.x} 
          y={contextMenu.y} 
          onDelete={deleteSelected}
          onDuplicate={duplicateSelected}
          onClose={() => setContextMenu(null)}
        />
      )}

      <div className="absolute top-4 right-4 pointer-events-none text-zinc-500 text-xs font-mono">
        Nodes: {nodes.length} | Wires: {wires.length} | Zoom: {Math.round(camera.zoom * 100)}% | Selected: {selectedNodeIds.length + selectedWireIds.length}
      </div>
    </div>
  );
};

export default App;

export enum GateType {
  AND = 'AND',
  OR = 'OR',
  NOT = 'NOT',
  NAND = 'NAND',
  NOR = 'NOR',
  XOR = 'XOR',
  INPUT_SWITCH = 'INPUT_SWITCH',
  OUTPUT_LAMP = 'OUTPUT_LAMP',
  CLOCK = 'CLOCK'
}

export interface Position {
  x: number;
  y: number;
}

export interface PinDef {
  id: string;
  type: 'input' | 'output';
  label?: string;
}

export interface CircuitNode {
  id: string;
  type: GateType;
  position: Position;
  state: boolean; // Main output state (High/Low)
  inputs: boolean[]; // Current state of inputs
  width: number;
  height: number;
  label: string;
  color?: string; // Optional custom color (e.g. for LEDs/Wires)
}

export type WireCurveType = 'bezier' | 'straight' | 'step';

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourcePinIndex: number; // usually 0 for single output gates
  targetNodeId: string;
  targetPinIndex: number;
  state: boolean;
  curveType?: WireCurveType;
  color?: string;
}

export interface Camera {
  x: number;
  y: number;
  zoom: number;
}

export enum InteractionMode {
  IDLE = 'IDLE',
  PANNING = 'PANNING',
  DRAGGING_NODE = 'DRAGGING_NODE',
  WIRING = 'WIRING',
  PLACING = 'PLACING',
  SELECTING = 'SELECTING'
}

export interface InteractionState {
  mode: InteractionMode;
  hoveredNodeId: string | null;
  hoveredWireId: string | null;
  hoveredPin: { nodeId: string; type: 'input' | 'output'; index: number } | null;
  dragStart: Position; // Screen coordinates
  dragOffset: Position; // Offset from node center (Legacy/Single) or unused in multi-drag
  activeWireStart: { nodeId: string; pinIndex: number } | null;
  placingType: GateType | null;
}

import { GateType } from './types';

// Palette from JSON requirements
export const COLORS = {
  background: '#1e1e1e',
  gridLines: '#2a2a2a',
  componentBody: '#333333',
  componentBorder: '#555555',
  componentBorderSelected: '#ffffff',
  textColor: '#e0e0e0',
  wireInactive: '#4a4a4a',
  wireActive: '#00ff41', // Neon Green
  pinInput: '#ffcc00',
  pinOutput: '#00ccff',
  lampOn: '#00ff41',
  lampOff: '#222222',
};

export const LED_COLORS = {
  GREEN: '#00ff41',
  RED: '#ff0033',
  BLUE: '#00ccff',
  YELLOW: '#ffcc00',
  WHITE: '#ffffff',
};

export const GRID_SIZE = 20;

export interface ComponentConfig {
  type: GateType;
  label: string;
  width: number;
  height: number;
  inputCount: number;
  outputCount: number;
  description: string;
}

export const COMPONENT_CONFIGS: Record<GateType, ComponentConfig> = {
  [GateType.AND]: { type: GateType.AND, label: 'AND', width: 80, height: 60, inputCount: 2, outputCount: 1, description: 'Output High only if all inputs are High.' },
  [GateType.OR]: { type: GateType.OR, label: 'OR', width: 80, height: 60, inputCount: 2, outputCount: 1, description: 'Output High if any input is High.' },
  [GateType.NOT]: { type: GateType.NOT, label: 'NOT', width: 60, height: 40, inputCount: 1, outputCount: 1, description: 'Inverts the input signal.' },
  [GateType.NAND]: { type: GateType.NAND, label: 'NAND', width: 80, height: 60, inputCount: 2, outputCount: 1, description: 'AND followed by NOT.' },
  [GateType.NOR]: { type: GateType.NOR, label: 'NOR', width: 80, height: 60, inputCount: 2, outputCount: 1, description: 'OR followed by NOT.' },
  [GateType.XOR]: { type: GateType.XOR, label: 'XOR', width: 80, height: 60, inputCount: 2, outputCount: 1, description: 'Exclusive OR.' },
  [GateType.INPUT_SWITCH]: { type: GateType.INPUT_SWITCH, label: 'SW', width: 50, height: 50, inputCount: 0, outputCount: 1, description: 'Toggle switch for logic High/Low.' },
  [GateType.OUTPUT_LAMP]: { type: GateType.OUTPUT_LAMP, label: 'LED', width: 50, height: 50, inputCount: 1, outputCount: 0, description: 'Visual indicator of signal state.' },
  [GateType.CLOCK]: { type: GateType.CLOCK, label: 'CLK', width: 50, height: 50, inputCount: 0, outputCount: 1, description: 'Toggles signal periodically.' },
};

import { CircuitNode, GateType, Wire, Camera, InteractionMode } from '../types';
import { COLORS, COMPONENT_CONFIGS, GRID_SIZE } from '../constants';

export const worldToScreen = (x: number, y: number, camera: Camera) => {
  return {
    x: (x * camera.zoom) + camera.x,
    y: (y * camera.zoom) + camera.y
  };
};

export const screenToWorld = (x: number, y: number, camera: Camera) => {
  return {
    x: (x - camera.x) / camera.zoom,
    y: (y - camera.y) / camera.zoom
  };
};

// --- Geometry Helpers for Hit Testing ---

const distToSegment = (px: number, py: number, x1: number, y1: number, x2: number, y2: number) => {
  const l2 = (x1 - x2) ** 2 + (y1 - y2) ** 2;
  if (l2 === 0) return Math.hypot(px - x1, py - y1);
  let t = ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1)));
};

// Samples a bezier curve to find approximate distance
const distToBezier = (
  px: number, py: number, 
  x0: number, y0: number, 
  cp1x: number, cp1y: number, 
  cp2x: number, cp2y: number, 
  x1: number, y1: number
) => {
  const SAMPLES = 10;
  let minD = Infinity;
  let prevX = x0;
  let prevY = y0;

  for (let i = 1; i <= SAMPLES; i++) {
    const t = i / SAMPLES;
    const invT = 1 - t;

    // Cubic Bezier Formula
    const currX = (invT ** 3) * x0 + 
                  3 * (invT ** 2) * t * cp1x + 
                  3 * invT * (t ** 2) * cp2x + 
                  (t ** 3) * x1;
    const currY = (invT ** 3) * y0 + 
                  3 * (invT ** 2) * t * cp1y + 
                  3 * invT * (t ** 2) * cp2y + 
                  (t ** 3) * y1;

    const d = distToSegment(px, py, prevX, prevY, currX, currY);
    if (d < minD) minD = d;

    prevX = currX;
    prevY = currY;
  }
  return minD;
};

export const checkWireHit = (
  worldX: number, 
  worldY: number, 
  wires: Wire[], 
  nodes: CircuitNode[]
): string | null => {
  const HIT_THRESHOLD = 8; // World units

  for (const wire of wires) {
    const sourceNode = nodes.find(n => n.id === wire.sourceNodeId);
    const targetNode = nodes.find(n => n.id === wire.targetNodeId);
    if (!sourceNode || !targetNode) continue;

    // Calculate start/end points exactly as they are drawn
    const startX = sourceNode.position.x + sourceNode.width;
    const startY = sourceNode.position.y + (sourceNode.height / 2);

    const inputCount = COMPONENT_CONFIGS[targetNode.type].inputCount;
    const pinSpacing = targetNode.height / (inputCount + 1);
    const endX = targetNode.position.x;
    const endY = targetNode.position.y + (pinSpacing * (wire.targetPinIndex + 1));

    const curveType = wire.curveType || 'bezier';
    let dist = Infinity;

    if (curveType === 'straight') {
      dist = distToSegment(worldX, worldY, startX, startY, endX, endY);
    } else if (curveType === 'step') {
      const midX = (startX + endX) / 2;
      const d1 = distToSegment(worldX, worldY, startX, startY, midX, startY);
      const d2 = distToSegment(worldX, worldY, midX, startY, midX, endY);
      const d3 = distToSegment(worldX, worldY, midX, endY, endX, endY);
      dist = Math.min(d1, d2, d3);
    } else {
      // Bezier
      const cpDist = Math.abs(endX - startX) * 0.5;
      dist = distToBezier(
        worldX, worldY, 
        startX, startY, 
        startX + cpDist, startY, 
        endX - cpDist, endY, 
        endX, endY
      );
    }

    if (dist < HIT_THRESHOLD) {
      return wire.id;
    }
  }

  return null;
};

// --- Drawing Functions ---

const drawPin = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  isInput: boolean, 
  active: boolean,
  isHovered: boolean
) => {
  const r = 5;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = active 
    ? (isInput ? COLORS.pinInput : COLORS.pinOutput) 
    : COLORS.componentBody;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = isHovered ? '#ffffff' : (isInput ? COLORS.pinInput : COLORS.pinOutput);
  ctx.stroke();
};

const drawIEEEGate = (ctx: CanvasRenderingContext2D, node: CircuitNode, selected: boolean) => {
  const { x, y } = node.position;
  const config = COMPONENT_CONFIGS[node.type];
  const w = node.width;
  const h = node.height;

  ctx.save();
  ctx.translate(x, y);

  // Body Path
  ctx.beginPath();
  ctx.lineWidth = selected ? 3 : 2;
  ctx.strokeStyle = selected ? COLORS.componentBorderSelected : COLORS.componentBorder;
  ctx.fillStyle = COLORS.componentBody;

  if (selected) {
    ctx.shadowColor = 'rgba(255, 255, 255, 0.5)';
    ctx.shadowBlur = 10;
  }

  switch (node.type) {
    case GateType.AND:
    case GateType.NAND:
      ctx.moveTo(0, 0);
      ctx.lineTo(w / 2, 0);
      ctx.arc(w / 2, h / 2, h / 2, -Math.PI / 2, Math.PI / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.OR:
    case GateType.NOR:
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      ctx.lineTo(w / 2, h); // Bottom flat-ish
      // OR curve is complex, approximating:
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(0, 0);
      break;
    case GateType.XOR:
      // Similar to OR but with the extra back curve line
      ctx.moveTo(10, 0);
      ctx.quadraticCurveTo(w / 4 + 10, h / 2, 10, h);
      ctx.lineTo(w / 2, h);
      ctx.quadraticCurveTo(w, h, w, h/2);
      ctx.quadraticCurveTo(w, 0, w/2, 0);
      ctx.lineTo(10, 0);

      // The second line for XOR
      ctx.stroke(); // Stroke body first
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(w / 4, h / 2, 0, h);
      break;
    case GateType.NOT:
      ctx.moveTo(0, 0);
      ctx.lineTo(w - 10, h / 2);
      ctx.lineTo(0, h);
      ctx.lineTo(0, 0);
      break;
    case GateType.INPUT_SWITCH:
      ctx.rect(0, 0, w, h);
      break;
    case GateType.OUTPUT_LAMP:
      ctx.arc(w/2, h/2, w/2 - 2, 0, Math.PI * 2);
      break;
    default:
      ctx.rect(0, 0, w, h);
  }

  ctx.fill();
  ctx.stroke();
  ctx.shadowBlur = 0; // Reset shadow

  // Negation Circle (NAND, NOR, NOT)
  if ([GateType.NAND, GateType.NOR, GateType.NOT].includes(node.type)) {
    ctx.beginPath();
    ctx.arc(w - 5, h / 2, 4, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.componentBody;
    ctx.fill();
    ctx.stroke();
  }

  // Visuals for Switch/Lamp
  if (node.type === GateType.INPUT_SWITCH) {
    ctx.beginPath();
    ctx.rect(10, 10, w - 20, h - 20);
    ctx.fillStyle = node.state ? COLORS.lampOn : '#111';
    ctx.fill();
    ctx.fillStyle = COLORS.textColor;
    ctx.font = '10px Inter';
    ctx.fillText(node.state ? 'ON' : 'OFF', w/2 - 8, h/2 + 3);
  }

  if (node.type === GateType.OUTPUT_LAMP) {
    ctx.beginPath();
    ctx.arc(w/2, h/2, w/2 - 8, 0, Math.PI * 2);

    // Custom color support
    const onColor = node.color || COLORS.lampOn;

    ctx.fillStyle = node.state ? onColor : COLORS.lampOff;
    ctx.fill();

    if (node.state) {
        ctx.shadowColor = onColor;
        ctx.shadowBlur = 20;
        ctx.stroke();
        ctx.shadowBlur = 0;
    }
  }

  // Label
  if (node.type !== GateType.INPUT_SWITCH && node.type !== GateType.OUTPUT_LAMP) {
      ctx.fillStyle = COLORS.textColor;
      ctx.font = 'bold 12px Inter';
      ctx.textAlign = 'center';
      ctx.fillText(config.label, w / 2, h / 2 + 4);
  }

  ctx.restore();
};

export const renderCircuit = (
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  nodes: CircuitNode[],
  wires: Wire[],
  camera: Camera,
  interactionState: any,
  selectedNodeIds: string[],
  selectedWireIds: string[],
  currentMousePos: { x: number, y: number }
) => {
  const { width, height } = canvas;

  // Clear
  ctx.fillStyle = COLORS.background;
  ctx.fillRect(0, 0, width, height);

  // Grid
  ctx.save();
  ctx.beginPath();
  ctx.strokeStyle = COLORS.gridLines;
  ctx.lineWidth = 1;

  const startX = Math.floor((0 - camera.x) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const startY = Math.floor((0 - camera.y) / camera.zoom / GRID_SIZE) * GRID_SIZE;
  const endX = Math.floor((width - camera.x) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;
  const endY = Math.floor((height - camera.y) / camera.zoom / GRID_SIZE + 1) * GRID_SIZE;

  for (let x = startX; x <= endX; x += GRID_SIZE) {
    const screenX = (x * camera.zoom) + camera.x;
    ctx.moveTo(screenX, 0);
    ctx.lineTo(screenX, height);
  }
  for (let y = startY; y <= endY; y += GRID_SIZE) {
    const screenY = (y * camera.zoom) + camera.y;
    ctx.moveTo(0, screenY);
    ctx.lineTo(width, screenY);
  }
  ctx.stroke();
  ctx.restore();

  // Draw Wires
  wires.forEach(wire => {
    const sourceNode = nodes.find(n => n.id === wire.sourceNodeId);
    const targetNode = nodes.find(n => n.id === wire.targetNodeId);
    if (!sourceNode || !targetNode) return;

    const startX = sourceNode.position.x + sourceNode.width;
    const startY = sourceNode.position.y + (sourceNode.height / 2); 

    const inputCount = COMPONENT_CONFIGS[targetNode.type].inputCount;
    const pinSpacing = targetNode.height / (inputCount + 1);
    const endX = targetNode.position.x;
    const endY = targetNode.position.y + (pinSpacing * (wire.targetPinIndex + 1));

    const s = worldToScreen(startX, startY, camera);
    const e = worldToScreen(endX, endY, camera);

    ctx.beginPath();
    ctx.moveTo(s.x, s.y);

    const curveType = wire.curveType || 'bezier';

    if (curveType === 'straight') {
      ctx.lineTo(e.x, e.y);
    } else if (curveType === 'step') {
      const midX = (s.x + e.x) / 2;
      ctx.lineTo(midX, s.y);
      ctx.lineTo(midX, e.y);
      ctx.lineTo(e.x, e.y);
    } else {
      const cpDist = Math.abs(e.x - s.x) * 0.5;
      ctx.bezierCurveTo(s.x + cpDist, s.y, e.x - cpDist, e.y, e.x, e.y);
    }

    const isSelected = selectedWireIds.includes(wire.id);
    const isHovered = interactionState.hoveredWireId === wire.id;

    if (isSelected || isHovered) {
      // Draw highlight under the wire
      ctx.save();
      ctx.lineWidth = 6 * camera.zoom;
      ctx.strokeStyle = isSelected ? COLORS.componentBorderSelected : 'rgba(255, 255, 255, 0.3)';
      if (isSelected) {
        ctx.shadowColor = 'white';
        ctx.shadowBlur = 10;
      }
      ctx.stroke();
      ctx.restore();
    }

    if (wire.color) {
      ctx.strokeStyle = wire.color;
      if (wire.state) {
        ctx.shadowColor = wire.color;
        ctx.shadowBlur = 10;
      }
    } else {
      ctx.strokeStyle = wire.state ? COLORS.wireActive : COLORS.wireInactive;
      if (wire.state) {
        ctx.shadowColor = COLORS.wireActive;
        ctx.shadowBlur = 10;
      }
    }

    ctx.lineWidth = 3 * camera.zoom;
    ctx.stroke();
    ctx.shadowBlur = 0;
  });

  // Active wire creation line
  if (interactionState.mode === InteractionMode.WIRING && interactionState.activeWireStart) {
    const { nodeId, pinIndex } = interactionState.activeWireStart;
    const node = nodes.find(n => n.id === nodeId);
    if (node) {
        // ... (Drawing handled in App.tsx mainly, but placeholder here if needed)
    }
  }

  // Draw Nodes
  nodes.forEach(node => {
    ctx.save();
    ctx.setTransform(camera.zoom, 0, 0, camera.zoom, camera.x, camera.y);

    const isSelected = selectedNodeIds.includes(node.id);
    drawIEEEGate(ctx, node, isSelected);

    // Draw Pins
    const config = COMPONENT_CONFIGS[node.type];

    // Inputs
    const pinSpacingIn = node.height / (config.inputCount + 1);
    for (let i = 0; i < config.inputCount; i++) {
        const pinY = node.position.y + (pinSpacingIn * (i + 1));
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'input' 
            && interactionState.hoveredPin?.index === i;

        drawPin(ctx, node.position.x, pinY, true, node.inputs[i], isHovered);
    }

    // Outputs
    if (config.outputCount > 0) {
        const pinY = node.position.y + (node.height / 2);
        const isHovered = interactionState.hoveredPin?.nodeId === node.id 
            && interactionState.hoveredPin?.type === 'output';
        drawPin(ctx, node.position.x + node.width, pinY, false, node.state, isHovered);
    }

    ctx.restore();
  });

  // Draw Selection Box
  if (interactionState.mode === InteractionMode.SELECTING) {
    const startX = interactionState.dragStart.x;
    const startY = interactionState.dragStart.y;
    const currentX = currentMousePos.x;
    const currentY = currentMousePos.y;

    const width = currentX - startX;
    const height = currentY - startY;

    ctx.save();
    ctx.strokeStyle = '#00ccff';
    ctx.lineWidth = 1;
    ctx.fillStyle = 'rgba(0, 204, 255, 0.1)';
    ctx.fillRect(startX, startY, width, height);
    ctx.strokeRect(startX, startY, width, height);
    ctx.restore();
  }
};

import React, { useEffect, useRef } from 'react';
import { Copy, Trash2 } from 'lucide-react';
import { GateType } from '../types';
import { LED_COLORS } from '../constants';

interface ContextMenuProps {
  x: number;
  y: number;
  nodeType?: GateType;
  currentColor?: string;
  onColorChange?: (color: string) => void;
  onDuplicate: () => void;
  onDelete: () => void;
  onClose: () => void;
}

export const ContextMenu: React.FC<ContextMenuProps> = ({ 
  x, 
  y, 
  nodeType, 
  currentColor, 
  onColorChange, 
  onDuplicate, 
  onDelete, 
  onClose 
}) => {
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onClose();
      }
    };
    // Use mousedown to detect outside clicks earlier than click
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  return (
    <div 
      ref={menuRef}
      className="fixed bg-zinc-800 border border-zinc-700 rounded-lg shadow-xl z-50 py-1 min-w-[160px] flex flex-col"
      style={{ top: y, left: x }}
    >
      {nodeType === GateType.OUTPUT_LAMP && onColorChange && (
        <div className="px-4 py-2 border-b border-zinc-700">
           <div className="text-[10px] text-zinc-500 mb-2 uppercase font-semibold">LED Color</div>
           <div className="flex gap-2">
             {Object.entries(LED_COLORS).map(([name, color]) => (
               <button
                 key={name}
                 onClick={(e) => { e.stopPropagation(); onColorChange(color); }}
                 className={`w-4 h-4 rounded-full border border-zinc-600 transition-transform hover:scale-110 cursor-pointer ${currentColor === color ? 'ring-1 ring-white' : ''}`}
                 style={{ backgroundColor: color, boxShadow: `0 0 5px ${color}40` }}
                 title={name}
               />
             ))}
           </div>
        </div>
      )}

      <button 
        onClick={(e) => { e.stopPropagation(); onDuplicate(); }}
        className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-zinc-700 hover:text-white flex items-center gap-2 transition-colors cursor-pointer"
      >
        <Copy size={14} />
        Duplicate
      </button>
      <button 
        onClick={(e) => { e.stopPropagation(); onDelete(); }}
        className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-zinc-700 hover:text-red-300 flex items-center gap-2 transition-colors cursor-pointer"
      >
        <Trash2 size={14} />
        Delete
      </button>
    </div>
  );
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  CircuitNode, 
  Wire, 
  Camera, 
  InteractionMode, 
  InteractionState, 
  GateType,
  Position
} from './types';
import { COMPONENT_CONFIGS, COLORS } from './constants';
import { renderCircuit, screenToWorld, worldToScreen, checkWireHit } from './services/renderer';
import { propagateCircuit } from './services/circuitEngine';
import Toolbar from './components/Toolbar';
import { ContextMenu } from './components/ContextMenu';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // State
  const [nodes, setNodes] = useState<CircuitNode[]>([]);
  const [wires, setWires] = useState<Wire[]>([]);
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, zoom: 1 });
  const [selectedNodeIds, setSelectedNodeIds] = useState<string[]>([]);
  const [selectedWireIds, setSelectedWireIds] = useState<string[]>([]);
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; nodeId: string } | null>(null);

  // Interaction State
  const [interaction, setInteraction] = useState<InteractionState>({
    mode: InteractionMode.IDLE,
    hoveredNodeId: null,
    hoveredWireId: null,
    hoveredPin: null,
    dragStart: { x: 0, y: 0 },
    dragOffset: { x: 0, y: 0 },
    activeWireStart: null,
    placingType: null,
  });

  // Refs
  const nodesRef = useRef(nodes);
  const wiresRef = useRef(wires);
  const interactionRef = useRef(interaction);
  const cameraRef = useRef(camera);
  const mousePosRef = useRef<Position>({ x: 0, y: 0 });
  const selectedNodeIdsRef = useRef(selectedNodeIds);
  const selectedWireIdsRef = useRef(selectedWireIds);

  // Store initial positions of selected nodes when dragging starts
  const initialNodePositionsRef = useRef<Map<string, Position>>(new Map());

  // Sync refs
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { wiresRef.current = wires; }, [wires]);
  useEffect(() => { interactionRef.current = interaction; }, [interaction]);
  useEffect(() => { cameraRef.current = camera; }, [camera]);
  useEffect(() => { selectedNodeIdsRef.current = selectedNodeIds; }, [selectedNodeIds]);
  useEffect(() => { selectedWireIdsRef.current = selectedWireIds; }, [selectedWireIds]);

  // Main Logic Loop (Clock & Propagation)
  useEffect(() => {
    const interval = setInterval(() => {
      let needsUpdate = false;
      const currentNodes = [...nodesRef.current];

      // Handle Clock Components
      currentNodes.forEach(node => {
        if (node.type === GateType.CLOCK) {
          node.state = !node.state;
          needsUpdate = true;
        }
      });

      if (needsUpdate) {
        const result = propagateCircuit(currentNodes, wiresRef.current);
        setNodes(result.nodes);
        setWires(result.wires);
      }
    }, 500); // 500ms Clock tick

    return () => clearInterval(interval);
  }, []);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;

    const render = () => {
      // Handle resize
      if (containerRef.current) {
        canvas.width = containerRef.current.clientWidth;
        canvas.height = containerRef.current.clientHeight;
      }

      const currentInteraction = interactionRef.current;

      renderCircuit(
        canvas, 
        ctx, 
        nodesRef.current, 
        wiresRef.current, 
        cameraRef.current, 
        currentInteraction,
        selectedNodeIdsRef.current,
        selectedWireIdsRef.current,
        mousePosRef.current
      );

      // Draw active wire line if dragging
      if (currentInteraction.mode === InteractionMode.WIRING && currentInteraction.activeWireStart) {
        const { nodeId } = currentInteraction.activeWireStart;
        const node = nodesRef.current.find(n => n.id === nodeId);
        if (node) {
          const startX = node.position.x + node.width;
          const startY = node.position.y + node.height / 2;
          const s = worldToScreen(startX, startY, cameraRef.current);

          ctx.beginPath();
          ctx.moveTo(s.x, s.y);
          ctx.lineTo(mousePosRef.current.x, mousePosRef.current.y);
          ctx.strokeStyle = COLORS.wireActive;
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, []);

  // --- Actions ---
  const deleteSelected = () => {
    // Collect ids
    const nodeIdsToDelete = new Set(selectedNodeIdsRef.current);
    const wireIdsToDelete = new Set(selectedWireIdsRef.current);

    // Add context menu target if applicable
    if (contextMenu?.nodeId && !nodeIdsToDelete.has(contextMenu.nodeId)) {
        nodeIdsToDelete.add(contextMenu.nodeId);
    }

    if (nodeIdsToDelete.size === 0 && wireIdsToDelete.size === 0) return;

    // Filter nodes
    setNodes(prev => prev.filter(n => !nodeIdsToDelete.has(n.id)));

    // Filter wires (remove if explicitly selected OR if attached to a deleted node)
    setWires(prev => prev.filter(w => 
      !wireIdsToDelete.has(w.id) && 
      !nodeIdsToDelete.has(w.sourceNodeId) && 
      !nodeIdsToDelete.has(w.targetNodeId)
    ));

    setSelectedNodeIds([]);
    setSelectedWireIds([]);
    setContextMenu(null);
  };

  const duplicateSelected = () => {
    // If context menu was triggered on an unselected node, duplicate just that.
    // Otherwise duplicate the selection.
    let idsToDuplicate = selectedNodeIds;
    if (contextMenu?.nodeId && !idsToDuplicate.includes(contextMenu.nodeId)) {
      idsToDuplicate = [contextMenu.nodeId];
    }

    if (idsToDuplicate.length === 0) return;

    const newNodes: CircuitNode[] = [];
    const idMap = new Map<string, string>(); // oldId -> newId

    // 1. Clone Nodes
    idsToDuplicate.forEach(id => {
      const original = nodes.find(n => n.id === id);
      if (original) {
        const newId = generateId();
        idMap.set(id, newId);
        newNodes.push({
          ...original,
          id: newId,
          position: { x: original.position.x + 20, y: original.position.y + 20 },
          inputs: [...original.inputs], // Copy state
          state: original.state,
          color: original.color
        });
      }
    });

    // 2. Clone internal wires (wires connecting two duplicated nodes)
    const newWires: Wire[] = [];
    wires.forEach(w => {
      if (idMap.has(w.sourceNodeId) && idMap.has(w.targetNodeId)) {
        newWires.push({
          ...w,
          id: generateId(),
          sourceNodeId: idMap.get(w.sourceNodeId)!,
          targetNodeId: idMap.get(w.targetNodeId)!
        });
      }
    });

    setNodes(prev => [...prev, ...newNodes]);
    setWires(prev => [...prev, ...newWires]);

    // Select the new copies
    setSelectedNodeIds(newNodes.map(n => n.id));
    setSelectedWireIds([]); // Do not auto-select duplicated wires for now
    setContextMenu(null);
  };

  // --- Interaction Handlers ---

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();

    let targetNodeId = interaction.hoveredNodeId;

    if (targetNodeId) {
      if (!selectedNodeIds.includes(targetNodeId)) {
        setSelectedNodeIds([targetNodeId]);
        setSelectedWireIds([]);
      }
      setContextMenu({
        x: e.clientX,
        y: e.clientY,
        nodeId: targetNodeId
      });
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (contextMenu) setContextMenu(null);

    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const worldPos = screenToWorld(x, y, camera);

    // Right click handled by ContextMenu or Pan
    if (e.button === 2) {
      if (!interaction.hoveredNodeId) {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.PANNING,
          dragStart: { x, y }
        }));
      }
      return;
    }

    // Placing Mode
    if (interaction.mode === InteractionMode.PLACING && interaction.placingType) {
      const config = COMPONENT_CONFIGS[interaction.placingType];
      const newNode: CircuitNode = {
        id: generateId(),
        type: interaction.placingType,
        position: { x: worldPos.x - config.width/2, y: worldPos.y - config.height/2 },
        width: config.width,
        height: config.height,
        inputs: new Array(config.inputCount).fill(false),
        state: false,
        label: config.label
      };

      setNodes(prev => [...prev, newNode]);
      setSelectedNodeIds([newNode.id]);
      setSelectedWireIds([]);
      return;
    }

    // Wiring Mode
    if (interaction.hoveredPin) {
      if (interaction.hoveredPin.type === 'output') {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.WIRING,
          activeWireStart: { nodeId: prev.hoveredPin!.nodeId, pinIndex: prev.hoveredPin!.index }
        }));
        setSelectedNodeIds([]); 
        setSelectedWireIds([]);
      }
      return;
    }

    // Node Interaction (Selection / Dragging)
    if (interaction.hoveredNodeId) {
      const nodeId = interaction.hoveredNodeId;
      const isSelected = selectedNodeIds.includes(nodeId);
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;

      let newSelection = [...selectedNodeIds];

      if (isMultiSelectKey) {
        if (isSelected) {
          newSelection = newSelection.filter(id => id !== nodeId);
        } else {
          newSelection.push(nodeId);
        }
      } else {
        if (!isSelected) {
          newSelection = [nodeId];
          setSelectedWireIds([]); // Clear wires if selecting a node without Shift
        }
      }

      setSelectedNodeIds(newSelection);

      // Prepare for Dragging
      const initialPosMap = new Map<string, Position>();
      nodes.forEach(n => {
        if (newSelection.includes(n.id)) {
          initialPosMap.set(n.id, { ...n.position });
        }
      });
      initialNodePositionsRef.current = initialPosMap;

      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.DRAGGING_NODE,
        dragStart: { x, y }
      }));
      return;
    }

    // Wire Selection Check (if no node or pin is hovered)
    // Check if we hit a wire using the logic in renderer
    const hitWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
    if (hitWireId) {
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;
      let newWireSelection = [...selectedWireIds];

      if (isMultiSelectKey) {
        if (newWireSelection.includes(hitWireId)) {
          newWireSelection = newWireSelection.filter(id => id !== hitWireId);
        } else {
          newWireSelection.push(hitWireId);
        }
      } else {
        newWireSelection = [hitWireId];
        setSelectedNodeIds([]); // Clear nodes if selecting wire without Shift
      }

      setSelectedWireIds(newWireSelection);
      return;
    }

    // Empty Space -> Selection Box
    if (!e.shiftKey && !e.ctrlKey) {
        setSelectedNodeIds([]);
        setSelectedWireIds([]);
    }
    setInteraction(prev => ({
      ...prev,
      mode: InteractionMode.SELECTING,
      dragStart: { x, y }
    }));
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    // Panning
    if (interaction.mode === InteractionMode.PANNING) {
      const dx = x - interaction.dragStart.x;
      const dy = y - interaction.dragStart.y;
      setCamera(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
      setInteraction(prev => ({ ...prev, dragStart: { x, y } }));
      return;
    }

    // Dragging Nodes
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dx = (x - interaction.dragStart.x) / camera.zoom;
      const dy = (y - interaction.dragStart.y) / camera.zoom;

      setNodes(prev => prev.map(n => {
        if (initialNodePositionsRef.current.has(n.id)) {
            const initial = initialNodePositionsRef.current.get(n.id)!;
            return {
                ...n,
                position: { x: initial.x + dx, y: initial.y + dy }
            };
        }
        return n;
      }));
      return;
    }

    // Selection Box
    if (interaction.mode === InteractionMode.SELECTING) {
      const startWorld = screenToWorld(interaction.dragStart.x, interaction.dragStart.y, camera);
      const currentWorld = screenToWorld(x, y, camera);

      const minX = Math.min(startWorld.x, currentWorld.x);
      const maxX = Math.max(startWorld.x, currentWorld.x);
      const minY = Math.min(startWorld.y, currentWorld.y);
      const maxY = Math.max(startWorld.y, currentWorld.y);

      const enclosedIds = nodes
        .filter(n => 
          n.position.x >= minX && (n.position.x + n.width) <= maxX &&
          n.position.y >= minY && (n.position.y + n.height) <= maxY
        )
        .map(n => n.id);

      setSelectedNodeIds(enclosedIds);
      // Optional: Select enclosed wires too? For now, stick to nodes.
      return;
    }

    // Hover Detection
    if ([InteractionMode.IDLE, InteractionMode.WIRING, InteractionMode.PLACING].includes(interaction.mode)) {
      const worldPos = screenToWorld(x, y, camera);
      let foundNodeId: string | null = null;
      let foundPin: InteractionState['hoveredPin'] = null;

      // Check Nodes & Pins
      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];
        const config = COMPONENT_CONFIGS[node.type];

        // Pins
        const pinSpacingIn = node.height / (config.inputCount + 1);
        for (let p = 0; p < config.inputCount; p++) {
          const px = node.position.x;
          const py = node.position.y + (pinSpacingIn * (p + 1));
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'input', index: p };
            break;
          }
        }
        if (foundPin) break;

        if (config.outputCount > 0) {
          const px = node.position.x + node.width;
          const py = node.position.y + node.height / 2;
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'output', index: 0 };
            break;
          }
        }
        if (foundPin) break;

        // Body
        if (worldPos.x >= node.position.x && worldPos.x <= node.position.x + node.width &&
            worldPos.y >= node.position.y && worldPos.y <= node.position.y + node.height) {
          foundNodeId = node.id;
          break;
        }
      }

      // Check Wires (Only if no node/pin hovered to avoid noise)
      let foundWireId: string | null = null;
      if (!foundNodeId && !foundPin) {
        foundWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
      }

      setInteraction(prev => ({
        ...prev,
        hoveredNodeId: foundNodeId,
        hoveredPin: foundPin,
        hoveredWireId: foundWireId
      }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    // Complete Wiring
    if (interaction.mode === InteractionMode.WIRING && interaction.hoveredPin && interaction.activeWireStart) {
      if (interaction.hoveredPin.type === 'input') {
        const newWire: Wire = {
          id: generateId(),
          sourceNodeId: interaction.activeWireStart.nodeId,
          sourcePinIndex: interaction.activeWireStart.pinIndex,
          targetNodeId: interaction.hoveredPin.nodeId,
          targetPinIndex: interaction.hoveredPin.index,
          state: false
        };

        const exists = wires.some(w => 
          w.targetNodeId === newWire.targetNodeId && w.targetPinIndex === newWire.targetPinIndex
        );

        if (!exists) {
          const newWires = [...wires, newWire];
          const res = propagateCircuit(nodes, newWires);
          setNodes(res.nodes);
          setWires(res.wires);
        }
      }
    }

    // Toggle Switch click handling
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dist = Math.hypot(e.clientX - interaction.dragStart.x, e.clientY - interaction.dragStart.y);
      if (dist < 3 && interaction.hoveredNodeId) {
        const node = nodes.find(n => n.id === interaction.hoveredNodeId);
        if (node && node.type === GateType.INPUT_SWITCH) {
           const newNodes = nodes.map(n => 
             n.id === node.id ? { ...n, state: !n.state } : n
           );
           const res = propagateCircuit(newNodes, wires);
           setNodes(res.nodes);
           setWires(res.wires);
        }
      }
    }

    setInteraction(prev => ({
      ...prev,
      mode: prev.mode === InteractionMode.PLACING ? InteractionMode.PLACING : InteractionMode.IDLE,
      activeWireStart: null,
      dragStart: { x: 0, y: 0 }
    }));
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomIntensity = 0.1;
    const direction = e.deltaY > 0 ? -1 : 1;
    const newZoom = Math.min(Math.max(camera.zoom + (direction * zoomIntensity), 0.2), 3);
    setCamera(prev => ({ ...prev, zoom: newZoom }));
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      deleteSelected();
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const selectTool = (mode: InteractionMode, gateType?: GateType) => {
    setInteraction(prev => ({
      ...prev,
      mode: mode,
      placingType: gateType || null
    }));
    if (mode !== InteractionMode.IDLE) {
      setSelectedNodeIds([]);
      setSelectedWireIds([]);
    }
  };

  return (
    <div className="relative w-screen h-screen bg-[#1e1e1e] overflow-hidden">
      <Toolbar 
        onSelectTool={selectTool} 
        currentMode={interaction.mode} 
        selectedGateType={interaction.placingType}
      />

      <div 
        ref={containerRef} 
        className="w-full h-full cursor-crosshair"
      >
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onContextMenu={handleContextMenu}
          onWheel={handleWheel}
          className="block"
        />
      </div>

      {contextMenu && (
        <ContextMenu 
          x={contextMenu.x} 
          y={contextMenu.y} 
          nodeType={nodes.find(n => n.id === contextMenu.nodeId)?.type}
          currentColor={nodes.find(n => n.id === contextMenu.nodeId)?.color}
          onColorChange={(color) => {
             setNodes(prev => prev.map(n => n.id === contextMenu.nodeId ? { ...n, color } : n));
          }}
          onDelete={deleteSelected}
          onDuplicate={duplicateSelected}
          onClose={() => setContextMenu(null)}
        />
      )}

      <div className="absolute top-4 right-4 pointer-events-none text-zinc-500 text-xs font-mono">
        Nodes: {nodes.length} | Wires: {wires.length} | Zoom: {Math.round(camera.zoom * 100)}% | Selected: {selectedNodeIds.length + selectedWireIds.length}
      </div>
    </div>
  );
};

