export default Toolbar;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  CircuitNode, 
  Wire, 
  Camera, 
  InteractionMode, 
  InteractionState, 
  GateType,
  Position,
  ProjectData
} from './types';
import { COMPONENT_CONFIGS, COLORS, PIN_SPACING } from './constants';
import { renderCircuit, screenToWorld, worldToScreen, checkWireHit } from './services/renderer';
import { propagateCircuit } from './services/circuitEngine';
import { generateCircuitFromTruthTable } from './services/quineMcCluskey';
import Toolbar from './components/Toolbar';
import { ContextMenu } from './components/ContextMenu';
import { KarnaughModal } from './components/KarnaughModal';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // State
  const [nodes, setNodes] = useState<CircuitNode[]>([]);
  const [wires, setWires] = useState<Wire[]>([]);
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, zoom: 1 });
  const [selectedNodeIds, setSelectedNodeIds] = useState<string[]>([]);
  const [selectedWireIds, setSelectedWireIds] = useState<string[]>([]);
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; nodeId: string } | null>(null);
  const [isKarnaughOpen, setIsKarnaughOpen] = useState(false);

  // Interaction State
  const [interaction, setInteraction] = useState<InteractionState>({
    mode: InteractionMode.IDLE,
    hoveredNodeId: null,
    hoveredWireId: null,
    hoveredPin: null,
    dragStart: { x: 0, y: 0 },
    dragOffset: { x: 0, y: 0 },
    activeWireStart: null,
    placingType: null,
  });

  // Refs
  const nodesRef = useRef(nodes);
  const wiresRef = useRef(wires);
  const interactionRef = useRef(interaction);
  const cameraRef = useRef(camera);
  const mousePosRef = useRef<Position>({ x: 0, y: 0 });
  const selectedNodeIdsRef = useRef(selectedNodeIds);
  const selectedWireIdsRef = useRef(selectedWireIds);

  // Store initial positions of selected nodes when dragging starts
  const initialNodePositionsRef = useRef<Map<string, Position>>(new Map());

  // Sync refs
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { wiresRef.current = wires; }, [wires]);
  useEffect(() => { interactionRef.current = interaction; }, [interaction]);
  useEffect(() => { cameraRef.current = camera; }, [camera]);
  useEffect(() => { selectedNodeIdsRef.current = selectedNodeIds; }, [selectedNodeIds]);
  useEffect(() => { selectedWireIdsRef.current = selectedWireIds; }, [selectedWireIds]);

  // Main Logic Loop (Clock & Propagation)
  useEffect(() => {
    const interval = setInterval(() => {
      let needsUpdate = false;
      const currentNodes = [...nodesRef.current];

      // Handle Clock Components
      currentNodes.forEach(node => {
        if (node.type === GateType.CLOCK) {
          node.state = !node.state;
          needsUpdate = true;
        }
      });

      if (needsUpdate) {
        const result = propagateCircuit(currentNodes, wiresRef.current);
        setNodes(result.nodes);
        setWires(result.wires);
      }
    }, 500); // 500ms Clock tick

    return () => clearInterval(interval);
  }, []);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;

    const render = () => {
      // Handle resize
      if (containerRef.current) {
        canvas.width = containerRef.current.clientWidth;
        canvas.height = containerRef.current.clientHeight;
      }

      const currentInteraction = interactionRef.current;

      renderCircuit(
        canvas, 
        ctx, 
        nodesRef.current, 
        wiresRef.current, 
        cameraRef.current, 
        currentInteraction,
        selectedNodeIdsRef.current,
        selectedWireIdsRef.current,
        mousePosRef.current
      );

      // Draw active wire line if dragging
      if (currentInteraction.mode === InteractionMode.WIRING && currentInteraction.activeWireStart) {
        const { nodeId } = currentInteraction.activeWireStart;
        const node = nodesRef.current.find(n => n.id === nodeId);
        if (node) {
          const startX = node.position.x + node.width;
          const startY = node.position.y + node.height / 2;
          const s = worldToScreen(startX, startY, cameraRef.current);

          ctx.beginPath();
          ctx.moveTo(s.x, s.y);
          ctx.lineTo(mousePosRef.current.x, mousePosRef.current.y);
          ctx.strokeStyle = COLORS.wireActive;
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, []);

  // --- Actions ---
  const deleteSelected = () => {
    // Collect ids
    const nodeIdsToDelete = new Set(selectedNodeIdsRef.current);
    const wireIdsToDelete = new Set(selectedWireIdsRef.current);

    // Add context menu target if applicable
    if (contextMenu?.nodeId && !nodeIdsToDelete.has(contextMenu.nodeId)) {
        nodeIdsToDelete.add(contextMenu.nodeId);
    }

    if (nodeIdsToDelete.size === 0 && wireIdsToDelete.size === 0) return;

    // Filter nodes
    setNodes(prev => prev.filter(n => !nodeIdsToDelete.has(n.id)));

    // Filter wires (remove if explicitly selected OR if attached to a deleted node)
    setWires(prev => prev.filter(w => 
      !wireIdsToDelete.has(w.id) && 
      !nodeIdsToDelete.has(w.sourceNodeId) && 
      !nodeIdsToDelete.has(w.targetNodeId)
    ));

    setSelectedNodeIds([]);
    setSelectedWireIds([]);
    setContextMenu(null);
  };

  const duplicateSelected = () => {
    // If context menu was triggered on an unselected node, duplicate just that.
    // Otherwise duplicate the selection.
    let idsToDuplicate = selectedNodeIds;
    if (contextMenu?.nodeId && !idsToDuplicate.includes(contextMenu.nodeId)) {
      idsToDuplicate = [contextMenu.nodeId];
    }

    if (idsToDuplicate.length === 0) return;

    const newNodes: CircuitNode[] = [];
    const idMap = new Map<string, string>(); // oldId -> newId

    // 1. Clone Nodes
    idsToDuplicate.forEach(id => {
      const original = nodes.find(n => n.id === id);
      if (original) {
        const newId = generateId();
        idMap.set(id, newId);
        newNodes.push({
          ...original,
          id: newId,
          position: { x: original.position.x + 20, y: original.position.y + 20 },
          inputs: [...original.inputs], // Copy state
          state: original.state,
          color: original.color
        });
      }
    });

    // 2. Clone internal wires (wires connecting two duplicated nodes)
    const newWires: Wire[] = [];
    wires.forEach(w => {
      if (idMap.has(w.sourceNodeId) && idMap.has(w.targetNodeId)) {
        newWires.push({
          ...w,
          id: generateId(),
          sourceNodeId: idMap.get(w.sourceNodeId)!,
          targetNodeId: idMap.get(w.targetNodeId)!
        });
      }
    });

    setNodes(prev => [...prev, ...newNodes]);
    setWires(prev => [...prev, ...newWires]);

    // Select the new copies
    setSelectedNodeIds(newNodes.map(n => n.id));
    setSelectedWireIds([]); // Do not auto-select duplicated wires for now
    setContextMenu(null);
  };

  const handleInputCountChange = (delta: number) => {
    if (!contextMenu?.nodeId) return;

    const nodeId = contextMenu.nodeId;

    setNodes(prevNodes => prevNodes.map(node => {
      if (node.id !== nodeId) return node;

      const currentCount = node.inputs.length;
      const newCount = Math.min(8, Math.max(2, currentCount + delta));

      if (newCount === currentCount) return node;

      let newInputs = [...node.inputs];

      if (newCount > currentCount) {
        // Add inputs (default false)
        for(let i = 0; i < (newCount - currentCount); i++) {
            newInputs.push(false);
        }
      } else {
        // Remove inputs from end
        newInputs = newInputs.slice(0, newCount);

        // Remove wires connected to deleted pins
        setWires(prevWires => prevWires.filter(w => 
           !(w.targetNodeId === nodeId && w.targetPinIndex >= newCount)
        ));
      }

      // Calculate new height based on pin count + 1 gap for top/bottom margin
      // 2 inputs = 3 spaces * 20px = 60px (Standard)
      // 8 inputs = 9 spaces * 20px = 180px
      const newHeight = (newCount + 1) * PIN_SPACING;

      return {
        ...node,
        inputs: newInputs,
        height: newHeight
      };
    }));
  };

  // --- Save / Load ---

  const handleSaveProject = () => {
    const projectData: ProjectData = {
      version: '1.0.0',
      nodes: nodes,
      wires: wires,
      camera: camera
    };

    const blob = new Blob([JSON.stringify(projectData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `circuit-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleLoadProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const projectData = JSON.parse(content) as ProjectData;

        // Basic validation
        if (Array.isArray(projectData.nodes) && Array.isArray(projectData.wires)) {
          setNodes(projectData.nodes);
          setWires(projectData.wires);
          if (projectData.camera) {
            setCamera(projectData.camera);
          }
          // Reset selection
          setSelectedNodeIds([]);
          setSelectedWireIds([]);
        } else {
          alert("Invalid project file format.");
        }
      } catch (err) {
        console.error("Failed to parse project file", err);
        alert("Failed to load project file.");
      }
    };
    reader.readAsText(file);
  };

  // --- Karnaugh Generator ---

  const handleKarnaughGenerate = (numVars: number, truthTable: boolean[]) => {
    // Determine spawn position (center of current view)
    const centerWorld = screenToWorld(
        (containerRef.current?.clientWidth || 800) / 2,
        (containerRef.current?.clientHeight || 600) / 2,
        camera
    );
    // Shift slightly left so the circuit centers better
    centerWorld.x -= 300; 
    centerWorld.y -= 200;

    const { nodes: newNodes, wires: newWires } = generateCircuitFromTruthTable(
        numVars, 
        truthTable, 
        centerWorld
    );

    // Merge into existing circuit
    setNodes(prev => [...prev, ...newNodes]);
    setWires(prev => [...prev, ...newWires]);
    setIsKarnaughOpen(false);
  };


  // --- Interaction Handlers ---

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();

    let targetNodeId = interaction.hoveredNodeId;

    if (targetNodeId) {
      if (!selectedNodeIds.includes(targetNodeId)) {
        setSelectedNodeIds([targetNodeId]);
        setSelectedWireIds([]);
      }
      setContextMenu({
        x: e.clientX,
        y: e.clientY,
        nodeId: targetNodeId
      });
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (contextMenu) setContextMenu(null);

    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const worldPos = screenToWorld(x, y, camera);

    // Right click handled by ContextMenu or Pan
    if (e.button === 2) {
      if (!interaction.hoveredNodeId) {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.PANNING,
          dragStart: { x, y }
        }));
      }
      return;
    }

    // Placing Mode
    if (interaction.mode === InteractionMode.PLACING && interaction.placingType) {
      const config = COMPONENT_CONFIGS[interaction.placingType];
      const newNode: CircuitNode = {
        id: generateId(),
        type: interaction.placingType,
        position: { x: worldPos.x - config.width/2, y: worldPos.y - config.height/2 },
        width: config.width,
        height: config.height,
        inputs: new Array(config.inputCount).fill(false),
        state: false,
        label: config.label
      };

      setNodes(prev => [...prev, newNode]);
      setSelectedNodeIds([newNode.id]);
      setSelectedWireIds([]);
      return;
    }

    // Wiring Mode
    if (interaction.hoveredPin) {
      if (interaction.hoveredPin.type === 'output') {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.WIRING,
          activeWireStart: { nodeId: prev.hoveredPin!.nodeId, pinIndex: prev.hoveredPin!.index }
        }));
        setSelectedNodeIds([]); 
        setSelectedWireIds([]);
      }
      return;
    }

    // Node Interaction (Selection / Dragging)
    if (interaction.hoveredNodeId) {
      const nodeId = interaction.hoveredNodeId;
      const isSelected = selectedNodeIds.includes(nodeId);
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;

      let newSelection = [...selectedNodeIds];

      if (isMultiSelectKey) {
        if (isSelected) {
          newSelection = newSelection.filter(id => id !== nodeId);
        } else {
          newSelection.push(nodeId);
        }
      } else {
        if (!isSelected) {
          newSelection = [nodeId];
          setSelectedWireIds([]); // Clear wires if selecting a node without Shift
        }
      }

      setSelectedNodeIds(newSelection);

      // Prepare for Dragging
      const initialPosMap = new Map<string, Position>();
      nodes.forEach(n => {
        if (newSelection.includes(n.id)) {
          initialPosMap.set(n.id, { ...n.position });
        }
      });
      initialNodePositionsRef.current = initialPosMap;

      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.DRAGGING_NODE,
        dragStart: { x, y }
      }));
      return;
    }

    // Wire Selection Check (if no node or pin is hovered)
    // Check if we hit a wire using the logic in renderer
    const hitWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
    if (hitWireId) {
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;
      let newWireSelection = [...selectedWireIds];

      if (isMultiSelectKey) {
        if (newWireSelection.includes(hitWireId)) {
          newWireSelection = newWireSelection.filter(id => id !== hitWireId);
        } else {
          newWireSelection.push(hitWireId);
        }
      } else {
        newWireSelection = [hitWireId];
        setSelectedNodeIds([]); // Clear nodes if selecting wire without Shift
      }

      setSelectedWireIds(newWireSelection);
      return;
    }

    // Empty Space -> Selection Box
    if (!e.shiftKey && !e.ctrlKey) {
        setSelectedNodeIds([]);
        setSelectedWireIds([]);
    }
    setInteraction(prev => ({
      ...prev,
      mode: InteractionMode.SELECTING,
      dragStart: { x, y }
    }));
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    // Panning
    if (interaction.mode === InteractionMode.PANNING) {
      const dx = x - interaction.dragStart.x;
      const dy = y - interaction.dragStart.y;
      setCamera(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
      setInteraction(prev => ({ ...prev, dragStart: { x, y } }));
      return;
    }

    // Dragging Nodes
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dx = (x - interaction.dragStart.x) / camera.zoom;
      const dy = (y - interaction.dragStart.y) / camera.zoom;

      setNodes(prev => prev.map(n => {
        if (initialNodePositionsRef.current.has(n.id)) {
            const initial = initialNodePositionsRef.current.get(n.id)!;
            return {
                ...n,
                position: { x: initial.x + dx, y: initial.y + dy }
            };
        }
        return n;
      }));
      return;
    }

    // Selection Box
    if (interaction.mode === InteractionMode.SELECTING) {
      const startWorld = screenToWorld(interaction.dragStart.x, interaction.dragStart.y, camera);
      const currentWorld = screenToWorld(x, y, camera);

      const minX = Math.min(startWorld.x, currentWorld.x);
      const maxX = Math.max(startWorld.x, currentWorld.x);
      const minY = Math.min(startWorld.y, currentWorld.y);
      const maxY = Math.max(startWorld.y, currentWorld.y);

      const enclosedIds = nodes
        .filter(n => 
          n.position.x >= minX && (n.position.x + n.width) <= maxX &&
          n.position.y >= minY && (n.position.y + n.height) <= maxY
        )
        .map(n => n.id);

      setSelectedNodeIds(enclosedIds);
      // Optional: Select enclosed wires too? For now, stick to nodes.
      return;
    }

    // Hover Detection
    if ([InteractionMode.IDLE, InteractionMode.WIRING, InteractionMode.PLACING].includes(interaction.mode)) {
      const worldPos = screenToWorld(x, y, camera);
      let foundNodeId: string | null = null;
      let foundPin: InteractionState['hoveredPin'] = null;

      // Check Nodes & Pins
      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];
        const config = COMPONENT_CONFIGS[node.type];

        // Pins - Dynamic Check
        const inputCount = node.inputs.length;
        const pinSpacingIn = node.height / (inputCount + 1);
        for (let p = 0; p < inputCount; p++) {
          const px = node.position.x;
          const py = node.position.y + (pinSpacingIn * (p + 1));
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'input', index: p };
            break;
          }
        }
        if (foundPin) break;

        if (config.outputCount > 0) {
          const px = node.position.x + node.width;
          const py = node.position.y + node.height / 2;
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'output', index: 0 };
            break;
          }
        }
        if (foundPin) break;

        // Body
        if (worldPos.x >= node.position.x && worldPos.x <= node.position.x + node.width &&
            worldPos.y >= node.position.y && worldPos.y <= node.position.y + node.height) {
          foundNodeId = node.id;
          break;
        }
      }

      // Check Wires (Only if no node/pin hovered to avoid noise)
      let foundWireId: string | null = null;
      if (!foundNodeId && !foundPin) {
        foundWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
      }

      setInteraction(prev => ({
        ...prev,
        hoveredNodeId: foundNodeId,
        hoveredPin: foundPin,
        hoveredWireId: foundWireId
      }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    // Complete Wiring
    if (interaction.mode === InteractionMode.WIRING && interaction.hoveredPin && interaction.activeWireStart) {
      if (interaction.hoveredPin.type === 'input') {
        const newWire: Wire = {
          id: generateId(),
          sourceNodeId: interaction.activeWireStart.nodeId,
          sourcePinIndex: interaction.activeWireStart.pinIndex,
          targetNodeId: interaction.hoveredPin.nodeId,
          targetPinIndex: interaction.hoveredPin.index,
          state: false
        };

        const exists = wires.some(w => 
          w.targetNodeId === newWire.targetNodeId && w.targetPinIndex === newWire.targetPinIndex
        );

        if (!exists) {
          const newWires = [...wires, newWire];
          const res = propagateCircuit(nodes, newWires);
          setNodes(res.nodes);
          setWires(res.wires);
        }
      }
    }

    // Toggle Switch click handling
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dist = Math.hypot(e.clientX - interaction.dragStart.x, e.clientY - interaction.dragStart.y);
      if (dist < 3 && interaction.hoveredNodeId) {
        const node = nodes.find(n => n.id === interaction.hoveredNodeId);
        if (node && node.type === GateType.INPUT_SWITCH) {
           const newNodes = nodes.map(n => 
             n.id === node.id ? { ...n, state: !n.state } : n
           );
           const res = propagateCircuit(newNodes, wires);
           setNodes(res.nodes);
           setWires(res.wires);
        }
      }
    }

    setInteraction(prev => ({
      ...prev,
      mode: prev.mode === InteractionMode.PLACING ? InteractionMode.PLACING : InteractionMode.IDLE,
      activeWireStart: null,
      dragStart: { x: 0, y: 0 }
    }));
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomIntensity = 0.1;
    const direction = e.deltaY > 0 ? -1 : 1;
    const newZoom = Math.min(Math.max(camera.zoom + (direction * zoomIntensity), 0.2), 3);
    setCamera(prev => ({ ...prev, zoom: newZoom }));
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      deleteSelected();
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const selectTool = (mode: InteractionMode, gateType?: GateType) => {
    setInteraction(prev => ({
      ...prev,
      mode: mode,
      placingType: gateType || null
    }));
    if (mode !== InteractionMode.IDLE) {
      setSelectedNodeIds([]);
      setSelectedWireIds([]);
    }
  };

  return (
    <div className="relative w-screen h-screen bg-[#1e1e1e] overflow-hidden">
      <Toolbar 
        onSelectTool={selectTool} 
        currentMode={interaction.mode} 
        selectedGateType={interaction.placingType}
        onSave={handleSaveProject}
        onLoad={handleLoadProject}
        onOpenKarnaugh={() => setIsKarnaughOpen(true)}
      />

      <div 
        ref={containerRef} 
        className="w-full h-full cursor-crosshair"
      >
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onContextMenu={handleContextMenu}
          onWheel={handleWheel}
          className="block"
        />
      </div>

      <KarnaughModal 
        isOpen={isKarnaughOpen}
        onClose={() => setIsKarnaughOpen(false)}
        onGenerate={handleKarnaughGenerate}
      />

      {contextMenu && (
        <ContextMenu 
          x={contextMenu.x} 
          y={contextMenu.y} 
          nodeType={nodes.find(n => n.id === contextMenu.nodeId)?.type}
          currentColor={nodes.find(n => n.id === contextMenu.nodeId)?.color}
          inputCount={nodes.find(n => n.id === contextMenu.nodeId)?.inputs.length}
          onColorChange={(color) => {
             setNodes(prev => prev.map(n => n.id === contextMenu.nodeId ? { ...n, color } : n));
          }}
          onInputCountChange={handleInputCountChange}
          onDelete={deleteSelected}
          onDuplicate={duplicateSelected}
          onClose={() => setContextMenu(null)}
        />
      )}

      <div className="absolute top-4 right-4 pointer-events-none text-zinc-500 text-xs font-mono">
        Nodes: {nodes.length} | Wires: {wires.length} | Zoom: {Math.round(camera.zoom * 100)}% | Selected: {selectedNodeIds.length + selectedWireIds.length}
      </div>
    </div>
  );
};

export default App;

import { CircuitNode, Wire, GateType } from '../types';
import { COMPONENT_CONFIGS, PIN_SPACING } from '../constants';

// --- Types ---
type Term = string; // e.g., "01-1" where - is don't care

// --- Quine-McCluskey Algorithm Helpers ---

const countOnes = (term: string) => term.split('').filter(c => c === '1').length;

const combineTerms = (t1: string, t2: string): string | null => {
  let diffIndex = -1;
  for (let i = 0; i < t1.length; i++) {
    if (t1[i] !== t2[i]) {
      if (diffIndex !== -1) return null; // More than 1 difference
      diffIndex = i;
    }
  }
  if (diffIndex === -1) return null; // Identical
  return t1.substring(0, diffIndex) + '-' + t1.substring(diffIndex + 1);
};

export const solveQuineMcCluskey = (numVars: number, minterms: number[]): string[] => {
  if (minterms.length === 0) return [];
  if (minterms.length === Math.pow(2, numVars)) return ['-'.repeat(numVars)]; // Always True

  // 1. Initialize groups
  let groups: Map<string, boolean> = new Map();
  minterms.forEach(m => {
    const bin = m.toString(2).padStart(numVars, '0');
    groups.set(bin, false);
  });

  let primeImplicants = new Set<string>();

  // 2. Iteratively combine
  let currentTerms = Array.from(groups.keys());

  while (currentTerms.length > 0) {
    const nextTerms = new Set<string>();
    const usedTerms = new Set<string>();

    // Compare every term with every other term
    for (let i = 0; i < currentTerms.length; i++) {
      for (let j = i + 1; j < currentTerms.length; j++) {
        const combined = combineTerms(currentTerms[i], currentTerms[j]);
        if (combined) {
          nextTerms.add(combined);
          usedTerms.add(currentTerms[i]);
          usedTerms.add(currentTerms[j]);
        }
      }
    }

    // Terms that couldn't be combined are Prime Implicants
    currentTerms.forEach(t => {
      if (!usedTerms.has(t)) {
        primeImplicants.add(t);
      }
    });

    if (nextTerms.size === 0) break;
    currentTerms = Array.from(nextTerms);
  }

  return Array.from(primeImplicants);
};

// --- Circuit Generator ---

const generateId = () => Math.random().toString(36).substr(2, 9);

export const generateCircuitFromTruthTable = (
  numVars: number, 
  truthTable: boolean[], // length 2^numVars
  startPos: { x: number, y: number }
): { nodes: CircuitNode[], wires: Wire[] } => {
  const nodes: CircuitNode[] = [];
  const wires: Wire[] = [];

  // 1. Get Simplified Terms
  const minterms = truthTable
    .map((val, idx) => val ? idx : -1)
    .filter(idx => idx !== -1);

  const simplifiedTerms = solveQuineMcCluskey(numVars, minterms);

  // Layout Constants
  const COL_Spacing = 150;
  const ROW_Spacing = 80;

  // 2. Create Input Switches (Column 0)
  const inputs: CircuitNode[] = [];
  const inputLabels = ['A', 'B', 'C', 'D'].slice(0, numVars);

  inputLabels.forEach((label, i) => {
    const node: CircuitNode = {
      id: generateId(),
      type: GateType.INPUT_SWITCH,
      position: { x: startPos.x, y: startPos.y + (i * ROW_Spacing) },
      width: 50,
      height: 50,
      inputs: [],
      state: false,
      label: label
    };
    inputs.push(node);
    nodes.push(node);
  });

  // 3. Create NOT Gates (Column 1) - Only if needed by terms
  const notGates: Map<number, CircuitNode> = new Map(); // inputIndex -> NotGate

  const needsNot = new Array(numVars).fill(false);
  simplifiedTerms.forEach(term => {
    for(let i=0; i<term.length; i++) {
      if (term[i] === '0') needsNot[i] = true;
    }
  });

  inputs.forEach((inputNode, i) => {
    if (needsNot[i]) {
      const notNode: CircuitNode = {
        id: generateId(),
        type: GateType.NOT,
        position: { x: startPos.x + COL_Spacing, y: inputNode.position.y + 10 },
        width: COMPONENT_CONFIGS[GateType.NOT].width,
        height: COMPONENT_CONFIGS[GateType.NOT].height,
        inputs: [false],
        state: false,
        label: 'NOT'
      };
      nodes.push(notNode);
      notGates.set(i, notNode);

      wires.push({
        id: generateId(),
        sourceNodeId: inputNode.id,
        sourcePinIndex: 0,
        targetNodeId: notNode.id,
        targetPinIndex: 0,
        state: false
      });
    }
  });

  // 4. Create AND Gates (Column 2) OR Prepare Direct Connections
  // We collect "Term Outputs" which are either an AND gate or a direct wire source
  interface TermOutput {
    sourceNodeId: string;
    sourcePinIndex: number;
    yPosition: number; // For layout of next stage
  }

  const termOutputs: TermOutput[] = [];
  const AND_COL_X = startPos.x + (COL_Spacing * 2);

  simplifiedTerms.forEach((term, idx) => {
    if (term === '-'.repeat(numVars) && simplifiedTerms.length > 1) return; 

    const connections: { nodeId: string, pinIndex: number, y: number }[] = [];

    for (let i = 0; i < term.length; i++) {
      const char = term[i];
      if (char === '1') {
        connections.push({ nodeId: inputs[i].id, pinIndex: 0, y: inputs[i].position.y });
      } else if (char === '0') {
        const notNode = notGates.get(i);
        if (notNode) connections.push({ nodeId: notNode.id, pinIndex: 0, y: notNode.position.y });
      }
    }

    if (connections.length === 0) {
       // Should effectively be VCC (Always True). 
    } else if (connections.length === 1) {
      // Direct connection, no AND gate needed
      termOutputs.push({
        sourceNodeId: connections[0].nodeId,
        sourcePinIndex: connections[0].pinIndex,
        yPosition: connections[0].y
      });
    } else {
      // Create AND Gate
      const inputCount = connections.length;
      const height = (inputCount + 1) * PIN_SPACING;

      // Calculate Average Y of inputs to center the gate
      const avgY = connections.reduce((sum, c) => sum + c.y, 0) / inputCount;

      // Ensure vertical separation from previous gates (simple stacking strategy fallback if overlap)
      let yPos = avgY - (height / 2);

      if (idx > 0) {
        const prevY = termOutputs[termOutputs.length - 1]?.yPosition || 0;
        if (yPos < prevY + 60) {
           yPos = prevY + 60;
        }
      }

      const andNode: CircuitNode = {
        id: generateId(),
        type: GateType.AND,
        position: { x: AND_COL_X, y: yPos },
        width: COMPONENT_CONFIGS[GateType.AND].width,
        height: height,
        inputs: new Array(inputCount).fill(false),
        state: false,
        label: 'AND'
      };

      nodes.push(andNode);

      connections.forEach((conn, pinIdx) => {
        wires.push({
          id: generateId(),
          sourceNodeId: conn.nodeId,
          sourcePinIndex: 0,
          targetNodeId: andNode.id,
          targetPinIndex: pinIdx,
          state: false
        });
      });

      termOutputs.push({
        sourceNodeId: andNode.id,
        sourcePinIndex: 0,
        yPosition: yPos + height / 2
      });
    }
  });

  // 5. Create OR Gate (Column 3)
  const OR_COL_X = AND_COL_X + COL_Spacing + 40;
  let finalOutputNodeId = '';
  let finalOutputPinIdx = 0;
  let lampY = startPos.y;

  if (termOutputs.length === 1) {
    // Direct connection to Lamp
    finalOutputNodeId = termOutputs[0].sourceNodeId;
    finalOutputPinIdx = termOutputs[0].sourcePinIndex;
    lampY = termOutputs[0].yPosition;
  } else if (termOutputs.length > 1) {
    // Create OR Gate
    const inputCount = termOutputs.length;
    const height = (inputCount + 1) * PIN_SPACING;
    const avgY = termOutputs.reduce((sum, t) => sum + t.yPosition, 0) / inputCount;

    const orNode: CircuitNode = {
      id: generateId(),
      type: GateType.OR,
      position: { x: OR_COL_X, y: avgY - (height/2) },
      width: COMPONENT_CONFIGS[GateType.OR].width,
      height: height,
      inputs: new Array(inputCount).fill(false),
      state: false,
      label: 'OR'
    };
    nodes.push(orNode);
    finalOutputNodeId = orNode.id;
    finalOutputPinIdx = 0;
    lampY = avgY;

    termOutputs.forEach((term, i) => {
      wires.push({
        id: generateId(),
        sourceNodeId: term.sourceNodeId,
        sourcePinIndex: term.sourcePinIndex,
        targetNodeId: orNode.id,
        targetPinIndex: i,
        state: false
      });
    });
  }

  // 6. Create Output Lamp
  const lampNode: CircuitNode = {
    id: generateId(),
    type: GateType.OUTPUT_LAMP,
    position: { x: OR_COL_X + 100, y: lampY - 25 }, // Center lamp on signal line
    width: 50,
    height: 50,
    inputs: [false],
    state: false,
    label: 'Q'
  };
  nodes.push(lampNode);

  if (finalOutputNodeId) {
    wires.push({
      id: generateId(),
      sourceNodeId: finalOutputNodeId,
      sourcePinIndex: finalOutputPinIdx,
      targetNodeId: lampNode.id,
      targetPinIndex: 0,
      state: false
    });
  }

  return { nodes, wires };
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  CircuitNode, 
  Wire, 
  Camera, 
  InteractionMode, 
  InteractionState, 
  GateType,
  Position,
  ProjectData
} from './types';
import { COMPONENT_CONFIGS, COLORS, PIN_SPACING } from './constants';
import { renderCircuit, screenToWorld, worldToScreen, checkWireHit } from './services/renderer';
import { propagateCircuit } from './services/circuitEngine';
import { generateCircuitFromTruthTable } from './services/quineMcCluskey';
import Toolbar from './components/Toolbar';
import { ContextMenu } from './components/ContextMenu';
import { KarnaughModal } from './components/KarnaughModal';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // State
  const [nodes, setNodes] = useState<CircuitNode[]>([]);
  const [wires, setWires] = useState<Wire[]>([]);
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, zoom: 1 });
  const [selectedNodeIds, setSelectedNodeIds] = useState<string[]>([]);
  const [selectedWireIds, setSelectedWireIds] = useState<string[]>([]);
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; nodeId: string } | null>(null);
  const [isKarnaughOpen, setIsKarnaughOpen] = useState(false);

  // Interaction State
  const [interaction, setInteraction] = useState<InteractionState>({
    mode: InteractionMode.IDLE,
    hoveredNodeId: null,
    hoveredWireId: null,
    hoveredPin: null,
    dragStart: { x: 0, y: 0 },
    dragOffset: { x: 0, y: 0 },
    activeWireStart: null,
    placingType: null,
  });

  // Refs
  const nodesRef = useRef(nodes);
  const wiresRef = useRef(wires);
  const interactionRef = useRef(interaction);
  const cameraRef = useRef(camera);
  const mousePosRef = useRef<Position>({ x: 0, y: 0 });
  const selectedNodeIdsRef = useRef(selectedNodeIds);
  const selectedWireIdsRef = useRef(selectedWireIds);

  // Store initial positions of selected nodes when dragging starts
  const initialNodePositionsRef = useRef<Map<string, Position>>(new Map());

  // Sync refs
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { wiresRef.current = wires; }, [wires]);
  useEffect(() => { interactionRef.current = interaction; }, [interaction]);
  useEffect(() => { cameraRef.current = camera; }, [camera]);
  useEffect(() => { selectedNodeIdsRef.current = selectedNodeIds; }, [selectedNodeIds]);
  useEffect(() => { selectedWireIdsRef.current = selectedWireIds; }, [selectedWireIds]);

  // Main Logic Loop (Clock & Propagation)
  useEffect(() => {
    const interval = setInterval(() => {
      let needsUpdate = false;
      const currentNodes = [...nodesRef.current];

      // Handle Clock Components
      currentNodes.forEach(node => {
        if (node.type === GateType.CLOCK) {
          node.state = !node.state;
          needsUpdate = true;
        }
      });

      if (needsUpdate) {
        const result = propagateCircuit(currentNodes, wiresRef.current);
        setNodes(result.nodes);
        setWires(result.wires);
      }
    }, 500); // 500ms Clock tick

    return () => clearInterval(interval);
  }, []);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;

    const render = () => {
      // Handle resize
      if (containerRef.current) {
        canvas.width = containerRef.current.clientWidth;
        canvas.height = containerRef.current.clientHeight;
      }

      const currentInteraction = interactionRef.current;

      renderCircuit(
        canvas, 
        ctx, 
        nodesRef.current, 
        wiresRef.current, 
        cameraRef.current, 
        currentInteraction,
        selectedNodeIdsRef.current,
        selectedWireIdsRef.current,
        mousePosRef.current
      );

      // Draw active wire line if dragging
      if (currentInteraction.mode === InteractionMode.WIRING && currentInteraction.activeWireStart) {
        const { nodeId } = currentInteraction.activeWireStart;
        const node = nodesRef.current.find(n => n.id === nodeId);
        if (node) {
          const startX = node.position.x + node.width;
          const startY = node.position.y + node.height / 2;
          const s = worldToScreen(startX, startY, cameraRef.current);

          ctx.beginPath();
          ctx.moveTo(s.x, s.y);
          ctx.lineTo(mousePosRef.current.x, mousePosRef.current.y);
          ctx.strokeStyle = COLORS.wireActive;
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 5]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, []);

  // --- Actions ---
  const deleteSelected = () => {
    // Collect ids
    const nodeIdsToDelete = new Set(selectedNodeIdsRef.current);
    const wireIdsToDelete = new Set(selectedWireIdsRef.current);

    // Add context menu target if applicable
    if (contextMenu?.nodeId && !nodeIdsToDelete.has(contextMenu.nodeId)) {
        nodeIdsToDelete.add(contextMenu.nodeId);
    }

    if (nodeIdsToDelete.size === 0 && wireIdsToDelete.size === 0) return;

    // Filter nodes
    setNodes(prev => prev.filter(n => !nodeIdsToDelete.has(n.id)));

    // Filter wires (remove if explicitly selected OR if attached to a deleted node)
    setWires(prev => prev.filter(w => 
      !wireIdsToDelete.has(w.id) && 
      !nodeIdsToDelete.has(w.sourceNodeId) && 
      !nodeIdsToDelete.has(w.targetNodeId)
    ));

    setSelectedNodeIds([]);
    setSelectedWireIds([]);
    setContextMenu(null);
  };

  const duplicateSelected = () => {
    // If context menu was triggered on an unselected node, duplicate just that.
    // Otherwise duplicate the selection.
    let idsToDuplicate = selectedNodeIds;
    if (contextMenu?.nodeId && !idsToDuplicate.includes(contextMenu.nodeId)) {
      idsToDuplicate = [contextMenu.nodeId];
    }

    if (idsToDuplicate.length === 0) return;

    const newNodes: CircuitNode[] = [];
    const idMap = new Map<string, string>(); // oldId -> newId

    // 1. Clone Nodes
    idsToDuplicate.forEach(id => {
      const original = nodes.find(n => n.id === id);
      if (original) {
        const newId = generateId();
        idMap.set(id, newId);
        newNodes.push({
          ...original,
          id: newId,
          position: { x: original.position.x + 20, y: original.position.y + 20 },
          inputs: [...original.inputs], // Copy state
          state: original.state,
          color: original.color
        });
      }
    });

    // 2. Clone internal wires (wires connecting two duplicated nodes)
    const newWires: Wire[] = [];
    wires.forEach(w => {
      if (idMap.has(w.sourceNodeId) && idMap.has(w.targetNodeId)) {
        newWires.push({
          ...w,
          id: generateId(),
          sourceNodeId: idMap.get(w.sourceNodeId)!,
          targetNodeId: idMap.get(w.targetNodeId)!
        });
      }
    });

    setNodes(prev => [...prev, ...newNodes]);
    setWires(prev => [...prev, ...newWires]);

    // Select the new copies
    setSelectedNodeIds(newNodes.map(n => n.id));
    setSelectedWireIds([]); // Do not auto-select duplicated wires for now
    setContextMenu(null);
  };

  const handleInputCountChange = (delta: number) => {
    if (!contextMenu?.nodeId) return;

    const nodeId = contextMenu.nodeId;

    setNodes(prevNodes => prevNodes.map(node => {
      if (node.id !== nodeId) return node;

      const currentCount = node.inputs.length;
      const newCount = Math.min(32, Math.max(2, currentCount + delta)); // Increased limit to 32

      if (newCount === currentCount) return node;

      let newInputs = [...node.inputs];

      if (newCount > currentCount) {
        // Add inputs (default false)
        for(let i = 0; i < (newCount - currentCount); i++) {
            newInputs.push(false);
        }
      } else {
        // Remove inputs from end
        newInputs = newInputs.slice(0, newCount);

        // Remove wires connected to deleted pins
        setWires(prevWires => prevWires.filter(w => 
           !(w.targetNodeId === nodeId && w.targetPinIndex >= newCount)
        ));
      }

      // Calculate new height based on pin count + 1 gap for top/bottom margin
      // 2 inputs = 3 spaces * 20px = 60px (Standard)
      // 8 inputs = 9 spaces * 20px = 180px
      const newHeight = (newCount + 1) * PIN_SPACING;

      return {
        ...node,
        inputs: newInputs,
        height: newHeight
      };
    }));
  };

  // --- Save / Load ---

  const handleSaveProject = () => {
    const projectData: ProjectData = {
      version: '1.0.0',
      nodes: nodes,
      wires: wires,
      camera: camera
    };

    const blob = new Blob([JSON.stringify(projectData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `circuit-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleLoadProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const projectData = JSON.parse(content) as ProjectData;

        // Basic validation
        if (Array.isArray(projectData.nodes) && Array.isArray(projectData.wires)) {
          setNodes(projectData.nodes);
          setWires(projectData.wires);
          if (projectData.camera) {
            setCamera(projectData.camera);
          }
          // Reset selection
          setSelectedNodeIds([]);
          setSelectedWireIds([]);
        } else {
          alert("Invalid project file format.");
        }
      } catch (err) {
        console.error("Failed to parse project file", err);
        alert("Failed to load project file.");
      }
    };
    reader.readAsText(file);
  };

  // --- Karnaugh Generator ---

  const handleKarnaughGenerate = (numVars: number, truthTable: boolean[]) => {
    // Determine spawn position (center of current view)
    const centerWorld = screenToWorld(
        (containerRef.current?.clientWidth || 800) / 2,
        (containerRef.current?.clientHeight || 600) / 2,
        camera
    );
    // Shift slightly left so the circuit centers better
    centerWorld.x -= 300; 
    centerWorld.y -= 200;

    const { nodes: newNodes, wires: newWires } = generateCircuitFromTruthTable(
        numVars, 
        truthTable, 
        centerWorld
    );

    // Merge into existing circuit
    setNodes(prev => [...prev, ...newNodes]);
    setWires(prev => [...prev, ...newWires]);
    setIsKarnaughOpen(false);
  };


  // --- Interaction Handlers ---

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();

    let targetNodeId = interaction.hoveredNodeId;

    if (targetNodeId) {
      if (!selectedNodeIds.includes(targetNodeId)) {
        setSelectedNodeIds([targetNodeId]);
        setSelectedWireIds([]);
      }
      setContextMenu({
        x: e.clientX,
        y: e.clientY,
        nodeId: targetNodeId
      });
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (contextMenu) setContextMenu(null);

    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const worldPos = screenToWorld(x, y, camera);

    // Right click handled by ContextMenu or Pan
    if (e.button === 2) {
      if (!interaction.hoveredNodeId) {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.PANNING,
          dragStart: { x, y }
        }));
      }
      return;
    }

    // Placing Mode
    if (interaction.mode === InteractionMode.PLACING && interaction.placingType) {
      const config = COMPONENT_CONFIGS[interaction.placingType];
      const newNode: CircuitNode = {
        id: generateId(),
        type: interaction.placingType,
        position: { x: worldPos.x - config.width/2, y: worldPos.y - config.height/2 },
        width: config.width,
        height: config.height,
        inputs: new Array(config.inputCount).fill(false),
        state: false,
        label: config.label
      };

      setNodes(prev => [...prev, newNode]);
      setSelectedNodeIds([newNode.id]);
      setSelectedWireIds([]);
      return;
    }

    // Wiring Mode
    if (interaction.hoveredPin) {
      if (interaction.hoveredPin.type === 'output') {
        setInteraction(prev => ({
          ...prev,
          mode: InteractionMode.WIRING,
          activeWireStart: { nodeId: prev.hoveredPin!.nodeId, pinIndex: prev.hoveredPin!.index }
        }));
        setSelectedNodeIds([]); 
        setSelectedWireIds([]);
      }
      return;
    }

    // Node Interaction (Selection / Dragging)
    if (interaction.hoveredNodeId) {
      const nodeId = interaction.hoveredNodeId;
      const isSelected = selectedNodeIds.includes(nodeId);
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;

      let newSelection = [...selectedNodeIds];

      if (isMultiSelectKey) {
        if (isSelected) {
          newSelection = newSelection.filter(id => id !== nodeId);
        } else {
          newSelection.push(nodeId);
        }
      } else {
        if (!isSelected) {
          newSelection = [nodeId];
          setSelectedWireIds([]); // Clear wires if selecting a node without Shift
        }
      }

      setSelectedNodeIds(newSelection);

      // Prepare for Dragging
      const initialPosMap = new Map<string, Position>();
      nodes.forEach(n => {
        if (newSelection.includes(n.id)) {
          initialPosMap.set(n.id, { ...n.position });
        }
      });
      initialNodePositionsRef.current = initialPosMap;

      setInteraction(prev => ({
        ...prev,
        mode: InteractionMode.DRAGGING_NODE,
        dragStart: { x, y }
      }));
      return;
    }

    // Wire Selection Check (if no node or pin is hovered)
    // Check if we hit a wire using the logic in renderer
    const hitWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
    if (hitWireId) {
      const isMultiSelectKey = e.shiftKey || e.ctrlKey || e.metaKey;
      let newWireSelection = [...selectedWireIds];

      if (isMultiSelectKey) {
        if (newWireSelection.includes(hitWireId)) {
          newWireSelection = newWireSelection.filter(id => id !== hitWireId);
        } else {
          newWireSelection.push(hitWireId);
        }
      } else {
        newWireSelection = [hitWireId];
        setSelectedNodeIds([]); // Clear nodes if selecting wire without Shift
      }

      setSelectedWireIds(newWireSelection);
      return;
    }

    // Empty Space -> Selection Box
    if (!e.shiftKey && !e.ctrlKey) {
        setSelectedNodeIds([]);
        setSelectedWireIds([]);
    }
    setInteraction(prev => ({
      ...prev,
      mode: InteractionMode.SELECTING,
      dragStart: { x, y }
    }));
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    // Panning
    if (interaction.mode === InteractionMode.PANNING) {
      const dx = x - interaction.dragStart.x;
      const dy = y - interaction.dragStart.y;
      setCamera(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
      setInteraction(prev => ({ ...prev, dragStart: { x, y } }));
      return;
    }

    // Dragging Nodes
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dx = (x - interaction.dragStart.x) / camera.zoom;
      const dy = (y - interaction.dragStart.y) / camera.zoom;

      setNodes(prev => prev.map(n => {
        if (initialNodePositionsRef.current.has(n.id)) {
            const initial = initialNodePositionsRef.current.get(n.id)!;
            return {
                ...n,
                position: { x: initial.x + dx, y: initial.y + dy }
            };
        }
        return n;
      }));
      return;
    }

    // Selection Box
    if (interaction.mode === InteractionMode.SELECTING) {
      const startWorld = screenToWorld(interaction.dragStart.x, interaction.dragStart.y, camera);
      const currentWorld = screenToWorld(x, y, camera);

      const minX = Math.min(startWorld.x, currentWorld.x);
      const maxX = Math.max(startWorld.x, currentWorld.x);
      const minY = Math.min(startWorld.y, currentWorld.y);
      const maxY = Math.max(startWorld.y, currentWorld.y);

      const enclosedIds = nodes
        .filter(n => 
          n.position.x >= minX && (n.position.x + n.width) <= maxX &&
          n.position.y >= minY && (n.position.y + n.height) <= maxY
        )
        .map(n => n.id);

      setSelectedNodeIds(enclosedIds);
      // Optional: Select enclosed wires too? For now, stick to nodes.
      return;
    }

    // Hover Detection
    if ([InteractionMode.IDLE, InteractionMode.WIRING, InteractionMode.PLACING].includes(interaction.mode)) {
      const worldPos = screenToWorld(x, y, camera);
      let foundNodeId: string | null = null;
      let foundPin: InteractionState['hoveredPin'] = null;

      // Check Nodes & Pins
      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];
        const config = COMPONENT_CONFIGS[node.type];

        // Pins - Dynamic Check
        const inputCount = node.inputs.length;
        const pinSpacingIn = node.height / (inputCount + 1);
        for (let p = 0; p < inputCount; p++) {
          const px = node.position.x;
          const py = node.position.y + (pinSpacingIn * (p + 1));
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'input', index: p };
            break;
          }
        }
        if (foundPin) break;

        if (config.outputCount > 0) {
          const px = node.position.x + node.width;
          const py = node.position.y + node.height / 2;
          if (Math.hypot(worldPos.x - px, worldPos.y - py) < 10) {
            foundPin = { nodeId: node.id, type: 'output', index: 0 };
            break;
          }
        }
        if (foundPin) break;

        // Body
        if (worldPos.x >= node.position.x && worldPos.x <= node.position.x + node.width &&
            worldPos.y >= node.position.y && worldPos.y <= node.position.y + node.height) {
          foundNodeId = node.id;
          break;
        }
      }

      // Check Wires (Only if no node/pin hovered to avoid noise)
      let foundWireId: string | null = null;
      if (!foundNodeId && !foundPin) {
        foundWireId = checkWireHit(worldPos.x, worldPos.y, wires, nodes);
      }

      setInteraction(prev => ({
        ...prev,
        hoveredNodeId: foundNodeId,
        hoveredPin: foundPin,
        hoveredWireId: foundWireId
      }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    // Complete Wiring
    if (interaction.mode === InteractionMode.WIRING && interaction.hoveredPin && interaction.activeWireStart) {
      if (interaction.hoveredPin.type === 'input') {
        const newWire: Wire = {
          id: generateId(),
          sourceNodeId: interaction.activeWireStart.nodeId,
          sourcePinIndex: interaction.activeWireStart.pinIndex,
          targetNodeId: interaction.hoveredPin.nodeId,
          targetPinIndex: interaction.hoveredPin.index,
          state: false
        };

        const exists = wires.some(w => 
          w.targetNodeId === newWire.targetNodeId && w.targetPinIndex === newWire.targetPinIndex
        );

        if (!exists) {
          const newWires = [...wires, newWire];
          const res = propagateCircuit(nodes, newWires);
          setNodes(res.nodes);
          setWires(res.wires);
        }
      }
    }

    // Toggle Switch click handling
    if (interaction.mode === InteractionMode.DRAGGING_NODE) {
      const dist = Math.hypot(e.clientX - interaction.dragStart.x, e.clientY - interaction.dragStart.y);
      if (dist < 3 && interaction.hoveredNodeId) {
        const node = nodes.find(n => n.id === interaction.hoveredNodeId);
        if (node && node.type === GateType.INPUT_SWITCH) {
           const newNodes = nodes.map(n => 
             n.id === node.id ? { ...n, state: !n.state } : n
           );
           const res = propagateCircuit(newNodes, wires);
           setNodes(res.nodes);
           setWires(res.wires);
        }
      }
    }

    setInteraction(prev => ({
      ...prev,
      mode: prev.mode === InteractionMode.PLACING ? InteractionMode.PLACING : InteractionMode.IDLE,
      activeWireStart: null,
      dragStart: { x: 0, y: 0 }
    }));
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomIntensity = 0.1;
    const direction = e.deltaY > 0 ? -1 : 1;
    const newZoom = Math.min(Math.max(camera.zoom + (direction * zoomIntensity), 0.2), 3);
    setCamera(prev => ({ ...prev, zoom: newZoom }));
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      deleteSelected();
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const selectTool = (mode: InteractionMode, gateType?: GateType) => {
    setInteraction(prev => ({
      ...prev,
      mode: mode,
      placingType: gateType || null
    }));
    if (mode !== InteractionMode.IDLE) {
      setSelectedNodeIds([]);
      setSelectedWireIds([]);
    }
  };

  return (
    <div className="relative w-screen h-screen bg-[#1e1e1e] overflow-hidden">
      <Toolbar 
        onSelectTool={selectTool} 
        currentMode={interaction.mode} 
        selectedGateType={interaction.placingType}
        onSave={handleSaveProject}
        onLoad={handleLoadProject}
        onOpenKarnaugh={() => setIsKarnaughOpen(true)}
      />

      <div 
        ref={containerRef} 
        className="w-full h-full cursor-crosshair"
      >
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onContextMenu={handleContextMenu}
          onWheel={handleWheel}
          className="block"
        />
      </div>

      <KarnaughModal 
        isOpen={isKarnaughOpen}
        onClose={() => setIsKarnaughOpen(false)}
        onGenerate={handleKarnaughGenerate}
      />

      {contextMenu && (
        <ContextMenu 
          x={contextMenu.x} 
          y={contextMenu.y} 
          nodeType={nodes.find(n => n.id === contextMenu.nodeId)?.type}
          currentColor={nodes.find(n => n.id === contextMenu.nodeId)?.color}
          inputCount={nodes.find(n => n.id === contextMenu.nodeId)?.inputs.length}
          onColorChange={(color) => {
             setNodes(prev => prev.map(n => n.id === contextMenu.nodeId ? { ...n, color } : n));
          }}
          onInputCountChange={handleInputCountChange}
          onDelete={deleteSelected}
          onDuplicate={duplicateSelected}
          onClose={() => setContextMenu(null)}
        />
      )}

      <div className="absolute top-4 right-4 pointer-events-none text-zinc-500 text-xs font-mono">
        Nodes: {nodes.length} | Wires: {wires.length} | Zoom: {Math.round(camera.zoom * 100)}% | Selected: {selectedNodeIds.length + selectedWireIds.length}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { Copy, Trash2, Minus, Plus } from 'lucide-react';
import { GateType } from '../types';
import { LED_COLORS } from '../constants';

interface ContextMenuProps {
  x: number;
  y: number;
  nodeType?: GateType;
  currentColor?: string;
  inputCount?: number;
  onColorChange?: (color: string) => void;
  onInputCountChange?: (delta: number) => void;
  onDuplicate: () => void;
  onDelete: () => void;
  onClose: () => void;
}

export const ContextMenu: React.FC<ContextMenuProps> = ({ 
  x, 
  y, 
  nodeType, 
  currentColor, 
  inputCount,
  onColorChange, 
  onInputCountChange,
  onDuplicate, 
  onDelete, 
  onClose 
}) => {
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onClose();
      }
    };
    // Use mousedown to detect outside clicks earlier than click
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  // Determine if this node type supports variable inputs
  const supportsVariableInputs = nodeType && [
    GateType.AND, 
    GateType.OR, 
    GateType.NAND, 
    GateType.NOR, 
    GateType.XOR
  ].includes(nodeType);

  return (
    <div 
      ref={menuRef}
      className="fixed bg-zinc-800 border border-zinc-700 rounded-lg shadow-xl z-50 py-1 min-w-[160px] flex flex-col"
      style={{ top: y, left: x }}
    >
      {/* LED Color Selector */}
      {nodeType === GateType.OUTPUT_LAMP && onColorChange && (
        <div className="px-4 py-2 border-b border-zinc-700">
           <div className="text-[10px] text-zinc-500 mb-2 uppercase font-semibold">LED Color</div>
           <div className="flex gap-2">
             {Object.entries(LED_COLORS).map(([name, color]) => (
               <button
                 key={name}
                 onClick={(e) => { e.stopPropagation(); onColorChange(color); }}
                 className={`w-4 h-4 rounded-full border border-zinc-600 transition-transform hover:scale-110 cursor-pointer ${currentColor === color ? 'ring-1 ring-white' : ''}`}
                 style={{ backgroundColor: color, boxShadow: `0 0 5px ${color}40` }}
                 title={name}
               />
             ))}
           </div>
        </div>
      )}

      {/* Input Count Selector */}
      {supportsVariableInputs && onInputCountChange && inputCount !== undefined && (
        <div className="px-4 py-2 border-b border-zinc-700">
          <div className="text-[10px] text-zinc-500 mb-2 uppercase font-semibold">Inputs: {inputCount}</div>
          <div className="flex items-center justify-between bg-zinc-700 rounded p-1">
            <button
              onClick={(e) => { e.stopPropagation(); onInputCountChange(-1); }}
              disabled={inputCount <= 2}
              className={`p-1 rounded hover:bg-zinc-600 text-zinc-200 transition-colors ${inputCount <= 2 ? 'opacity-30 cursor-not-allowed' : ''}`}
            >
              <Minus size={14} />
            </button>
            <span className="text-xs font-mono text-white">{inputCount}</span>
            <button
              onClick={(e) => { e.stopPropagation(); onInputCountChange(1); }}
              disabled={inputCount >= 32}
              className={`p-1 rounded hover:bg-zinc-600 text-zinc-200 transition-colors ${inputCount >= 32 ? 'opacity-30 cursor-not-allowed' : ''}`}
            >
              <Plus size={14} />
            </button>
          </div>
        </div>
      )}

      <button 
        onClick={(e) => { e.stopPropagation(); onDuplicate(); }}
        className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-zinc-700 hover:text-white flex items-center gap-2 transition-colors cursor-pointer"
      >
        <Copy size={14} />
        Duplicate
      </button>
      <button 
        onClick={(e) => { e.stopPropagation(); onDelete(); }}
        className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-zinc-700 hover:text-red-300 flex items-center gap-2 transition-colors cursor-pointer"
      >
        <Trash2 size={14} />
        Delete
      </button>
    </div>
  );
};

import { CircuitNode, Wire, GateType } from '../types';
import { COMPONENT_CONFIGS, PIN_SPACING } from '../constants';

// --- Types ---
type Term = string; // e.g., "01-1" where - is don't care

// --- Quine-McCluskey Algorithm Helpers ---

const countOnes = (term: string) => term.split('').filter(c => c === '1').length;

const combineTerms = (t1: string, t2: string): string | null => {
  let diffIndex = -1;
  for (let i = 0; i < t1.length; i++) {
    if (t1[i] !== t2[i]) {
      if (diffIndex !== -1) return null; // More than 1 difference
      diffIndex = i;
    }
  }
  if (diffIndex === -1) return null; // Identical
  return t1.substring(0, diffIndex) + '-' + t1.substring(diffIndex + 1);
};

export const solveQuineMcCluskey = (numVars: number, minterms: number[]): string[] => {
  if (minterms.length === 0) return [];
  if (minterms.length === Math.pow(2, numVars)) return ['-'.repeat(numVars)]; // Always True

  // 1. Initialize groups
  let groups: Map<string, boolean> = new Map();
  minterms.forEach(m => {
    const bin = m.toString(2).padStart(numVars, '0');
    groups.set(bin, false);
  });

  let primeImplicants = new Set<string>();

  // 2. Iteratively combine
  let currentTerms = Array.from(groups.keys());

  while (currentTerms.length > 0) {
    const nextTerms = new Set<string>();
    const usedTerms = new Set<string>();

    // Compare every term with every other term
    for (let i = 0; i < currentTerms.length; i++) {
      for (let j = i + 1; j < currentTerms.length; j++) {
        const combined = combineTerms(currentTerms[i], currentTerms[j]);
        if (combined) {
          nextTerms.add(combined);
          usedTerms.add(currentTerms[i]);
          usedTerms.add(currentTerms[j]);
        }
      }
    }

    // Terms that couldn't be combined are Prime Implicants
    currentTerms.forEach(t => {
      if (!usedTerms.has(t)) {
        primeImplicants.add(t);
      }
    });

    if (nextTerms.size === 0) break;
    currentTerms = Array.from(nextTerms);
  }

  return Array.from(primeImplicants);
};

// --- Circuit Generator ---

const generateId = () => Math.random().toString(36).substr(2, 9);

export const generateCircuitFromTruthTable = (
  numVars: number, 
  truthTable: boolean[], // length 2^numVars
  startPos: { x: number, y: number }
): { nodes: CircuitNode[], wires: Wire[] } => {
  const nodes: CircuitNode[] = [];
  const wires: Wire[] = [];

  // 1. Get Simplified Terms
  const minterms = truthTable
    .map((val, idx) => val ? idx : -1)
    .filter(idx => idx !== -1);

  const simplifiedTerms = solveQuineMcCluskey(numVars, minterms);

  // Layout Constants
  const COL_Spacing = 150;
  const ROW_Spacing = 80;

  // 2. Create Input Switches (Column 0)
  const inputs: CircuitNode[] = [];
  const inputLabels = ['A', 'B', 'C', 'D'].slice(0, numVars);

  inputLabels.forEach((label, i) => {
    const node: CircuitNode = {
      id: generateId(),
      type: GateType.INPUT_SWITCH,
      position: { x: startPos.x, y: startPos.y + (i * ROW_Spacing) },
      width: 50,
      height: 50,
      inputs: [],
      state: false,
      label: label
    };
    inputs.push(node);
    nodes.push(node);
  });

  // 3. Create NOT Gates (Column 1) - Only if needed by terms
  const notGates: Map<number, CircuitNode> = new Map(); // inputIndex -> NotGate

  const needsNot = new Array(numVars).fill(false);
  simplifiedTerms.forEach(term => {
    for(let i=0; i<term.length; i++) {
      if (term[i] === '0') needsNot[i] = true;
    }
  });

  inputs.forEach((inputNode, i) => {
    if (needsNot[i]) {
      const notNode: CircuitNode = {
        id: generateId(),
        type: GateType.NOT,
        position: { x: startPos.x + COL_Spacing, y: inputNode.position.y + 10 },
        width: COMPONENT_CONFIGS[GateType.NOT].width,
        height: COMPONENT_CONFIGS[GateType.NOT].height,
        inputs: [false],
        state: false,
        label: 'NOT'
      };
      nodes.push(notNode);
      notGates.set(i, notNode);

      wires.push({
        id: generateId(),
        sourceNodeId: inputNode.id,
        sourcePinIndex: 0,
        targetNodeId: notNode.id,
        targetPinIndex: 0,
        state: false
      });
    }
  });

  // 4. Create AND Gates (Column 2) OR Prepare Direct Connections
  // We collect "Term Outputs" which are either an AND gate or a direct wire source
  interface TermOutput {
    sourceNodeId: string;
    sourcePinIndex: number;
    yPosition: number; // For layout of next stage
  }

  const termOutputs: TermOutput[] = [];
  const AND_COL_X = startPos.x + (COL_Spacing * 2);

  simplifiedTerms.forEach((term, idx) => {
    if (term === '-'.repeat(numVars) && simplifiedTerms.length > 1) return; 

    const connections: { nodeId: string, pinIndex: number, y: number }[] = [];

    for (let i = 0; i < term.length; i++) {
      const char = term[i];
      if (char === '1') {
        connections.push({ nodeId: inputs[i].id, pinIndex: 0, y: inputs[i].position.y });
      } else if (char === '0') {
        const notNode = notGates.get(i);
        if (notNode) connections.push({ nodeId: notNode.id, pinIndex: 0, y: notNode.position.y });
      }
    }

    if (connections.length === 0) {
       // Should effectively be VCC (Always True). 
    } else if (connections.length === 1) {
      // Direct connection, no AND gate needed
      termOutputs.push({
        sourceNodeId: connections[0].nodeId,
        sourcePinIndex: connections[0].pinIndex,
        yPosition: connections[0].y
      });
    } else {
      // Create AND Gate
      const inputCount = connections.length;
      const height = (inputCount + 1) * PIN_SPACING;

      // Calculate Average Y of inputs to center the gate
      const avgY = connections.reduce((sum, c) => sum + c.y, 0) / inputCount;

      // Ensure vertical separation from previous gates (simple stacking strategy fallback if overlap)
      let yPos = avgY - (height / 2);

      if (idx > 0) {
        const prevY = termOutputs[termOutputs.length - 1]?.yPosition || 0;
        if (yPos < prevY + 60) {
           yPos = prevY + 60;
        }
      }

      const andNode: CircuitNode = {
        id: generateId(),
        type: GateType.AND,
        position: { x: AND_COL_X, y: yPos },
        width: COMPONENT_CONFIGS[GateType.AND].width,
        height: height,
        inputs: new Array(inputCount).fill(false),
        state: false,
        label: 'AND'
      };

      nodes.push(andNode);

      connections.forEach((conn, pinIdx) => {
        wires.push({
          id: generateId(),
          sourceNodeId: conn.nodeId,
          sourcePinIndex: 0,
          targetNodeId: andNode.id,
          targetPinIndex: pinIdx,
          state: false
        });
      });

      termOutputs.push({
        sourceNodeId: andNode.id,
        sourcePinIndex: 0,
        yPosition: yPos + height / 2
      });
    }
  });

  // 5. Create OR Gate (Column 3)
  const OR_COL_X = AND_COL_X + COL_Spacing + 40;
  let finalOutputNodeId = '';
  let finalOutputPinIdx = 0;
  let lampY = startPos.y;

  if (termOutputs.length === 1) {
    // Direct connection to Lamp
    finalOutputNodeId = termOutputs[0].sourceNodeId;
    finalOutputPinIdx = termOutputs[0].sourcePinIndex;
    lampY = termOutputs[0].yPosition;
  } else if (termOutputs.length > 1) {
    // Create OR Gate
    const inputCount = termOutputs.length;
    const height = (inputCount + 1) * PIN_SPACING;
    const avgY = termOutputs.reduce((sum, t) => sum + t.yPosition, 0) / inputCount;

    const orNode: CircuitNode = {
      id: generateId(),
      type: GateType.OR,
      position: { x: OR_COL_X, y: avgY - (height/2) },
      width: COMPONENT_CONFIGS[GateType.OR].width,
      height: height,
      inputs: new Array(inputCount).fill(false),
      state: false,
      label: 'OR'
    };
    nodes.push(orNode);
    finalOutputNodeId = orNode.id;
    finalOutputPinIdx = 0;
    lampY = avgY;

    termOutputs.forEach((term, i) => {
      wires.push({
        id: generateId(),
        sourceNodeId: term.sourceNodeId,
        sourcePinIndex: term.sourcePinIndex,
        targetNodeId: orNode.id,
        targetPinIndex: i,
        state: false
      });
    });
  }

  // 6. Create Output Lamp
  const lampNode: CircuitNode = {
    id: generateId(),
    type: GateType.OUTPUT_LAMP,
    position: { x: OR_COL_X + 100, y: lampY - 25 }, // Center lamp on signal line
    width: 50,
    height: 50,
    inputs: [false],
    state: false,
    label: 'Q'
  };
  nodes.push(lampNode);

  if (finalOutputNodeId) {
    wires.push({
      id: generateId(),
      sourceNodeId: finalOutputNodeId,
      sourcePinIndex: finalOutputPinIdx,
      targetNodeId: lampNode.id,
      targetPinIndex: 0,
      state: false
    });
  }

  return { nodes, wires };
};

import { CircuitNode, Wire, GateType } from '../types';
import { COMPONENT_CONFIGS, PIN_SPACING } from '../constants';

// --- Types ---
export type Term = string; // e.g., "01-1" where - is don't care

// --- Quine-McCluskey Algorithm Helpers ---

const combineTerms = (t1: string, t2: string): string | null => {
  let diffIndex = -1;
  for (let i = 0; i < t1.length; i++) {
    if (t1[i] !== t2[i]) {
      if (diffIndex !== -1) return null; // More than 1 difference
      diffIndex = i;
    }
  }
  if (diffIndex === -1) return null; // Identical
  return t1.substring(0, diffIndex) + '-' + t1.substring(diffIndex + 1);
};

export const solveQuineMcCluskey = (numVars: number, minterms: number[]): string[] => {
  if (minterms.length === 0) return [];
  if (minterms.length === Math.pow(2, numVars)) return ['-'.repeat(numVars)]; // Always True

  // 1. Initialize groups
  let groups: Map<string, boolean> = new Map();
  minterms.forEach(m => {
    const bin = m.toString(2).padStart(numVars, '0');
    groups.set(bin, false);
  });

  let primeImplicants = new Set<string>();

  // 2. Iteratively combine
  let currentTerms = Array.from(groups.keys());

  while (currentTerms.length > 0) {
    const nextTerms = new Set<string>();
    const usedTerms = new Set<string>();

    // Compare every term with every other term
    for (let i = 0; i < currentTerms.length; i++) {
      for (let j = i + 1; j < currentTerms.length; j++) {
        const combined = combineTerms(currentTerms[i], currentTerms[j]);
        if (combined) {
          nextTerms.add(combined);
          usedTerms.add(currentTerms[i]);
          usedTerms.add(currentTerms[j]);
        }
      }
    }

    // Terms that couldn't be combined are Prime Implicants
    currentTerms.forEach(t => {
      if (!usedTerms.has(t)) {
        primeImplicants.add(t);
      }
    });

    if (nextTerms.size === 0) break;
    currentTerms = Array.from(nextTerms);
  }

  // Simple optimization: Remove redundant Prime Implicants (simplified approach)
  // For a visual tool, displaying all PIs is often clearer than a heavily minimized confusing set,
  // but we sort them for consistency.
  return Array.from(primeImplicants).sort();
};

// --- Equation Generator ---

export const termsToEquation = (terms: string[], variableNames: string[]): string => {
  if (terms.length === 0) return "0 (False)";

  // Check for Always True
  if (terms.some(t => t.split('').every(c => c === '-'))) return "1 (True)";

  const parts = terms.map(term => {
    let part = "";
    for (let i = 0; i < term.length; i++) {
      if (term[i] === '1') {
        part += variableNames[i];
      } else if (term[i] === '0') {
        part += variableNames[i] + "'"; // using ' for NOT
      }
    }
    return part === "" ? "1" : part;
  });

  return parts.join(" + ");
};

// --- Circuit Generator ---

const generateId = () => Math.random().toString(36).substr(2, 9);

export const generateCircuitFromTerms = (
  numVars: number, 
  terms: string[], 
  startPos: { x: number, y: number }
): { nodes: CircuitNode[], wires: Wire[] } => {
  const nodes: CircuitNode[] = [];
  const wires: Wire[] = [];

  // Layout Constants
  const COL_Spacing = 180;
  const ROW_Spacing = 80;

  // 1. Create Input Switches (Column 0)
  const inputs: CircuitNode[] = [];
  const inputLabels = ['A', 'B', 'C', 'D'].slice(0, numVars);

  inputLabels.forEach((label, i) => {
    const node: CircuitNode = {
      id: generateId(),
      type: GateType.INPUT_SWITCH,
      position: { x: startPos.x, y: startPos.y + (i * ROW_Spacing) },
      width: 50,
      height: 50,
      inputs: [],
      state: false,
      label: label
    };
    inputs.push(node);
    nodes.push(node);
  });

  // 2. Create NOT Gates (Column 1) - Only if needed by terms
  // We strictly create NOTs based on the equation requirements.
  const notGates: Map<number, CircuitNode> = new Map(); // inputIndex -> NotGate
  const needsNot = new Array(numVars).fill(false);

  terms.forEach(term => {
    for(let i=0; i<term.length; i++) {
      if (term[i] === '0') needsNot[i] = true;
    }
  });

  inputs.forEach((inputNode, i) => {
    if (needsNot[i]) {
      const notNode: CircuitNode = {
        id: generateId(),
        type: GateType.NOT,
        position: { x: startPos.x + COL_Spacing, y: inputNode.position.y + 10 },
        width: COMPONENT_CONFIGS[GateType.NOT].width,
        height: COMPONENT_CONFIGS[GateType.NOT].height,
        inputs: [false],
        state: false,
        label: 'NOT'
      };
      nodes.push(notNode);
      notGates.set(i, notNode);

      wires.push({
        id: generateId(),
        sourceNodeId: inputNode.id,
        sourcePinIndex: 0,
        targetNodeId: notNode.id,
        targetPinIndex: 0,
        state: false
      });
    }
  });

  // 3. Create Product Terms (AND Gates)
  interface TermOutput {
    sourceNodeId: string;
    sourcePinIndex: number;
    yPosition: number;
  }

  const termOutputs: TermOutput[] = [];
  const AND_COL_X = startPos.x + (COL_Spacing * 2);

  terms.forEach((term, idx) => {
    // If term is all dashes ("---"), it's logic 1. 
    // Usually handled by logic before calling this, but if present:
    if (term === '-'.repeat(numVars) && terms.length > 1) return; 

    const connections: { nodeId: string, pinIndex: number, y: number }[] = [];

    for (let i = 0; i < term.length; i++) {
      const char = term[i];
      if (char === '1') {
        connections.push({ nodeId: inputs[i].id, pinIndex: 0, y: inputs[i].position.y });
      } else if (char === '0') {
        const notNode = notGates.get(i);
        if (notNode) connections.push({ nodeId: notNode.id, pinIndex: 0, y: notNode.position.y });
      }
    }

    if (connections.length === 0) {
       // Term is "1" (Always True)
       // We can represent this as a switch that defaults to ON, or ignore if part of a sum
    } else if (connections.length === 1) {
      // Direct connection (Single Variable Term)
      termOutputs.push({
        sourceNodeId: connections[0].nodeId,
        sourcePinIndex: connections[0].pinIndex,
        yPosition: connections[0].y
      });
    } else {
      // Create AND Gate (Product)
      const inputCount = connections.length;
      const height = (inputCount + 1) * PIN_SPACING;

      // Smart Positioning: Average Y of inputs
      const avgY = connections.reduce((sum, c) => sum + c.y, 0) / inputCount;

      // Collision avoidance with previous gates
      let yPos = avgY - (height / 2);
      if (idx > 0) {
        const prevY = termOutputs[termOutputs.length - 1]?.yPosition || -1000;
        // Minimal vertical distance check
        if (yPos < prevY + 60) {
           yPos = prevY + 60;
        }
      }

      const andNode: CircuitNode = {
        id: generateId(),
        type: GateType.AND,
        position: { x: AND_COL_X, y: yPos },
        width: COMPONENT_CONFIGS[GateType.AND].width,
        height: height,
        inputs: new Array(inputCount).fill(false),
        state: false,
        label: 'AND'
      };

      nodes.push(andNode);

      connections.forEach((conn, pinIdx) => {
        wires.push({
          id: generateId(),
          sourceNodeId: conn.nodeId,
          sourcePinIndex: 0,
          targetNodeId: andNode.id,
          targetPinIndex: pinIdx,
          state: false
        });
      });

      termOutputs.push({
        sourceNodeId: andNode.id,
        sourcePinIndex: 0,
        yPosition: yPos + (height / 2)
      });
    }
  });

  // 4. Create Sum Term (OR Gate)
  const OR_COL_X = AND_COL_X + COL_Spacing + 40;
  let finalOutputNodeId = '';
  let finalOutputPinIdx = 0;
  let lampY = startPos.y;

  if (termOutputs.length === 0) {
     // No terms = False. Lamp unconnected.
  } else if (termOutputs.length === 1) {
    // Single term = Direct output
    finalOutputNodeId = termOutputs[0].sourceNodeId;
    finalOutputPinIdx = termOutputs[0].sourcePinIndex;
    lampY = termOutputs[0].yPosition;
  } else {
    // Multiple terms = OR Gate
    const inputCount = termOutputs.length;
    const height = (inputCount + 1) * PIN_SPACING;
    const avgY = termOutputs.reduce((sum, t) => sum + t.yPosition, 0) / inputCount;

    const orNode: CircuitNode = {
      id: generateId(),
      type: GateType.OR,
      position: { x: OR_COL_X, y: avgY - (height/2) },
      width: COMPONENT_CONFIGS[GateType.OR].width,
      height: height,
      inputs: new Array(inputCount).fill(false),
      state: false,
      label: 'OR'
    };
    nodes.push(orNode);
    finalOutputNodeId = orNode.id;
    finalOutputPinIdx = 0;
    lampY = avgY;

    termOutputs.forEach((term, i) => {
      wires.push({
        id: generateId(),
        sourceNodeId: term.sourceNodeId,
        sourcePinIndex: term.sourcePinIndex,
        targetNodeId: orNode.id,
        targetPinIndex: i,
        state: false
      });
    });
  }

  // 5. Output Lamp
  const lampNode: CircuitNode = {
    id: generateId(),
    type: GateType.OUTPUT_LAMP,
    position: { x: OR_COL_X + 100, y: lampY - 25 }, 
    width: 50,
    height: 50,
    inputs: [false],
    state: false,
    label: 'Q'
  };
  nodes.push(lampNode);

  if (finalOutputNodeId) {
    wires.push({
      id: generateId(),
      sourceNodeId: finalOutputNodeId,
      sourcePinIndex: finalOutputPinIdx,
      targetNodeId: lampNode.id,
      targetPinIndex: 0,
      state: false
    });
  }

  return { nodes, wires };
};

// Wrapper for backward compatibility / direct calls
export const generateCircuitFromTruthTable = (
    numVars: number, 
    truthTable: boolean[], 
    startPos: { x: number, y: number }
  ) => {
    const minterms = truthTable
      .map((val, idx) => val ? idx : -1)
      .filter(idx => idx !== -1);

    const terms = solveQuineMcCluskey(numVars, minterms);
    return generateCircuitFromTerms(numVars, terms, startPos);
  };

import React, { useState, useEffect } from 'react';
import { X, Wand2, RefreshCw, Calculator } from 'lucide-react';
import { solveQuineMcCluskey, termsToEquation } from '../services/quineMcCluskey';

interface KarnaughModalProps {
  isOpen: boolean;
  onClose: () => void;
  onGenerate: (numVars: number, truthTable: boolean[]) => void;
}

export const KarnaughModal: React.FC<KarnaughModalProps> = ({ isOpen, onClose, onGenerate }) => {
  const [numVars, setNumVars] = useState<number>(3);
  const [truthTable, setTruthTable] = useState<boolean[]>([]);
  const [equation, setEquation] = useState<string>("0");

  // Initialize truth table when numVars changes
  useEffect(() => {
    setTruthTable(new Array(Math.pow(2, numVars)).fill(false));
  }, [numVars]);

  // Update Equation when TruthTable changes
  useEffect(() => {
    const minterms = truthTable
      .map((val, idx) => val ? idx : -1)
      .filter(idx => idx !== -1);

    const terms = solveQuineMcCluskey(numVars, minterms);
    const variableNames = ['A', 'B', 'C', 'D'].slice(0, numVars);
    const eq = termsToEquation(terms, variableNames);
    setEquation(eq);
