          >
            <X size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 flex-1 overflow-y-auto flex gap-6 flex-col md:flex-row">

          {/* Settings & Preview */}
          <div className="w-full md:w-1/3 flex flex-col gap-6">
